package com.deadmantoolkit;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Anonymous, stable id for one game account: a salted SHA-256 of RuneLite's account hash. It lets the server keep
 * one account's trades together without ever learning the account hash or the player's name.
 */
final class AccountId
{
	/**
	 * Part of the id's format, so it keeps the plugin's first name: changing it would give every account a new id (the
	 * server's per-account data and trust would start over).
	 */
	static final String PREFIX = "deadman-ge-tracker:";
	private static final char[] HEX = "0123456789abcdef".toCharArray();

	private AccountId()
	{
	}

	/** Lowercase hex SHA-256 of {@code "deadman-ge-tracker:" + accountHash} (UTF-8): always 64 characters. */
	static String of(long accountHash)
	{
		MessageDigest md;
		try
		{
			md = MessageDigest.getInstance("SHA-256");
		}
		catch (NoSuchAlgorithmException e)
		{
			// Every Java platform is required to provide SHA-256.
			throw new IllegalStateException(e);
		}
		byte[] digest = md.digest((PREFIX + accountHash).getBytes(StandardCharsets.UTF_8));
		char[] out = new char[digest.length * 2];
		for (int i = 0; i < digest.length; i++)
		{
			out[i * 2] = HEX[(digest[i] >> 4) & 0xf];
			out[i * 2 + 1] = HEX[digest[i] & 0xf];
		}
		return new String(out);
	}
}

package com.deadmantoolkit;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.IntFunction;
import lombok.Value;

/**
 * One of the player's own GE offers that is still open (active and not fully filled), as an immutable snapshot for
 * the panel. Built on the client thread from {@link OfferTracker}'s slots.
 */
@Value
public class ActiveOffer
{
	int slot;
	String offerKey;
	int itemId;
	String name;
	boolean buy;
	/** Offer price per item. */
	long price;
	int totalQty;
	int filled;
	/** When the offer was placed (unix s). */
	long placedAt;

	/**
	 * The open offers in slot order.
	 *
	 * @param names item names by id (on the client thread, the item manager)
	 */
	static List<ActiveOffer> fromTracker(OfferTracker t, IntFunction<String> names)
	{
		List<ActiveOffer> out = new ArrayList<>();
		for (int slot = 0; slot < OfferTracker.SLOTS; slot++)
		{
			OfferTracker.SlotState s = t.getSlot(slot);
			if (s == null || s.getStatus() != OfferTracker.Status.ACTIVE || s.getSold() >= s.getTotalQty())
			{
				continue;
			}
			out.add(new ActiveOffer(slot, s.getOfferKey(), s.getItemId(), names.apply(s.getItemId()), s.isBuy(),
				s.getPrice(), s.getTotalQty(), s.getSold(), s.getPlacedAt()));
		}
		return Collections.unmodifiableList(out);
	}
}

package com.deadmantoolkit;

import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Decides when an offer alert may notify (pure apart from its own state; thread safe). Only a change into UNDERCUT or
 * OUTBID notifies, the same offer and flag at most once per {@link #COOLDOWN_MS}, and any two alerts at least
 * {@link #GLOBAL_GAP_MS} apart.
 */
final class AlertGate
{
	static final long COOLDOWN_MS = 30 * 60_000L;
	static final long GLOBAL_GAP_MS = 60_000L;

	/** The last flag seen per offer key. */
	private final Map<String, OfferWatch.Flag> lastFlag = new HashMap<>();
	/** When "offerKey|flag" last notified (epoch ms). */
	private final Map<String, Long> lastFired = new HashMap<>();
	private long lastAny = Long.MIN_VALUE;

	/**
	 * Record the offer's current flag and say whether to notify now.
	 *
	 * @param nowMs epoch ms
	 */
	synchronized boolean shouldNotify(String offerKey, OfferWatch.Flag flag, long nowMs)
	{
		OfferWatch.Flag prev = lastFlag.put(offerKey, flag);
		if ((flag != OfferWatch.Flag.UNDERCUT && flag != OfferWatch.Flag.OUTBID) || flag == prev)
		{
			return false;
		}
		String key = offerKey + "|" + flag;
		Long fired = lastFired.get(key);
		if (fired != null && nowMs - fired < COOLDOWN_MS)
		{
			// Already told recently; this change is used up.
			return false;
		}
		if (lastAny != Long.MIN_VALUE && nowMs - lastAny < GLOBAL_GAP_MS)
		{
			// Too soon after another alert: forget we saw it, so the next check (a minute later) tries again.
			restore(offerKey, prev);
			return false;
		}
		lastFired.put(key, nowMs);
		lastAny = nowMs;
		return true;
	}

	/** Forget offers that are no longer open. */
	synchronized void retain(Collection<String> openOfferKeys)
	{
		Set<String> keep = new HashSet<>(openOfferKeys);
		lastFlag.keySet().retainAll(keep);
		lastFired.keySet().removeIf(k -> !keep.contains(k.substring(0, k.lastIndexOf('|'))));
	}

	private void restore(String offerKey, OfferWatch.Flag prev)
	{
		if (prev == null)
		{
			lastFlag.remove(offerKey);
		}
		else
		{
			lastFlag.put(offerKey, prev);
		}
	}
}

package com.deadmantoolkit;

import java.time.Duration;
import java.time.Instant;
import java.util.Optional;
import java.util.function.Consumer;
import java.util.function.Supplier;
import net.runelite.api.events.CommandExecuted;
import net.runelite.client.eventbus.Subscribe;

/**
 * The {@code ::breach} developer command ({@link BreachPreview}). Registered on the event bus only in developer mode
 * (RuneLite's {@code @Named("developerMode")}); normal installs never see it. Runs on the client thread.
 */
final class BreachCommands
{
	/** What the preview drives. */
	interface Target
	{
		/** The breach timer's clock offset now (zero when off). */
		Duration offset();

		/** Shift the breach timer's clock by {@code offset} and drop any correction from a game message. */
		void preview(Duration offset);

		/** Feed the breach message parser as if the game had sent {@code gameText}. */
		void gameMessage(String gameText);
	}

	private final Target target;
	/** Shows a line in the local chatbox only. */
	private final Consumer<String> chat;
	/** The real clock. */
	private final Supplier<Instant> clock;

	BreachCommands(Target target, Consumer<String> chat, Supplier<Instant> clock)
	{
		this.target = target;
		this.chat = chat;
		this.clock = clock;
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted e)
	{
		if (BreachPreview.COMMAND.equalsIgnoreCase(e.getCommand()))
		{
			run(e.getArguments());
		}
	}

	/** Run {@code ::breach <args>}; also used by the panel's dev tools buttons. Client thread. */
	void run(String[] args)
	{
		Optional<BreachPreview.Command> parsed = BreachPreview.parse(args);
		if (!parsed.isPresent())
		{
			chat.accept(BreachPreview.USAGE);
			return;
		}
		BreachPreview.Command c = parsed.get();
		if (c.getAction() == BreachPreview.Action.MSG)
		{
			target.gameMessage(BreachPreview.gameMessage(c.getHours(), c.getMinutes()));
		}
		else
		{
			target.preview(BreachPreview.offset(c.getAction(), clock.get(), target.offset()));
		}
		chat.accept(BreachPreview.confirmation(c));
	}
}

package com.deadmantoolkit;

import java.time.Duration;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

/**
 * Reads the game message "The next breach will appear in X hour(s), Y minute(s)." Accepts singular or plural,
 * a missing hours or minutes part, "and" instead of a comma, colour tags, and "less than a minute".
 */
public final class BreachMessage
{
	private static final Pattern PATTERN = Pattern.compile(
		"next breach will appear in\\s+(?:(\\d+)\\s*hours?)?\\s*,?\\s*(?:and\\s+)?(?:(\\d+)\\s*minutes?)?",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern LESS_THAN_A_MINUTE = Pattern.compile(
		"next breach will appear in\\s+less than a minute", Pattern.CASE_INSENSITIVE);
	/** Breaches are at most a week apart; anything longer isn't a countdown to trust. */
	private static final Duration MAX = Duration.ofDays(8);

	private BreachMessage()
	{
	}

	/** The time until the next breach, or empty when {@code raw} isn't that message. */
	public static Optional<Duration> parse(String raw)
	{
		if (raw == null)
		{
			return Optional.empty();
		}
		String text = Text.removeTags(raw);
		if (LESS_THAN_A_MINUTE.matcher(text).find())
		{
			return Optional.of(Duration.ofMinutes(1));
		}
		Matcher m = PATTERN.matcher(text);
		if (!m.find() || (m.group(1) == null && m.group(2) == null))
		{
			return Optional.empty();
		}
		try
		{
			long hours = m.group(1) == null ? 0 : Long.parseLong(m.group(1));
			long minutes = m.group(2) == null ? 0 : Long.parseLong(m.group(2));
			Duration d = Duration.ofHours(hours).plusMinutes(minutes);
			return d.compareTo(MAX) > 0 ? Optional.empty() : Optional.of(d);
		}
		catch (NumberFormatException | ArithmeticException e)
		{
			// More digits than a long holds: not a real message.
			return Optional.empty();
		}
	}
}

package com.deadmantoolkit;

import java.time.Duration;
import java.time.Instant;
import java.util.Locale;
import java.util.Optional;
import lombok.Value;

/**
 * Developer-mode breach preview (pure): parses {@code ::breach} commands and works out how far to shift the breach
 * timer's clock so the real schedule is at the requested point. Only the breach timer's clock and schedule input
 * change; the banner then runs through its phases on its own. Never registered outside developer mode.
 * <ul>
 * <li>{@code ::breach soon}: the next breach starts in 2 minutes;</li>
 * <li>{@code ::breach active}: a breach started just now;</li>
 * <li>{@code ::breach despawn}: spawning ended just now;</li>
 * <li>{@code ::breach msg <h> <m>}: as if the game said "The next breach will appear in h hour(s), m minute(s)";</li>
 * <li>{@code ::breach off}: the real clock and schedule again.</li>
 * </ul>
 */
public final class BreachPreview
{
	public static final String COMMAND = "breach";
	public static final String USAGE = "Usage: ::breach soon | active | despawn | msg <hours> <minutes> | off";
	/** "soon" starts the next breach this long from now. */
	static final Duration SOON = Duration.ofMinutes(2);

	private BreachPreview()
	{
	}

	public enum Action
	{
		SOON, ACTIVE, DESPAWN, MSG, OFF
	}

	@Value
	public static class Command
	{
		Action action;
		/** msg only. */
		int hours;
		int minutes;
	}

	/** The command for {@code ::breach <args>}, or empty when the arguments aren't one. */
	public static Optional<Command> parse(String[] args)
	{
		if (args == null || args.length == 0 || args[0] == null)
		{
			return Optional.empty();
		}
		String a = args[0].trim().toLowerCase(Locale.ROOT);
		switch (a)
		{
			case "soon":
				return args.length == 1 ? Optional.of(new Command(Action.SOON, 0, 0)) : Optional.empty();
			case "active":
				return args.length == 1 ? Optional.of(new Command(Action.ACTIVE, 0, 0)) : Optional.empty();
			case "despawn":
				return args.length == 1 ? Optional.of(new Command(Action.DESPAWN, 0, 0)) : Optional.empty();
			case "off":
				return args.length == 1 ? Optional.of(new Command(Action.OFF, 0, 0)) : Optional.empty();
			case "msg":
			{
				if (args.length != 3)
				{
					return Optional.empty();
				}
				Integer h = smallInt(args[1]), m = smallInt(args[2]);
				return h == null || m == null ? Optional.empty() : Optional.of(new Command(Action.MSG, h, m));
			}
			default:
				return Optional.empty();
		}
	}

	/** 0..999, or null. */
	private static Integer smallInt(String s)
	{
		if (s == null || !s.trim().matches("\\d{1,3}"))
		{
			return null;
		}
		return Integer.parseInt(s.trim());
	}

	/**
	 * The offset to add to the real clock so that, at {@code realNow}, the real schedule is where the action asks:
	 * 2 minutes before a start (SOON), at a start (ACTIVE) or at the end of its spawn phase (DESPAWN). Zero for OFF; MSG
	 * keeps the current offset (it only feeds the message parser).
	 */
	public static Duration offset(Action action, Instant realNow, Duration current)
	{
		switch (action)
		{
			case SOON:
				return Duration.between(realNow, BreachSchedule.nextStart(realNow).minus(SOON));
			case ACTIVE:
				return Duration.between(realNow, BreachSchedule.nextStart(realNow));
			case DESPAWN:
				return Duration.between(realNow, BreachSchedule.nextStart(realNow).plus(BreachSchedule.SPAWN));
			case OFF:
				return Duration.ZERO;
			default:
				return current == null ? Duration.ZERO : current;
		}
	}

	/** The game message for {@code ::breach msg h m}, in the game's wording. */
	public static String gameMessage(int hours, int minutes)
	{
		return "The next breach will appear in " + hours + (hours == 1 ? " hour" : " hours") + ", " + minutes
			+ (minutes == 1 ? " minute" : " minutes") + ".";
	}

	/** The local chat confirmation for a command. */
	public static String confirmation(Command c)
	{
		switch (c.getAction())
		{
			case SOON:
				return "Breach preview: next breach starts in 2 minutes.";
			case ACTIVE:
				return "Breach preview: a breach started just now.";
			case DESPAWN:
				return "Breach preview: spawning ended just now; bosses despawn in 30 minutes.";
			case MSG:
				return "Breach preview: fed \"" + gameMessage(c.getHours(), c.getMinutes()) + "\"";
			default:
				return "Breach preview off: real clock and schedule.";
		}
	}
}

package com.deadmantoolkit;

import java.time.DayOfWeek;
import java.time.Duration;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import lombok.Value;

/**
 * The permanent Deadman breach schedule: every Saturday and Sunday at 02:00, 06:00, 10:00, 14:00, 18:00 and 22:00
 * UTC (12 a week). Bosses spawn for about 15 minutes; any left alive despawn about 30 minutes after that.
 * Pure, all in UTC.
 */
public final class BreachSchedule
{
	static final int[] HOURS = {2, 6, 10, 14, 18, 22};
	public static final Duration SPAWN = Duration.ofMinutes(15);
	public static final Duration DESPAWN = Duration.ofMinutes(30);
	/** From the start of a breach to the end of its despawn phase. */
	static final Duration TOTAL = SPAWN.plus(DESPAWN);
	/** A corrected time this close to a scheduled start is taken to be that start (the game rounds to minutes). */
	static final Duration SNAP = Duration.ofMinutes(2);
	/** More than a week, so a search always finds a start. */
	private static final int SEARCH_DAYS = 8;

	public enum Phase
	{
		/** Bosses are spawning; {@link State#getAt()} is when spawning ends. */
		ACTIVE,
		/** Spawning is over; {@link State#getAt()} is when the remaining bosses despawn. */
		DESPAWN,
		/** {@link State#getAt()} is when the next breach starts. */
		UPCOMING,
	}

	@Value
	public static class State
	{
		Phase phase;
		Instant at;
	}

	private BreachSchedule()
	{
	}

	static boolean isBreachDay(DayOfWeek d)
	{
		return d == DayOfWeek.SATURDAY || d == DayOfWeek.SUNDAY;
	}

	/** The earliest scheduled start strictly after {@code now}. */
	static Instant nextStart(Instant now)
	{
		LocalDate day = now.atZone(ZoneOffset.UTC).toLocalDate();
		for (int i = 0; i <= SEARCH_DAYS; i++, day = day.plusDays(1))
		{
			if (!isBreachDay(day.getDayOfWeek()))
			{
				continue;
			}
			for (int h : HOURS)
			{
				Instant start = day.atTime(h, 0).toInstant(ZoneOffset.UTC);
				if (start.isAfter(now))
				{
					return start;
				}
			}
		}
		throw new IllegalStateException("no breach within a week of " + now);
	}

	/** The latest scheduled start at or before {@code now}. */
	static Instant lastStart(Instant now)
	{
		LocalDate day = now.atZone(ZoneOffset.UTC).toLocalDate();
		for (int i = 0; i <= SEARCH_DAYS; i++, day = day.minusDays(1))
		{
			if (!isBreachDay(day.getDayOfWeek()))
			{
				continue;
			}
			for (int k = HOURS.length - 1; k >= 0; k--)
			{
				Instant start = day.atTime(HOURS[k], 0).toInstant(ZoneOffset.UTC);
				if (!start.isAfter(now))
				{
					return start;
				}
			}
		}
		throw new IllegalStateException("no breach within a week before " + now);
	}

	/**
	 * Where we are in the breach cycle.
	 *
	 * @param correction a breach start reported by the game (see {@link #correct}), or null. It replaces the
	 *                   scheduled next start while in the future, and drives the phases for 45 minutes after it.
	 */
	public static State state(Instant now, Instant correction)
	{
		if (correction != null)
		{
			State s = phaseOf(correction, now);
			if (s != null)
			{
				return s;
			}
		}
		State s = phaseOf(lastStart(now), now);
		if (s != null)
		{
			return s;
		}
		Instant next = correction != null && correction.isAfter(now) ? correction : nextStart(now);
		return new State(Phase.UPCOMING, next);
	}

	/** The active or despawn phase of a breach that started at {@code start}, or null outside them. */
	private static State phaseOf(Instant start, Instant now)
	{
		if (now.isBefore(start))
		{
			return null;
		}
		Instant spawnEnd = start.plus(SPAWN);
		if (now.isBefore(spawnEnd))
		{
			return new State(Phase.ACTIVE, spawnEnd);
		}
		Instant despawnEnd = start.plus(TOTAL);
		if (now.isBefore(despawnEnd))
		{
			return new State(Phase.DESPAWN, despawnEnd);
		}
		return null;
	}

	/**
	 * The next breach start from the game's "next breach will appear in ..." message seen at {@code now}. The game
	 * only gives minutes, so a time within {@link #SNAP} of a scheduled start is that start; anything else (the
	 * schedule changed) is trusted as reported.
	 */
	public static Instant correct(Instant now, Duration until)
	{
		Instant predicted = now.plus(until);
		Instant scheduled = nextStart(predicted.minus(SNAP).minusSeconds(1));
		if (Duration.between(predicted, scheduled).abs().compareTo(SNAP) <= 0)
		{
			return scheduled;
		}
		return predicted;
	}
}

package com.deadmantoolkit;

import java.time.Duration;
import java.time.Instant;
import java.time.format.DateTimeParseException;

/**
 * When the 4-hour GE buy limit of an item resets, as RuneLite's own Grand Exchange plugin records it. Pure.
 * <p>
 * That plugin keeps, in the current account's RS-profile config (group {@value #CONFIG_GROUP}, key
 * {@code buylimit_<itemId>}), an Instant (ISO text): set to four hours after a buy when no future reset time exists,
 * so it is when that item's buy limit window resets. Only read for the current profile, on world 345.
 */
public final class BuyLimitReset
{
	public static final String CONFIG_GROUP = "grandexchange";
	static final String KEY_PREFIX = "buylimit_";
	/** RuneLite's own group, where plugins' on/off state lives (key: the plugin class name in lower case). */
	public static final String RUNELITE_GROUP = "runelite";
	public static final String GE_PLUGIN_KEY = "grandexchangeplugin";
	/** The GE plugin's "Enable GE limit reset timer" setting (on by default). */
	public static final String CORE_RESET_KEY = "enableGELimitReset";

	private BuyLimitReset()
	{
	}

	/**
	 * Whether RuneLite's own Grand Exchange plugin already shows the buy limit reset on the offer setup screen ("Buy
	 * limit: 70 (2:14)"): the plugin is on (it is by default) and its reset timer setting is on (also the default).
	 * Then the DMM line leaves the reset out and keeps its room for the market numbers.
	 *
	 * @param gePluginEnabled the {@value #RUNELITE_GROUP}.{@value #GE_PLUGIN_KEY} value, or null (default: on)
	 * @param resetEnabled    the {@value #CONFIG_GROUP}.{@value #CORE_RESET_KEY} value, or null (default: on)
	 */
	public static boolean coreShowsReset(String gePluginEnabled, String resetEnabled)
	{
		return !"false".equalsIgnoreCase(trim(gePluginEnabled)) && !"false".equalsIgnoreCase(trim(resetEnabled));
	}

	/**
	 * The buy limit part of the GE offer setup's DMM line: the time left ({@link #remaining}) on a buy offer, unless
	 * RuneLite's GE plugin already shows it there ({@link #coreShowsReset}); else null.
	 */
	public static String forGeLine(boolean buyOffer, String gePluginEnabled, String resetEnabled, Instant reset,
		Instant now)
	{
		if (!buyOffer || coreShowsReset(gePluginEnabled, resetEnabled))
		{
			return null;
		}
		return remaining(reset, now);
	}

	private static String trim(String s)
	{
		return s == null ? null : s.trim();
	}

	/** The config key for an item's reset time. */
	public static String key(int itemId)
	{
		return KEY_PREFIX + itemId;
	}

	/** The stored value as an Instant (ISO text, or epoch milliseconds), or null when missing or unreadable. */
	public static Instant parse(String value)
	{
		if (value == null)
		{
			return null;
		}
		String v = value.trim();
		if (v.isEmpty())
		{
			return null;
		}
		try
		{
			if (v.chars().allMatch(Character::isDigit))
			{
				return Instant.ofEpochMilli(Long.parseLong(v));
			}
			return Instant.parse(v);
		}
		catch (DateTimeParseException | NumberFormatException | ArithmeticException ex)
		{
			return null;
		}
	}

	/** {@code reset} when it is still in the future at {@code now}, else null (no limit window running). */
	public static Instant future(Instant reset, Instant now)
	{
		return reset != null && reset.isAfter(now) ? reset : null;
	}

	/**
	 * How long until the reset, e.g. "2h 14m", "14m", "<1m"; null when it isn't in the future. Rounded down, like a
	 * countdown.
	 */
	public static String remaining(Instant reset, Instant now)
	{
		if (future(reset, now) == null)
		{
			return null;
		}
		long minutes = Duration.between(now, reset).getSeconds() / 60;
		if (minutes <= 0)
		{
			return "<1m";
		}
		long h = minutes / 60, m = minutes % 60;
		return h > 0 ? h + "h " + m + "m" : m + "m";
	}
}

package com.deadmantoolkit;

import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.Overlay;

/**
 * Never registered with the OverlayManager and never drawn. It only carries the plugin in an OverlayMenuClicked
 * event, which RuneLite's config plugin answers by opening this plugin's configuration page (the panel's gear button).
 */
class ConfigLinkOverlay extends Overlay
{
	ConfigLinkOverlay(Plugin plugin)
	{
		super(plugin);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		return null;
	}
}

package com.deadmantoolkit;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
