	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged e)
	{
		GrandExchangeOffer offer = e.getOffer();
		// The client sends a burst of EMPTY offers before login completes; they don't mean anything.
		if (offer.getState() == GrandExchangeOfferState.EMPTY && client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		OfferTracker t = tracker;
		if (!isTrackedWorld() || !ensureProfileLoaded(t))
		{
			return;
		}

		boolean late = client.getGameState() != GameState.LOGGED_IN
			|| client.getTickCount() <= lastLoginTick + LOGIN_BURST_TICKS;
		int slot = e.getSlot();
		List<TradeEvent> events = t.update(slot, OfferTracker.Snapshot.of(offer), late, now(), client.getWorld());

		store.saveSlot(t, slot);
		if (!events.isEmpty())
		{
			store.saveCompleted(t);
			record(events);
		}
		publishOffers(t);
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded e)
	{
		if (e.getGroupId() == InterfaceID.GE_HISTORY)
		{
			log.debug("GE history interface opened (tracked world: {})", isTrackedWorld());
			if (isTrackedWorld())
			{
				historyReadTicks = HISTORY_READ_TICKS;
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		onTrackedWorld = client.getGameState() == GameState.LOGGED_IN && isTrackedWorld();
		if (loginCheckPending)
		{
			loginCheckPending = false;
			afterLogin();
			WorldEventsController we = worldEvents;
			if (we != null)
			{
				we.onLoggedIn();
			}
		}
		if (client.getTickCount() % WORLD_EVENT_TICKS == 0)
		{
			WorldEventsController we = worldEvents;
			if (we != null)
			{
				we.tick();
			}
		}

		if (historyReadTicks > 0)
		{
			historyReadTicks--;
			List<GeHistory.Entry> entries = readHistoryWidget();
			if (entries != null && !entries.isEmpty())
			{
				historyReadTicks = 0;
				processHistory(entries, tracker);
			}
			else if (historyReadTicks == 0)
			{
				if (entries != null)
				{
					// Still shown with no rows after the whole wait: this account has no GE History.
					markEmptyHistoryImported(tracker);
				}
				else
				{
					log.debug("GE history: gave up, no rows parsed");
				}
			}
		}

		OfferTracker t = tracker;
		if (client.getTickCount() % SEEN_INTERVAL_TICKS == 0 && client.getTickCount() > lastLoginTick + LOGIN_BURST_TICKS
			&& isTrackedWorld() && ensureProfileLoaded(t))
		{
			// Offers we're watching live haven't changed as of now. If one fills after we log out, the server knows
			// it happened after this point when pairing it with the counterparty's report.
			for (int slot : t.markSeen(now()))
			{
				store.saveSlot(t, slot);
			}
		}

		if (nextOpenOffersTick >= 0 && client.getTickCount() >= nextOpenOffersTick)
		{
			nextOpenOffersTick = client.getTickCount() + OPEN_OFFERS_INTERVAL_TICKS;
			TradeUploader up = uploader;
			if (up != null && isTrackedWorld() && ensureProfileLoaded(t) && shareEnabled())
			{
				up.setOpenOffers(client.getWorld(), accountId(), buildOpenOffers(t, up));
			}
		}
	}

	/**
	 * First tick after a login (or after starting while logged in): tell the panel whether this account's GE History
	 * was imported, and send the one-time chat hint. Client thread.
	 */
	private void afterLogin()
	{
		if (!isTrackedWorld() || !ensureProfileLoaded(tracker))
		{
			announceAccount(null);
			return;
		}
		Boolean hintShown = configManager.getConfiguration(DeadmanToolKitConfig.GROUP,
			DeadmanToolKitConfig.KEY_HINT_SHOWN, Boolean.class);
		if (Boolean.TRUE.equals(hintShown))
		{
			return;
		}
		if (Onboarding.shouldShowChatHint(config.connected(), store.historyImported()))
		{
			// Local only: shown in this client's chatbox, never sent to the game.
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(new ChatMessageBuilder()
					.append(ChatColorType.HIGHLIGHT)
					.append(CHAT_HINT)
					.build())
				.build());
		}
		// Once per install, whether or not it was needed.
		configManager.setConfiguration(DeadmanToolKitConfig.GROUP, DeadmanToolKitConfig.KEY_HINT_SHOWN, true);
	}

	/**
	 * Send the panel the import state of the account whose profile is loaded, or null when logged out / off world
	 * 345. Client thread.
	 */
	private void announceAccount(String profile)
	{
		if (profile == null)
		{
			publishOffers(null);
		}
		Boolean imported = profile == null ? null : store.historyImported();
		announcedProfile = profile;
		ProfitStore ps = profit;
		String acct = profile == null ? null : accountId();
		if (ps != null && acct != null)
		{
			// Switch to this account's profit file (one small read) and show its numbers.
			executor.execute(() -> ps.load(acct));
		}
		SwingUtilities.invokeLater(() ->
		{
			DeadmanToolKitPanel p = panel;
			if (p != null)
			{
				p.setAccountState(imported, profile);
			}
		});
	}

	/** The hashed id of the logged-in account ({@link AccountId}), or null when unknown. Client thread. */
	private String accountId()
	{
		long hash = client.getAccountHash();
		if (hash == -1)
		{
			return null;
		}
		if (hash != cachedAccountHash || cachedAccountId == null)
		{
			cachedAccountHash = hash;
			cachedAccountId = AccountId.of(hash);
		}
		return cachedAccountId;
	}

	/* ------------------------------------------------------- GE history */

	/**
	 * @return the parsed rows; an empty list when the list is shown but has no rows at all; null when the list is
	 * missing or hidden, or has rows the parser couldn't read (neither may be taken as an empty history)
	 */
	private List<GeHistory.Entry> readHistoryWidget()
	{
		Widget list = client.getWidget(InterfaceID.GeHistory.LIST);
		if (list == null || list.isHidden())
		{
			log.debug("GE history list widget {}", list == null ? "missing" : "hidden");
			return null;
		}
		Widget[] children = list.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			Widget[] statics = list.getStaticChildren();
			Widget[] nested = list.getNestedChildren();
			log.debug("GE history list has no dynamic children (static: {}, nested: {})",
				statics == null ? 0 : statics.length, nested == null ? 0 : nested.length);
			return Collections.emptyList();
		}
		List<GeHistory.Cell> cells = new ArrayList<>(children.length);
		for (Widget w : children)
		{
			int itemId = w.getItemId() > 0 ? itemManager.canonicalize(w.getItemId()) : -1;
			cells.add(new GeHistory.Cell(w.getText(), itemId, w.getItemQuantity()));
		}
		List<GeHistory.Entry> entries = GeHistory.parse(cells);
		log.debug("Read {} GE history entries from {} widgets", entries.size(), children.length);
		if (entries.isEmpty())
		{
			if (log.isDebugEnabled())
			{
				// Dump the layout so the parser can be fixed if the interface differs from what we expect.
				for (int i = 0; i < Math.min(children.length, 36); i++)
				{
					Widget w = children[i];
					log.debug("  history[{}] type={} item={} qty={} text='{}'", i, w.getType(), w.getItemId(), w.getItemQuantity(), w.getText());
				}
			}
			return null;
		}
		return entries;
	}

	/**
	 * The GE History list stayed empty: there is nothing to import, but the account has been through the import, so
	 * the welcome card stops asking for it. Only the first time; a real import later still adds its rows.
	 */
	private void markEmptyHistoryImported(OfferTracker t)
	{
		if (!ensureProfileLoaded(t) || store.historyImported())
		{
			return;
		}
		store.saveHistory(Collections.emptyList());
		log.debug("GE history: empty, marked as imported");
		SwingUtilities.invokeLater(() ->
		{
			DeadmanToolKitPanel p = panel;
			if (p != null)
			{
				p.onHistoryImported(0);
			}
		});
	}

	private void processHistory(List<GeHistory.Entry> entries, OfferTracker t)
	{
		if (!ensureProfileLoaded(t))
		{
			return;
		}
		List<String> current = new ArrayList<>(entries.size());
		entries.forEach(en -> current.add(en.signature()));
		List<String> previous = store.loadHistory();
		boolean wasImported = store.historyImported();
		int fresh = GeHistory.countNew(previous, current);

		long ts = now();
		int world = client.getWorld();
		List<TradeEvent> events = GeHistory.newEvents(entries, fresh, t::consumeCompleted, ts, world,
			() -> "hist:" + UUID.randomUUID());
		// Rows for trades already imported from RuneLite's GE history (each used once).
		List<String> recent = store.loadRuneLiteRecent();
		if (!recent.isEmpty() && events.removeIf(ev -> RuneLiteImport.consumeRecent(recent, ev)))
		{
			store.saveRuneLiteRecent(recent);
		}

		store.saveHistory(current);
		store.saveCompleted(t);
		log.debug("GE history: {} rows, {} new, {} not seen live", entries.size(), fresh, events.size());
		record(events);
		if (!wasImported)
		{
			int added = events.size();
			SwingUtilities.invokeLater(() ->
			{
				DeadmanToolKitPanel p = panel;
				if (p != null)
				{
					p.onHistoryImported(added);
				}
			});
		}
	}

	/* ---------------------------------------------------------- output */

	/** Record events just observed (client thread): My trades, upload, local log and profit. */
	private void record(List<TradeEvent> raw)
	{
		if (raw.isEmpty())
		{
			return;
		}
		List<TradeEvent> events = new ArrayList<>(raw.size());
		for (TradeEvent ev : raw)
		{
			events.add(withName(ev));
		}
		myTrades.addNewest(events);
		notifyMyTradesChanged();
		persist(events, accountId(), false);
	}

	/**
	 * Upload (when connected and sharing), append to the local log (when on; each event to the file of its own month)
	 * and count for profit, in that order on the executor. Client thread.
	 *
	 * @param older the events are older than ones already counted (an import): profit is recounted from the log in
	 *              time order (when they all went into it), so they count as the cost basis of later sells
	 */
	private void persist(List<TradeEvent> events, String acct, boolean older)
	{
		TradeUploader up = uploader;
		if (up != null && shareEnabled())
		{
			boolean fill = false;
			for (TradeEvent ev : events)
			{
				up.add(ev, acct);
				queueItemInfo(up, ev.getItemId());
				fill |= TradeEvent.FILL.equals(ev.getKind());
			}
			if (fill)
			{
				requestFlushSoon();
			}
		}
		Map<YearMonth, List<String>> lines = null;
		if (config.saveLocalLog())
		{
			// Live events of one update share a month; imported ones carry their own (older) times.
			lines = new TreeMap<>();
			for (TradeEvent ev : events)
			{
				lines.computeIfAbsent(LocalTradeLog.monthOf(ev.getTs()), k -> new ArrayList<>())
					.add(gson.toJson(logLine(gson, ev, acct)));
			}
		}
		ProfitStore ps = profit;
		Map<YearMonth, List<String>> logLines = lines;
		executor.execute(() -> appendAndApply(ps, logLines, acct, events, older));
	}

	/**
	 * Executor: append the events to the local log (if it's on), then count them for profit (even when it's off). In
	 * one task, in order, so a profit rebuild reading the log never misses or double counts an event.
	 */
	private void appendAndApply(ProfitStore ps, Map<YearMonth, List<String>> lines, String acct, List<TradeEvent> events,
		boolean older)
	{
		boolean logged = false, allLogged = lines != null;
		if (lines != null)
		{
			for (Map.Entry<YearMonth, List<String>> e : lines.entrySet())
			{
				boolean ok = appendLocalLog(e.getKey(), e.getValue());
				logged |= ok;
				allLogged &= ok;
			}
		}
		if (ps == null)
		{
			return;
		}
		try
		{
			if (!(older && allLogged && acct != null && ps.rebuildFor(acct)))
			{
				ps.apply(acct, events, logged);
			}
		}
		catch (RuntimeException ex)
		{
			log.warn("Couldn't count profit", ex);
		}
	}

	/* ------------------------------------------- RuneLite GE history import */

	/**
	 * The panel's "Import RuneLite GE history" (EDT): the player asked to read the trade history RuneLite's own Grand
	 * Exchange plugin keeps for the logged-in account. Reads that config value on the client thread, works out what
	 * is new on the executor (with the local trade log), then records it on the client thread. {@code onDone} gets
	 * the result line on the EDT. Returns false when an import is already running.
	 */
	private boolean startRuneLiteImport(Consumer<RuneLiteImportAction.Result> onDone)
	{
		if (!importing.compareAndSet(false, true))
		{
			return false;
		}
		Consumer<RuneLiteImportAction.Result> finish = result ->
		{
			importing.set(false);
			SwingUtilities.invokeLater(() -> onDone.accept(result));
		};
		clientThread.invoke(() ->
		{
			try
			{
				readRuneLiteHistory(finish);
			}
			catch (RuntimeException ex)
			{
				log.warn("RuneLite GE history import failed", ex);
				finish.accept(RuneLiteImportAction.Result.problem(RuneLiteImport.FAILED));
			}
		});
		return true;
	}

	/**
	 * Client thread: only logged in on world 345 with RuneLite's DEADMAN profile, and only the current profile's value
	 * (never another account's). Hands the raw text to the executor.
	 */
	private void readRuneLiteHistory(Consumer<RuneLiteImportAction.Result> finish)
	{
		OfferTracker t = tracker;
		boolean onDeadman345 = t != null && client.getGameState() == GameState.LOGGED_IN && isTrackedWorld()
			&& RuneScapeProfileType.getCurrent(client) == RuneScapeProfileType.DEADMAN && ensureProfileLoaded(t);
		String profile = onDeadman345 ? configManager.getRSProfileKey() : null;
		String acct = onDeadman345 ? accountId() : null;
		onDeadman345 &= profile != null && acct != null && profile.equals(store.loadedProfile());
		// The local log is what tells which trades the plugin already has (queued appends run first on the
		// executor); without it, trades recorded in earlier sessions would be imported again.
		String blocked = RuneLiteImport.blocked(onDeadman345, config.saveLocalLog());
		if (blocked != null)
		{
			finish.accept(RuneLiteImportAction.Result.problem(blocked));
			return;
		}
		String json = store.runeLiteTradeHistory();
		long watermark = store.runeLiteImportedThrough();
		int world = client.getWorld();
		executor.execute(() ->
		{
			try
			{
				planRuneLiteImport(json, watermark, profile, acct, world, finish);
			}
			catch (IOException | RuntimeException ex)
			{
				log.warn("RuneLite GE history import failed", ex);
				finish.accept(RuneLiteImportAction.Result.problem(RuneLiteImport.FAILED));
			}
		});
	}

	/** Executor: parse, drop records before the cutoff, compare with what this account already has. */
	private void planRuneLiteImport(String json, long watermark, String profile, String acct, int world,
		Consumer<RuneLiteImportAction.Result> finish) throws IOException
	{
		List<RuneLiteImport.Record> records = RuneLiteImport.parse(gson, json);
		List<RuneLiteImport.Record> candidates = new ArrayList<>();
		for (RuneLiteImport.Record r : records)
		{
			if (!RuneLiteImport.beforeCutoff(r) && r.getTime() > watermark)
			{
				candidates.add(r);
			}
		}
		List<TradeEvent> known = new ArrayList<>();
		if (!candidates.isEmpty())
		{
			Filepath dir = getPluginDirectory();
			for (String name : LogFiles.fromMonth(LocalTradeLog.listNames(dir), RuneLiteImport.firstMonth(candidates)))
			{
				LocalTradeLog.forEachInFile(dir, name, gson, (obj, ev) ->
				{
					if (ProfitStore.belongsTo(obj, acct))
					{
						known.add(ev);
					}
				});
			}
		}
		RuneLiteImport.Plan plan = RuneLiteImport.plan(records, known, watermark, world);
		log.debug("RuneLite GE history: {} records, {} new, {} already recorded, {} before the cutoff", records.size(),
			plan.getAdd().size(), plan.getAlready(), plan.getBeforeCutoff());
		clientThread.invoke(() ->
		{
			try
			{
				applyRuneLiteImport(plan, watermark, profile, acct, finish);
			}
			catch (RuntimeException ex)
			{
				log.warn("RuneLite GE history import failed", ex);
				finish.accept(RuneLiteImportAction.Result.problem(RuneLiteImport.FAILED));
			}
		});
	}

	/** Client thread: record the new trades, if the same account is still logged in, and remember how far we got. */
	private void applyRuneLiteImport(RuneLiteImport.Plan plan, long watermark, String profile, String acct,
		Consumer<RuneLiteImportAction.Result> finish)
	{
		if (tracker == null)
		{
			finish.accept(RuneLiteImportAction.Result.problem(RuneLiteImport.STOPPED));
			return;
		}
		if (!profile.equals(configManager.getRSProfileKey()) || !profile.equals(store.loadedProfile())
			|| !acct.equals(accountId()))
		{
			finish.accept(RuneLiteImportAction.Result.problem(RuneLiteImport.ACCOUNT_CHANGED));
			return;
		}
		if (!plan.getAdd().isEmpty())
		{
			List<TradeEvent> events = new ArrayList<>(plan.getAdd().size());
			for (TradeEvent ev : plan.getAdd())
			{
				events.add(withName(ev));
			}
			myTrades.addByTime(events);
			notifyMyTradesChanged();
			persist(events, acct, true);
			// So a GE History row read later for one of these trades isn't recorded again.
			store.saveRuneLiteRecent(RuneLiteImport.remember(store.loadRuneLiteRecent(), events));
		}
		if (plan.getNewestMs() > watermark)
		{
			store.saveRuneLiteImportedThrough(plan.getNewestMs());
		}
		finish.accept(RuneLiteImportAction.Result.done(RuneLiteImport.message(plan, ZoneId.systemDefault())));
	}

	/**
	 * When your 4-hour GE buy limit for {@code itemId} resets, from RuneLite's GE plugin data for the current profile;
	 * null off world 345 or when no reset is coming. Any thread (a config read).
	 */
	private Instant buyLimitResetForPanel(int itemId)
	{
		if (!onTrackedWorld)
		{
			return null;
		}
		return BuyLimitReset.future(store.buyLimitReset(itemId), Instant.now());
	}

	/** Profit numbers changed (executor). */
	private void onProfit(ProfitSnapshot snapshot)
	{
		SwingUtilities.invokeLater(() ->
		{
			DeadmanToolKitPanel p = panel;
			if (p != null)
			{
				p.onProfit(snapshot);
			}
		});
	}

	/** The panel's Rebuild button (EDT): recount profit from the local log in the background. */
	private void rebuildProfit()
	{
		ProfitStore ps = profit;
		if (ps != null)
		{
			executor.execute(ps::rebuild);
		}
	}

	/**
	 * One local log line: the event plus "acct", the hashed account id (when known), so per-account numbers can be
	 * rebuilt from the log. Reading a line back as a TradeEvent ignores "acct".
	 */
	static JsonObject logLine(Gson gson, TradeEvent ev, String accountId)
	{
		JsonObject o = gson.toJsonTree(ev).getAsJsonObject();
		if (accountId != null)
		{
			o.addProperty("acct", accountId);
		}
		return o;
	}

	/** Must be called on the client thread. */
	private TradeEvent withName(TradeEvent ev)
	{
		return ev.toBuilder().name(itemManager.getItemComposition(ev.getItemId()).getName()).build();
	}

	/** Older log lines have no item name. Must be called on the client thread. */
	private TradeEvent withNameIfMissing(TradeEvent ev)
	{
		return ev.getName() == null ? withName(ev) : ev;
	}

	private void notifyMyTradesChanged()
	{
		SwingUtilities.invokeLater(() ->
		{
			DeadmanToolKitPanel p = panel;
			if (p != null)
			{
				p.onMyTradesChanged();
			}
		});
	}

	/** Client thread only. Captures the name now; the icon is only referenced and gets PNG-encoded during flush. */
	private void queueItemInfo(TradeUploader up, int itemId)
	{
		if (!up.needsItem(itemId))
		{
			return;
		}
		String name = itemManager.getItemComposition(itemId).getName();
		AsyncBufferedImage img = itemManager.getImage(itemId);
		up.addItem(itemId, name, img, geLimit(itemId));
		img.onLoaded(() -> up.setIcon(itemId, img));
	}

	/**
	 * The item's GE buy limit from RuneLite's item stats (an in-memory lookup, no IO), or 0 when unknown. The server
	 * uses it to reject buys over the 4-hour limit; it only accepts the value from trusted sources. Client thread.
	 */
	private int geLimit(int itemId)
	{
		ItemStats stats = itemManager.getItemStats(itemId);
		return stats != null && stats.getGeLimit() > 0 ? stats.getGeLimit() : 0;
	}

	/**
	 * Load the local trade log so "My trades" survives restarts. Runs off the client thread.
	 *
	 * @param session {@link MyTrades#session()} when the plugin started; if the plugin has been stopped since, the
	 *                result is dropped rather than merged into a later session
	 */
	private void loadLocalLog(int session)
	{
		List<TradeEvent> newest;
		try
		{
			// Only the newest shown events, read from the end of the newest files; the rest of the log isn't parsed.
			newest = LocalTradeLog.readNewest(getPluginDirectory(), gson, MyTrades.MAX);
		}
		catch (IOException ex)
		{
			log.debug("Couldn't read local trade log", ex);
			return;
		}
		if (newest.isEmpty())
		{
			return;
		}

		// Item names are filled in on the client thread. Item definitions only exist once the client has loaded the game
		// cache (login screen or later); at startup this runs earlier, so retry on each tick until then.
		clientThread.invokeLater(() ->
		{
			if (client.getGameState().getState() < GameState.LOGIN_SCREEN.getState())
			{
				return false;
			}
			if (myTrades.mergeLoaded(session, newest, this::withNameIfMissing))
			{
				notifyMyTradesChanged();
			}
			else
			{
				log.debug("Dropped a local trade log load from a previous session");
			}
			return true;
		});
	}

	private static BufferedImage buildIcon()
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(0xd8a634));
		g.fillOval(0, 0, 16, 16);
		g.setColor(new Color(0x2b2b2b));
		g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.drawPolyline(new int[]{3, 6, 9, 13}, new int[]{11, 7, 9, 4}, 4);
		g.dispose();
		return img;
	}

	/** @return true if the lines were written */
	private boolean appendLocalLog(YearMonth month, List<String> lines)
	{
		try
		{
			LocalTradeLog.append(getPluginDirectory(), month, lines);
			return true;
		}
		catch (IOException ex)
		{
			log.warn("Couldn't write local trade log", ex);
			return false;
		}
	}

	/**
	 * Your open offers, sent to the panel when they changed so the item view can show them at once. Client thread.
	 *
	 * @param t the tracker, or null when logged out / not on world 345 (no offers)
	 */
	private void publishOffers(OfferTracker t)
	{
		List<ActiveOffer> offers = t == null ? Collections.emptyList()
			: ActiveOffer.fromTracker(t, id -> itemManager.getItemComposition(id).getName());
		if (offers.equals(publishedOffers))
		{
			return;
		}
		publishedOffers = offers;
		OfferMarketWatch watch = offerWatch;
		if (watch != null)
		{
			watch.setOffers(offers);
		}
		SwingUtilities.invokeLater(() ->
		{
			DeadmanToolKitPanel p = panel;
			if (p != null)
			{
				p.onOffersChanged(offers);
			}
		});
	}

	/** The server accepted trades of these items (OkHttp thread): let the item view fetch the new market data. */
	private void onUploaded(Set<Integer> itemIds)
	{
		SwingUtilities.invokeLater(() ->
		{
			DeadmanToolKitPanel p = panel;
			if (p != null)
			{
				p.onUploaded(itemIds);
			}
		});
	}

	/**
	 * Upload in about {@link #FLUSH_SOON_SECONDS} instead of at the next scheduled flush, so a fill shows up in the
	 * market data quickly. Requests while one is pending are merged into it.
	 */
	private void requestFlushSoon()
	{
		ScheduledFuture<?> pending = soonFlush.get();
		if (pending != null && !pending.isDone())
		{
			return;
		}
		ScheduledFuture<?> next = executor.schedule(() -> flushSoon(1), FLUSH_SOON_SECONDS, TimeUnit.SECONDS);
		if (!soonFlush.compareAndSet(pending, next))
		{
			// Another request scheduled one first.
			next.cancel(false);
		}
	}

	/** The one-shot upload; if a request is still running, try again a little later (a few times at most). */
	private void flushSoon(int attempt)
	{
		if (tracker == null)
		{
			// Stopped meanwhile; shutDown already flushed.
			return;
		}
		TradeUploader up = uploader;
		if (up != null && up.isInFlight() && attempt < FLUSH_SOON_TRIES)
		{
			soonFlush.set(executor.schedule(() -> flushSoon(attempt + 1), FLUSH_SOON_SECONDS, TimeUnit.SECONDS));
			return;
		}
		// Clear first, so a fill recorded during this upload schedules its own.
		soonFlush.set(null);
		scheduledFlush();
	}

	/** Whether the side panel is open; any thread. */
	private boolean panelShown()
	{
		DeadmanToolKitPanel p = panel;
		return p != null && p.isPanelActive();
	}

	/** The periodic offer check (executor). Only starts a request when due; catches everything to keep the task alive. */
	private void checkOffers()
	{
		try
		{
			OfferMarketWatch w = offerWatch;
			if (w != null)
			{
				w.refresh(false);
			}
		}
		catch (RuntimeException ex)
		{
			warnOnce("Offer check failed", ex);
		}
	}

	/** Failures of the repeating tasks already logged as a warning; the next ones go to debug. */
	private final Set<String> warned = ConcurrentHashMap.newKeySet();

	/** A scheduled task failed: a warning the first time, debug after that (it runs every few seconds). */
	private void warnOnce(String what, RuntimeException ex)
	{
		if (warned.add(what))
		{
			log.warn(what, ex);
		}
		else
		{
			log.debug("{}: {}", what, ex.toString());
		}
	}

	/** The scheduled upload. Catches everything: an exception would cancel the fixed-delay task for the session. */
	private void scheduledFlush()
	{
		try
		{
			flush();
		}
		catch (RuntimeException ex)
		{
			warnOnce("Trade upload flush failed", ex);
		}
		saveSpool();
	}

	/** Write the uploads still waiting to the spool file (or remove it). Executor thread. */
	private void saveSpool()
	{
		UploadSpool sp = spool;
		TradeUploader up = uploader;
		if (sp != null && up != null)
		{
			try
			{
				sp.save(up.pending());
			}
			catch (RuntimeException ex)
			{
				warnOnce("Couldn't save pending uploads", ex);
			}
		}
	}

	/**
	 * Enabled while logged in on world 345: the game sends no offer events for slots that haven't changed, so compare
	 * all 8 with the saved state now. Whatever differs happened while the plugin wasn't watching, so it is recorded as
	 * late (never as a live trade at this moment). Slots the game shows as empty are cleared. Client thread.
	 */
	private void reconcileSlots()
	{
		OfferTracker t = tracker;
		if (!isTrackedWorld() || !ensureProfileLoaded(t))
		{
			return;
		}
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return;
		}
		long ts = now();
		int world = client.getWorld();
		for (int slot = 0; slot < offers.length && slot < OfferTracker.SLOTS; slot++)
		{
			GrandExchangeOffer offer = offers[slot];
			if (offer == null)
			{
				continue;
			}
			List<TradeEvent> events = t.update(slot, OfferTracker.Snapshot.of(offer), true, ts, world);
			store.saveSlot(t, slot);
			if (!events.isEmpty())
			{
				store.saveCompleted(t);
				record(events);
			}
		}
		publishOffers(t);
	}

	private void flush()
	{
		TradeUploader up = uploader;
		if (up == null)
		{
			return;
		}
		if (!shareEnabled())
		{
			up.clear();
			return;
		}
		up.flush();
	}

	/** Your offers that are still open, serialized now since the slot state keeps changing. Client thread only. */
	private List<JsonObject> buildOpenOffers(OfferTracker t, TradeUploader up)
	{
		List<JsonObject> offers = new ArrayList<>();
		for (int slot = 0; slot < OfferTracker.SLOTS; slot++)
		{
			OfferTracker.SlotState s = t.getSlot(slot);
			if (s == null || s.getStatus() != OfferTracker.Status.ACTIVE || s.getSold() >= s.getTotalQty())
			{
				continue;
			}
			offers.add(TradeUploader.offerJson(slot, s));
			queueItemInfo(up, s.getItemId());
		}
		return offers;
	}

	/* ---------------------------------------------------- persistence */

	/**
	 * Load slot state for the current account (each account / game mode has its own RuneLite profile).
	 *
	 * @param t the tracker, read once by the caller (null after shutDown)
	 */
	private boolean ensureProfileLoaded(OfferTracker t)
	{
		if (t == null || !store.ensureLoaded(t))
		{
			return false;
		}
		String profile = store.loadedProfile();
		if (profile != null && !profile.equals(announcedProfile))
		{
			announceAccount(profile);
			publishOffers(t);
		}
		return true;
	}

	/* ---------------------------------------------------------- helpers */

	/** Only the permanent Deadman world (345), double-checked against the world type. */
	private boolean isTrackedWorld()
	{
		return client.getWorld() == PERMANENT_DEADMAN_WORLD
			&& client.getWorldType().contains(WorldType.DEADMAN);
	}

	private static long now()
	{
		return Instant.now().getEpochSecond();
	}
}

package com.deadmantoolkit;

import com.deadmantoolkit.world.WorldEventMessage;
import java.util.Arrays;
import java.util.Locale;
import java.util.Optional;
import java.util.function.Consumer;
import lombok.Value;
import net.runelite.api.events.CommandExecuted;
import net.runelite.client.eventbus.Subscribe;

/**
 * The {@code ::dgt} developer command: a fresh-install preview of the panel, re-arming the one-time hints, and test
 * world events (fed through the same parser as the game's broadcasts, but never reported to the server).
 * Registered on the event bus only in developer mode; normal installs never see it. Runs on the client thread.
 */
final class DevCommands
{
	static final String COMMAND = "dgt";
	static final String USAGE = "Usage: ::dgt fresh | fresh off | hints | chest <place> | breach <place> [single|multi]"
		+ " | events sample | events clear";

	enum Action
	{
		/** Show the panel as a brand-new install would (UI only; nothing real changes). */
		FRESH_ON,
		/** Back to the real state. */
		FRESH_OFF,
		/** Re-arm the one-time chat hint and show it now. */
		HINTS,
		/** A test broadcast: {@link Command#getGameText()}. */
		WORLD_EVENT,
		/** A wave of test events: a chest and breaches at known, rough, other-map and unknown places. */
		EVENTS_SAMPLE,
		/** Forget all world events. */
		EVENTS_CLEAR,
	}

	@Value
	static class Command
	{
		Action action;
		/** WORLD_EVENT: the broadcast to feed, in the game's wording. */
		String gameText;
	}

	/** The sample wave, in the game's wording. */
	static final String[] SAMPLE = {
		WorldEventMessage.gameText(WorldEventMessage.Kind.CHEST, "north of the Warriors' Guild", null),
		WorldEventMessage.gameText(WorldEventMessage.Kind.BREACH, "the Bone Yard", WorldEventMessage.Combat.MULTI),
		WorldEventMessage.gameText(WorldEventMessage.Kind.BREACH, "North of Asgarnia", WorldEventMessage.Combat.SINGLE),
		WorldEventMessage.gameText(WorldEventMessage.Kind.BREACH, "Zanaris", WorldEventMessage.Combat.SINGLE),
		WorldEventMessage.gameText(WorldEventMessage.Kind.BREACH, "the Whispering Glade", WorldEventMessage.Combat.MULTI),
	};

	/** What the command drives. */
	interface Target
	{
		void freshPreview(boolean on);

		void resetHints();

		/** Feed a test broadcast. */
		void worldEvent(String gameText);

		void clearWorldEvents();
	}

	private final Target target;
	/** Shows a line in the local chatbox only. */
	private final Consumer<String> chat;

	DevCommands(Target target, Consumer<String> chat)
	{
		this.target = target;
		this.chat = chat;
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted e)
	{
		if (COMMAND.equalsIgnoreCase(e.getCommand()))
		{
			run(e.getArguments());
		}
	}

	/** Run {@code ::dgt <args>}; also used by the panel's dev tools buttons. Client thread. */
	void run(String[] args)
	{
		Optional<Command> parsed = parse(args);
		if (!parsed.isPresent())
		{
			chat.accept(USAGE);
			return;
		}
		Command c = parsed.get();
		switch (c.getAction())
		{
			case FRESH_ON:
				target.freshPreview(true);
				chat.accept("Fresh-install preview on (panel only; nothing real changed). ::dgt fresh off to end it.");
				break;
			case FRESH_OFF:
				target.freshPreview(false);
				chat.accept("Fresh-install preview off.");
				break;
			case HINTS:
				target.resetHints();
				break;
			case WORLD_EVENT:
				target.worldEvent(c.getGameText());
				chat.accept("Test event: " + c.getGameText());
				break;
			case EVENTS_SAMPLE:
				for (String text : SAMPLE)
				{
					target.worldEvent(text);
				}
				chat.accept("Test events: a chest and 4 breaches (one at a place the plugin doesn't know).");
				break;
			case EVENTS_CLEAR:
				target.clearWorldEvents();
				chat.accept("World events cleared.");
				break;
		}
	}

	/**
	 * {@code fresh [on|off]}, {@code hints}, {@code chest <place>}, {@code breach <place> [single|multi]},
	 * {@code events sample}, {@code events clear}; case-insensitive.
	 */
	static Optional<Command> parse(String[] args)
	{
		if (args == null || args.length == 0)
		{
			return Optional.empty();
		}
		String first = args[0].toLowerCase(Locale.ROOT);
		String second = args.length > 1 ? args[1].toLowerCase(Locale.ROOT) : null;
		switch (first)
		{
			case "fresh":
				if (args.length > 2)
				{
					return Optional.empty();
				}
				if (second == null || second.equals("on"))
				{
					return Optional.of(new Command(Action.FRESH_ON, null));
				}
				return second.equals("off") ? Optional.of(new Command(Action.FRESH_OFF, null)) : Optional.empty();
			case "hints":
				return args.length == 1 ? Optional.of(new Command(Action.HINTS, null)) : Optional.empty();
			case "events":
				if (args.length != 2)
				{
					return Optional.empty();
				}
				return second.equals("sample") ? Optional.of(new Command(Action.EVENTS_SAMPLE, null))
					: second.equals("clear") ? Optional.of(new Command(Action.EVENTS_CLEAR, null)) : Optional.empty();
			case "chest":
			{
				String place = String.join(" ", Arrays.copyOfRange(args, 1, args.length)).trim();
				return place.isEmpty() ? Optional.empty() : Optional.of(new Command(Action.WORLD_EVENT,
					WorldEventMessage.gameText(WorldEventMessage.Kind.CHEST, place, null)));
			}
			case "breach":
			{
				int end = args.length;
				WorldEventMessage.Combat combat = null;
				String last = args[end - 1].toLowerCase(Locale.ROOT);
				if (end > 2 && (last.equals("single") || last.equals("multi")))
				{
					combat = last.equals("multi") ? WorldEventMessage.Combat.MULTI : WorldEventMessage.Combat.SINGLE;
					end--;
				}
				String place = String.join(" ", Arrays.copyOfRange(args, 1, end)).trim();
				return place.isEmpty() ? Optional.empty() : Optional.of(new Command(Action.WORLD_EVENT,
					WorldEventMessage.gameText(WorldEventMessage.Kind.BREACH, place, combat)));
			}
			default:
				return Optional.empty();
		}
	}
}

package com.deadmantoolkit;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.function.Predicate;
import java.util.function.Supplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;

/**
 * Parses the in-game Grand Exchange History tab and works out which rows are new since we last read it.
 * The tab lists completed trades newest-first with no timestamps.
 */
public final class GeHistory
{
	private static final Pattern NUMBER = Pattern.compile("\\d[\\d,]*");
	private static final Pattern TAGS = Pattern.compile("<[^>]*>");

	private GeHistory()
	{
	}

	/** The bits of a history-list widget we care about. */
	@Value
	public static class Cell
	{
		String text;
		int itemId;
		int itemQty;
	}

	@Value
	public static class Entry
	{
		boolean buy;
		int itemId;
		int qty;
		long total;

		String signature()
		{
			return OfferTracker.signature(buy, itemId, qty, total);
		}
	}

	/**
	 * Walk the list's children in order, collecting a side label ("Bought"/"Sold"), an item, and a coin total into
	 * each entry. Order-tolerant, so small layout changes in the interface don't break it.
	 */
	public static List<Entry> parse(List<Cell> cells)
	{
		List<Entry> out = new ArrayList<>();
		Boolean buy = null;
		int itemId = -1, qty = 0;
		long total = -1;

		for (Cell c : cells)
		{
			String text = c.text == null ? "" : TAGS.matcher(c.text.replace("<br>", " ")).replaceAll("").trim();
			if (c.itemId > 0)
			{
				itemId = c.itemId;
				qty = c.itemQty;
			}
			else if (text.startsWith("Bought"))
			{
				buy = true;
			}
			else if (text.startsWith("Sold"))
			{
				buy = false;
			}
			else if (text.toLowerCase(Locale.ROOT).contains("coin"))
			{
				Matcher m = NUMBER.matcher(text);
				if (m.find())
				{
					try
					{
						total = Long.parseLong(m.group().replace(",", ""));
					}
					catch (NumberFormatException e)
					{
						total = -1;
					}
				}
			}

			if (buy != null && itemId > 0 && qty > 0 && total > 0)
			{
				out.add(new Entry(buy, itemId, qty, total));
				buy = null;
				itemId = -1;
				qty = 0;
				total = -1;
			}
		}
		return out;
	}

	/**
	 * Given the previous and current list of row signatures (both newest-first), return how many rows at the top of
	 * {@code current} are new. Finds the smallest offset at which the rest of {@code current} lines up with the
	 * start of {@code previous}.
	 */
	public static int countNew(List<String> previous, List<String> current)
	{
		if (previous == null || previous.isEmpty())
		{
			return current.size();
		}
		for (int k = 0; k < current.size(); k++)
		{
			int overlap = Math.min(current.size() - k, previous.size());
			boolean match = true;
			for (int j = 0; j < overlap; j++)
			{
				if (!current.get(k + j).equals(previous.get(j)))
				{
					match = false;
					break;
				}
			}
			if (match)
			{
				return k;
			}
		}
		return current.size();
	}

	/**
	 * Build events for the {@code fresh} new rows at the top of {@code entries}, oldest first so matching against
	 * offers tracked live happens in trade order. Rows {@code seenLive} accepts were already recorded live and are
	 * skipped.
	 */
	public static List<TradeEvent> newEvents(List<Entry> entries, int fresh, Predicate<String> seenLive, long ts, int world,
		Supplier<String> idGen)
	{
		List<TradeEvent> events = new ArrayList<>();
		for (int i = fresh - 1; i >= 0; i--)
		{
			Entry en = entries.get(i);
			if (seenLive.test(en.signature()))
			{
				continue;
			}
			events.add(TradeEvent.builder()
				.id(idGen.get())
				.kind(TradeEvent.HISTORY)
				.side(TradeEvent.sideOf(en.isBuy()))
				.itemId(en.getItemId())
				.qty(en.getQty())
				.price(TradeEvent.avgPrice(en.getTotal(), en.getQty()))
				.total(en.getTotal())
				.ts(ts)
				.late(true)
				.world(world)
				.build());
		}
		return events;
	}
}

package com.deadmantoolkit;

import net.runelite.client.util.QuantityFormatter;
import net.runelite.client.util.Text;

/**
 * The Deadman price line in the GE offer setup's description text (pure).
 * <p>
 * The game builds that text in a script that hands it to RuneLite's "geBuyExamineText" / "geSellExamineText"
 * callbacks before setting it: examine text, then (when there is one) the fee line last, with an info icon placed
 * after the last line. Core's GE plugin appends its own lines before the fee. This adds one line marked
 * {@link #MARKER}, also before the fee, and removes any earlier one first, so applying it twice never duplicates it
 * and nothing else in the text changes.
 */
final class GePriceText
{
	static final String MARKER = "<col=ff981f>DMM</col>";
	private static final String BR = "<br>";
	/** Visible characters a line may have before the bid / ask part is dropped. */
	static final int MAX_VISIBLE = 60;

	private GePriceText()
	{
	}

	/**
	 * {@code out} with {@code line} added: before {@code fee} when the text ends with it (so the fee stays last and its
	 * icon stays in place), otherwise as a new last line. An earlier DMM line is replaced.
	 *
	 * @param out  the text the script will set
	 * @param fee  the fee text the script got, or empty
	 * @param line from {@link #line}
	 */
	static String insert(String out, String fee, String line)
	{
		String base = strip(out == null ? "" : out);
		if (fee != null && !fee.isEmpty() && base.endsWith(fee))
		{
			return base.substring(0, base.length() - fee.length()) + line + BR + fee;
		}
		return base.isEmpty() ? line : base + BR + line;
	}

	/** {@code text} without any DMM line (and the line break that introduced it). */
	static String strip(String text)
	{
		String s = text;
		int at;
		while ((at = s.indexOf(MARKER)) >= 0)
		{
			int end = s.indexOf(BR, at);
			boolean afterBreak = at >= BR.length() && s.startsWith(BR, at - BR.length());
			if (afterBreak)
			{
				// "...<br>DMM ...<br>rest" -> "...<br>rest"; "...<br>DMM ..." -> "..."
				s = s.substring(0, at - BR.length()) + (end < 0 ? "" : s.substring(end));
			}
			else
			{
				// The DMM line is first: drop it and its trailing break.
				s = s.substring(0, at) + (end < 0 ? "" : s.substring(end + BR.length()));
			}
		}
		return s;
	}

	/** The line for an item's market summary, e.g. "DMM last 1.25M/1.24M · bid 1.23M ask 1.26M · 523/24h". */
	static String line(MarketData.Summary s)
	{
		return line(s, null);
	}

	/**
	 * {@link #line(MarketData.Summary)} plus, when {@code limitReset} is set, when your GE buy limit for the item
	 * resets, e.g. "... · limit resets in 2h 14m".
	 *
	 * @param limitReset the time left ({@link BuyLimitReset#remaining}), or null to leave it out
	 */
	static String line(MarketData.Summary s, String limitReset)
	{
		if (s == null)
		{
			return MARKER + " no trades yet" + limitPart(limitReset, false);
		}
		return line(s.getLastBuy(), s.getLastSell(), s.getBestBid(), s.getBestAsk(), s.getVol24(), limitReset);
	}

	static String line(Long lastBuy, Long lastSell, Long bestBid, Long bestAsk, long vol24)
	{
		return line(lastBuy, lastSell, bestBid, bestAsk, vol24, null);
	}

	/**
	 * The line stays within {@link #MAX_VISIBLE} visible characters: when it would be longer, the bid / ask part goes
	 * first, then the buy limit part gets its short form ("limit 2h 14m").
	 */
	static String line(Long lastBuy, Long lastSell, Long bestBid, Long bestAsk, long vol24, String limitReset)
	{
		if (lastBuy == null && lastSell == null && bestBid == null && bestAsk == null && vol24 <= 0)
		{
			return MARKER + " no trades yet" + limitPart(limitReset, false);
		}
		String last = " last " + gp(lastBuy) + "/" + gp(lastSell);
		String book = " · bid " + gp(bestBid) + " ask " + gp(bestAsk);
		String vol = " · " + QuantityFormatter.quantityToStackSize(Math.max(0, vol24)) + "/24h";
		String limit = limitPart(limitReset, false);
		String full = MARKER + last + book + vol + limit;
		if (fits(full))
		{
			return full;
		}
		String noBook = MARKER + last + vol + limit;
		if (fits(noBook) || limitReset == null)
		{
			return noBook;
		}
		return MARKER + last + vol + limitPart(limitReset, true);
	}

	/** " · limit resets in 2h 14m" (short: " · limit 2h 14m"), or empty without a reset time. */
	static String limitPart(String limitReset, boolean shortForm)
	{
		if (limitReset == null || limitReset.isEmpty())
		{
			return "";
		}
		return (shortForm ? " · limit " : " · limit resets in ") + limitReset;
	}

	private static boolean fits(String line)
	{
		return Text.removeTags(line).length() <= MAX_VISIBLE;
	}

	/** Compact gp ("1.25M", "9,999"), or "-" when unknown. */
	static String gp(Long v)
	{
		return v == null ? "-" : QuantityFormatter.quantityToStackSize(v);
	}
}

package com.deadmantoolkit;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.HashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Where this computer's install id and install token live: a small JSON file in the plugin's data folder, not the
 * RuneLite config. ConfigManager logs every value it saves at debug level (so a token would end up in client.log with
 * --debug), broadcasts it to all plugins in a ConfigChanged event, and syncs the config to RuneLite's servers for
 * players with a RuneLite account; a synced install id would also make two PCs fight over one id.
 * <p>
 * The file is read once (lazily) and cached; every change is written straight away (temp file, then rename). When the
 * folder can't be written, the values stay in memory for this session. Values are never logged.
 * Not thread-safe on its own: {@link InstallIdentity} serialises all calls.
 */
@Slf4j
final class IdentityFile implements InstallIdentity.Store
{
	static final String FILE_NAME = "server-identity.json";

	private final ProfitStore.Dir dir;
	private final Gson gson;
	private Map<String, String> values;
	/**
	 * The file is there but couldn't be read (locked by another program, no permission): this session works from memory
	 * and never writes over it, so the install keeps its id and key for the next start.
	 */
	private boolean readOnly;

	IdentityFile(ProfitStore.Dir dir, Gson gson)
	{
		this.dir = dir;
		this.gson = gson;
	}

	@Override
	public String get(String key)
	{
		return load().get(key);
	}

	@Override
	public void set(String key, String value)
	{
		load().put(key, value);
		save();
	}

	@Override
	public void unset(String key)
	{
		if (load().remove(key) != null)
		{
			save();
		}
	}

	/** True once the file was read (so a caller on the EDT can avoid triggering the read). */
	boolean loaded()
	{
		return values != null;
	}

	private Map<String, String> load()
	{
		if (values != null)
		{
			return values;
		}
		values = new HashMap<>();
		Filepath file = null;
		try
		{
			file = dir.get().joinSegment(FILE_NAME);
		}
		catch (IOException | RuntimeException ex)
		{
			log.debug("Couldn't open the plugin data folder: {}", ex.getClass().getSimpleName());
		}
		if (file != null && file.isFile())
		{
			// Read first, then parse: Gson reports a failed read as a syntax error, and the two must differ here.
			String text = null;
			try
			{
				text = readText(file);
			}
			catch (IOException | RuntimeException ex)
			{
				// Unreadable right now (locked by another program, no permission), not broken: don't replace it with a
				// new id, which would lose the key for good.
				log.debug("Couldn't read the install identity file: {}", ex.getClass().getSimpleName());
				readOnly = true;
			}
			if (text != null)
			{
				try
				{
					JsonObject o = gson.fromJson(text, JsonObject.class);
					if (o != null)
					{
						for (String k : new String[]{InstallIdentity.KEY_INSTALL_ID, InstallIdentity.KEY_INSTALL_TOKEN,
							InstallIdentity.KEY_LOST_IDS})
						{
							JsonElement e = o.get(k);
							if (e != null && e.isJsonPrimitive())
							{
								values.put(k, e.getAsString());
							}
						}
					}
				}
				catch (RuntimeException ex)
				{
					// Not JSON: nothing in it can be used, so it is replaced on the next save.
					log.debug("Couldn't parse the install identity file: {}", ex.getClass().getSimpleName());
				}
			}
		}
		return values;
	}

	private static String readText(Filepath file) throws IOException
	{
		StringBuilder sb = new StringBuilder();
		char[] buf = new char[1024];
		try (BufferedReader r = file.openBufferedReader())
		{
			int n;
			while ((n = r.read(buf)) != -1)
			{
				sb.append(buf, 0, n);
			}
		}
		return sb.toString();
	}

	/** Writes the values (temp file, then rename). False when the folder can't be written; never logs a value. */
	private boolean save()
	{
		if (readOnly)
		{
			return false;
		}
		try
		{
			Filepath d = dir.get();
			if (!d.exists())
			{
				d.createDirectories();
			}
			JsonObject o = new JsonObject();
			for (Map.Entry<String, String> e : values.entrySet())
			{
				o.addProperty(e.getKey(), e.getValue());
			}
			Filepath file = d.joinSegment(FILE_NAME);
			Filepath tmp = d.joinSegment(FILE_NAME + ".tmp");
			try (BufferedWriter w = tmp.openBufferedWriter(StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING,
				StandardOpenOption.WRITE))
			{
				gson.toJson(o, w);
			}
			try
			{
				tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException ex)
			{
				tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
			}
			return true;
		}
		catch (IOException | RuntimeException ex)
		{
			log.debug("Couldn't save the install identity file: {}", ex.getClass().getSimpleName());
			return false;
		}
	}
}

package com.deadmantoolkit;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Gets an install token from the collection server (POST v1/register {installId}) and stores it in the
 * {@link ServerIdentity}. Asynchronous (OkHttp enqueue); the callback runs exactly once, on an OkHttp thread, or on
 * the caller's thread when the request can't even be started.
 * <p>
 * The token is a secret for this install: it is never logged, and neither are response bodies or request headers.
 * Only status codes are logged, at debug level.
 */
@Slf4j
class InstallAuth
{
	static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	/** The server's 409 error for an install id whose data was deleted (vs "installId already registered"). */
	static final String DELETED_ERROR = "installId deleted";

	enum Status
	{
		/** A token was issued; {@link Result#getToken()} has it. */
		OK,
		/**
		 * 409 "installId already registered": another token holds this install id (this PC's was lost or replaced, or
		 * the id isn't ours). Only when not rotating.
		 */
		CONFLICT,
		/** 409 "installId deleted": this install id's data was deleted already. Only when not rotating. */
		DELETED,
		/** Rate limited, server error, bad response or network failure. */
		FAILED
	}

	/** The outcome of a registration. Deliberately has no toString, so the token can't end up in a log line. */
	static final class Result
	{
		private final Status status;
		private final String installId;
		private final String token;
		/** HTTP status, or -1 for a network failure. */
		private final int code;

		Result(Status status, String installId, String token, int code)
		{
			this.status = status;
			this.installId = installId;
			this.token = token;
			this.code = code;
		}

		Status getStatus()
		{
			return status;
		}

		/** The install id the token was issued for (after any rotation). */
		String getInstallId()
		{
			return installId;
		}

		String getToken()
		{
			return token;
		}

		int getCode()
		{
			return code;
		}
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final HttpUrl registerUrl;
	private final ServerIdentity identity;

	InstallAuth(OkHttpClient http, Gson gson, HttpUrl base, ServerIdentity identity)
	{
		this.http = http;
		this.gson = gson;
		this.registerUrl = base.newBuilder().addPathSegments("v1/register").build();
		this.identity = identity;
	}

	/** Adds the install token to a request. */
	static Request.Builder bearer(Request.Builder req, String token)
	{
		return req.header("Authorization", "Bearer " + token);
	}

	/**
	 * Register the current install id.
	 *
	 * @param rotateOnConflict on 409, switch to a new random install id and try once more (uploads); when false a
	 *                         409 is reported as {@link Status#CONFLICT} (deleting data: the id is gone or not ours)
	 * @param done             called exactly once with the outcome
	 */
	void register(boolean rotateOnConflict, Consumer<Result> done)
	{
		String installId = identity.installId();
		JsonObject body = new JsonObject();
		body.addProperty("installId", installId);
		Request request = new Request.Builder()
			.url(registerUrl)
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		Call call;
		try
		{
			call = http.newCall(request);
		}
		catch (RuntimeException e)
		{
			log.warn("Couldn't start registration", e);
			deliver(done, new Result(Status.FAILED, installId, null, -1));
			return;
		}
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call c, IOException e)
			{
				log.debug("Registration failed: {}", e.getClass().getSimpleName());
				deliver(done, new Result(Status.FAILED, installId, null, -1));
			}

			@Override
			public void onResponse(Call c, Response response)
			{
				Result result;
				boolean retry = false;
				try (response)
				{
					int code = response.code();
					log.debug("Registration: HTTP {}", code);
					if (code == 200)
					{
						String token = readToken(response.body());
						if (InstallIdentity.isToken(token))
						{
							identity.setToken(installId, token);
							result = new Result(Status.OK, installId, token, code);
						}
						else
						{
							result = new Result(Status.FAILED, installId, null, code);
						}
					}
					else if (code == 409 && rotateOnConflict)
					{
						// Someone else holds this id (or it was deleted): continue as a new random install. When it is held by
						// another token, this PC's key for it was lost, and what it shared under it may still be on the server.
						if (DELETED_ERROR.equals(readError(response.body())))
						{
							identity.rotateInstallId();
						}
						else
						{
							identity.replaceInstallId();
						}
						retry = true;
						result = null;
					}
					else if (code == 409)
					{
						// Only an explicit "deleted" counts as already deleted; anything else may still have data.
						result = new Result(DELETED_ERROR.equals(readError(response.body())) ? Status.DELETED : Status.CONFLICT,
							installId, null, code);
					}
					else
					{
						result = new Result(Status.FAILED, installId, null, code);
					}
				}
				catch (RuntimeException e)
				{
					log.debug("Bad registration response: {}", e.getClass().getSimpleName());
					result = new Result(Status.FAILED, installId, null, -1);
				}
				if (retry)
				{
					register(false, done);
				}
				else
				{
					deliver(done, result);
				}
			}
		});
	}

	/** The "error" field of an error response, or null. */
	private String readError(ResponseBody body)
	{
		if (body == null)
		{
			return null;
		}
		try
		{
			JsonObject o = gson.fromJson(body.charStream(), JsonObject.class);
			JsonElement e = o == null ? null : o.get("error");
			return e != null && e.isJsonPrimitive() ? e.getAsString() : null;
		}
		catch (RuntimeException ex)
		{
			return null;
		}
	}

	/** The "token" field of a register response, or null. Never logs the body. */
	private String readToken(ResponseBody body)
	{
		if (body == null)
		{
			return null;
		}
		JsonObject o = gson.fromJson(body.charStream(), JsonObject.class);
		JsonElement t = o == null ? null : o.get("token");
		return t != null && t.isJsonPrimitive() ? t.getAsString() : null;
	}

	private static void deliver(Consumer<Result> done, Result result)
	{
		try
		{
			done.accept(result);
		}
		catch (RuntimeException e)
		{
			log.warn("Registration callback failed", e);
		}
	}
}

package com.deadmantoolkit;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Supplier;
import java.util.regex.Pattern;

/**
 * {@link ServerIdentity} over a small key-value {@link Store} ("installId", "installToken"): the plugin's
 * {@link IdentityFile} (a map in tests). All methods are synchronized, so two first-run callers can't each create and
 * save a different id.
 */
class InstallIdentity implements ServerIdentity
{
	static final String KEY_INSTALL_ID = "installId";
	static final String KEY_INSTALL_TOKEN = "installToken";
	/** Comma-separated older install ids whose key was lost ({@link #replaceInstallId()}). */
	static final String KEY_LOST_IDS = "lostInstallIds";
	private static final int MAX_LOST_IDS = 8;
	/** The server's token format: base64url of 32 random bytes, no padding. Anything else is treated as no token. */
	private static final Pattern TOKEN = Pattern.compile("^[A-Za-z0-9_-]{43}$");

	/** Where the values live (a file in the plugin's data folder, a map in tests). */
	interface Store
	{
		String get(String key);

		void set(String key, String value);

		void unset(String key);
	}

	private final Store store;
	private final Supplier<String> newId;

	InstallIdentity(Store store, Supplier<String> newId)
	{
		this.store = store;
		this.newId = newId;
	}

	/** True for a value shaped like a server-issued token. */
	static boolean isToken(String s)
	{
		return s != null && TOKEN.matcher(s).matches();
	}

	@Override
	public synchronized String installId()
	{
		return TrackerStore.installId(() -> store.get(KEY_INSTALL_ID), id -> store.set(KEY_INSTALL_ID, id), newId);
	}

	@Override
	public synchronized String token()
	{
		String t = store.get(KEY_INSTALL_TOKEN);
		return isToken(t) ? t : null;
	}

	@Override
	public synchronized void setToken(String installId, String token)
	{
		if (isToken(token) && installId != null && installId.equals(store.get(KEY_INSTALL_ID)))
		{
			store.set(KEY_INSTALL_TOKEN, token);
		}
	}

	@Override
	public synchronized void clearToken(String installId)
	{
		if (installId != null && installId.equals(store.get(KEY_INSTALL_ID)) && store.get(KEY_INSTALL_TOKEN) != null)
		{
			store.unset(KEY_INSTALL_TOKEN);
		}
	}

	@Override
	public synchronized String rotateInstallId()
	{
		if (store.get(KEY_INSTALL_TOKEN) != null)
		{
			store.unset(KEY_INSTALL_TOKEN);
		}
		String id = newId.get();
		store.set(KEY_INSTALL_ID, id);
		return id;
	}

	@Override
	public synchronized String replaceInstallId()
	{
		String old = store.get(KEY_INSTALL_ID);
		if (old != null && old.length() == TrackerStore.INSTALL_ID_LENGTH)
		{
			List<String> lost = new ArrayList<>(lostInstallIds());
			lost.remove(old);
			lost.add(old);
			while (lost.size() > MAX_LOST_IDS)
			{
				lost.remove(0);
			}
			store.set(KEY_LOST_IDS, String.join(",", lost));
		}
		return rotateInstallId();
	}

	@Override
	public synchronized List<String> lostInstallIds()
	{
		String v = store.get(KEY_LOST_IDS);
		if (v == null || v.isEmpty())
		{
			return Collections.emptyList();
		}
		List<String> out = new ArrayList<>();
		for (String id : v.split(","))
		{
			if (id.length() == TrackerStore.INSTALL_ID_LENGTH)
			{
				out.add(id);
			}
		}
		return out;
	}
}

package com.deadmantoolkit;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;

/**
 * Recent market summaries per item for the GE price line. Lookups never block; a missing or old entry starts one
 * background fetch (never two at once for an item) and calls back when it arrives. Thread safe.
 */
class ItemQuoteCache
{
	/** Refetch entries older than this. */
	static final long TTL_MS = 30_000;
	/** Entries older than this aren't shown at all while a newer one is fetched. */
	static final long MAX_AGE_MS = 5 * 60_000;
	static final int MAX_ENTRIES = 64;

	/** Fetches one item; callbacks may run on any thread. */
	interface Fetcher
	{
		void fetch(int itemId, Consumer<MarketData.ItemDetail> ok, Consumer<String> err);
	}

	private static final class Entry
	{
		MarketData.ItemDetail detail;
		long fetchedAt;
		/** When the last fetch was started (also after a failure, so a failing server isn't hammered). */
		long requestedAt = Long.MIN_VALUE;
		boolean inFlight;
		final List<Runnable> waiting = new ArrayList<>();
	}

	private final Fetcher fetcher;
	private final Map<Integer, Entry> entries = new LinkedHashMap<Integer, Entry>(16, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<Integer, Entry> eldest)
		{
			return size() > MAX_ENTRIES;
		}
	};

	ItemQuoteCache(Fetcher fetcher)
	{
		this.fetcher = fetcher;
	}

	/**
	 * The item's summary if one is held and not older than {@link #MAX_AGE_MS}; fetches a newer one in the background
	 * when it is older than {@link #TTL_MS} (or missing), then runs {@code onReady}.
	 *
	 * @param now    epoch ms
	 * @param onReady run (on the fetching thread) when new data has been stored; may be null
	 */
	MarketData.ItemDetail request(int itemId, long now, Runnable onReady)
	{
		MarketData.ItemDetail shown;
		synchronized (this)
		{
			Entry e = entries.computeIfAbsent(itemId, k -> new Entry());
			boolean has = e.detail != null;
			shown = has && now - e.fetchedAt <= MAX_AGE_MS ? e.detail : null;
			boolean fresh = has && now - e.fetchedAt <= TTL_MS;
			boolean recentlyTried = e.requestedAt != Long.MIN_VALUE && now - e.requestedAt < TTL_MS;
			if (fresh || recentlyTried && !e.inFlight)
			{
				return shown;
			}
			if (onReady != null)
			{
				e.waiting.add(onReady);
			}
			if (e.inFlight)
			{
				return shown;
			}
			e.inFlight = true;
			e.requestedAt = now;
		}
		fetcher.fetch(itemId, d -> done(itemId, d, now), err -> done(itemId, null, now));
		return shown;
	}

	/** The held summary if not older than {@link #MAX_AGE_MS}, without fetching. */
	synchronized MarketData.ItemDetail peek(int itemId, long now)
	{
		Entry e = entries.get(itemId);
		return e != null && e.detail != null && now - e.fetchedAt <= MAX_AGE_MS ? e.detail : null;
	}

	synchronized void clear()
	{
		entries.clear();
	}

	/** @param requestedAt when the fetch started; the data counts as of then */
	private void done(int itemId, MarketData.ItemDetail detail, long requestedAt)
	{
		List<Runnable> run;
		synchronized (this)
		{
			Entry e = entries.get(itemId);
			if (e == null)
			{
				// Cleared or evicted meanwhile.
				return;
			}
			e.inFlight = false;
			run = new ArrayList<>(e.waiting);
			e.waiting.clear();
			if (detail == null)
			{
				return;
			}
			e.detail = detail;
			e.fetchedAt = requestedAt;
		}
		run.forEach(Runnable::run);
	}
}

package com.deadmantoolkit;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.time.YearMonth;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.BiConsumer;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * The local trade log in the plugin's data folder: one JSON object per line (a {@link TradeEvent} plus "acct", the
 * hashed account id), in one file per month ({@code trades-YYYY-MM.jsonl}, by the event time in UTC). The legacy
 * {@code trades.jsonl} from older versions is still read. Does disk IO, so only call it from the executor, never the
 * client thread.
 */
@Slf4j
final class LocalTradeLog
{
	private LocalTradeLog()
	{
	}

	/** The file that events at {@code month} (UTC) go to. */
	static String fileName(YearMonth month)
	{
		return String.format("trades-%04d-%02d.jsonl", month.getYear(), month.getMonthValue());
	}

	/** The month (UTC) of a unix-seconds timestamp. */
	static YearMonth monthOf(long ts)
	{
		return YearMonth.from(Instant.ofEpochSecond(ts).atZone(ZoneOffset.UTC));
	}

	/** Append already-serialized lines to {@code month}'s file, creating the folder and file if needed. */
	static void append(Filepath dir, YearMonth month, List<String> lines) throws IOException
	{
		// getPluginDirectory() doesn't create this plugin's own folder.
		if (!dir.exists())
		{
			dir.createDirectories();
		}
		Filepath file = dir.joinSegment(fileName(month));
		try (BufferedWriter w = file.openBufferedWriter(StandardOpenOption.CREATE, StandardOpenOption.APPEND))
		{
			for (String line : lines)
			{
				w.write(line);
				w.newLine();
			}
		}
	}

	/** Names of the log files in {@code dir}, in no particular order (empty if the folder doesn't exist). */
	static List<String> listNames(Filepath dir) throws IOException
	{
		if (!dir.isDirectory())
		{
			return Collections.emptyList();
		}
		try (Stream<Filepath> s = dir.walk(1))
		{
			return s.filter(Filepath::isFile).map(Filepath::getFileName).collect(Collectors.toList());
		}
	}

	/**
	 * The newest {@code maxShown} events that "My trades" shows ({@link MyTrades#isShown}), oldest first. Reads files
	 * newest month first, each from its end, and stops as soon as it has enough, so older months are never opened.
	 * Lines that don't parse, or have no kind, are skipped.
	 */
	static List<TradeEvent> readNewest(Filepath dir, Gson gson, int maxShown) throws IOException
	{
		return readNewest(dir, gson, maxShown, ReverseLineReader.DEFAULT_CHUNK);
	}

	static List<TradeEvent> readNewest(Filepath dir, Gson gson, int maxShown, int chunk) throws IOException
	{
		List<TradeEvent> newestFirst = new ArrayList<>();
		if (maxShown <= 0)
		{
			return newestFirst;
		}
		for (String name : LogFiles.newestFirst(listNames(dir)))
		{
			Filepath file = dir.joinSegment(name);
			try (ReverseLineReader r = new ReverseLineReader(file.openFileChannel(StandardOpenOption.READ), chunk))
			{
				String line;
				while ((line = r.readLine()) != null)
				{
					TradeEvent ev = parse(gson, line);
					if (ev != null && MyTrades.isShown(ev))
					{
						newestFirst.add(ev);
						if (newestFirst.size() >= maxShown)
						{
							Collections.reverse(newestFirst);
							return newestFirst;
						}
					}
				}
			}
		}
		Collections.reverse(newestFirst);
		return newestFirst;
	}

	/**
	 * Stream every log line, oldest file first and each file front to back, as the raw object (for "acct") and the
	 * parsed event. Bad lines are skipped. For rebuilding totals from the whole log; this reads everything.
	 */
	static void forEachOldestFirst(Filepath dir, Gson gson, BiConsumer<JsonObject, TradeEvent> consumer) throws IOException
	{
		for (String name : LogFiles.oldestFirst(listNames(dir)))
		{
			forEachInFile(dir, name, gson, consumer);
		}
	}

	/** Stream one log file front to back; see {@link #forEachOldestFirst}. Does nothing if the file is missing. */
	static void forEachInFile(Filepath dir, String name, Gson gson, BiConsumer<JsonObject, TradeEvent> consumer) throws IOException
	{
		Filepath file = dir.joinSegment(name);
		if (!file.isFile())
		{
			return;
		}
		try (BufferedReader r = file.openBufferedReader())
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				if (line.isEmpty())
				{
					continue;
				}
				try
				{
					JsonObject obj = gson.fromJson(line, JsonObject.class);
					if (obj == null)
					{
						continue;
					}
					TradeEvent ev = gson.fromJson(obj, TradeEvent.class);
					if (ev != null && ev.getKind() != null)
					{
						consumer.accept(obj, ev);
					}
				}
				catch (RuntimeException ex)
				{
					log.debug("Skipping bad trade log line", ex);
				}
			}
		}
	}

	/** The event on one log line, or null if it doesn't parse or has no kind. "acct" is ignored. */
	static TradeEvent parse(Gson gson, String line)
	{
		try
		{
			TradeEvent ev = gson.fromJson(line, TradeEvent.class);
			return ev != null && ev.getKind() != null ? ev : null;
		}
		catch (RuntimeException ex)
		{
			log.debug("Skipping bad trade log line", ex);
			return null;
		}
	}
}

package com.deadmantoolkit;

import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Which files in the plugin folder make up the local trade log, and in what order. Pure.
 * <p>
 * The log is one file per month, {@code trades-YYYY-MM.jsonl}, plus the legacy {@code trades.jsonl} written by older
 * versions, which only holds trades from before the monthly files existed (so it is always the oldest).
 */
final class LogFiles
{
	static final String LEGACY_FILE = "trades.jsonl";
	private static final Pattern MONTHLY = Pattern.compile("^trades-([0-9]{4})-([0-9]{2})[.]jsonl$");

	private LogFiles()
	{
	}

	static boolean isMonthly(String name)
	{
		return name != null && MONTHLY.matcher(name).matches();
	}

	/** The month of a monthly log file's name, or null for any other name. */
	static YearMonth monthOf(String name)
	{
		Matcher m = name == null ? null : MONTHLY.matcher(name);
		if (m == null || !m.matches())
		{
			return null;
		}
		int month = Integer.parseInt(m.group(2));
		return month >= 1 && month <= 12 ? YearMonth.of(Integer.parseInt(m.group(1)), month) : null;
	}

	/**
	 * The log files that can hold events from {@code from} on, oldest first: monthly files of that month or later,
	 * plus the legacy file (it has no month). All of them when {@code from} is null.
	 */
	static List<String> fromMonth(List<String> names, YearMonth from)
	{
		List<String> out = new ArrayList<>();
		for (String n : oldestFirst(names))
		{
			YearMonth m = monthOf(n);
			if (from == null || m == null || !m.isBefore(from))
			{
				out.add(n);
			}
		}
		return out;
	}

	/** Monthly log files, newest month first, then the legacy file if present. Other names are ignored. */
	static List<String> newestFirst(List<String> names)
	{
		List<String> monthly = new ArrayList<>();
		boolean legacy = false;
		for (String n : names)
		{
			if (isMonthly(n))
			{
				monthly.add(n);
			}
			else if (LEGACY_FILE.equals(n))
			{
				legacy = true;
			}
		}
		// Zero-padded year and month, so name order is time order.
		monthly.sort(Collections.reverseOrder());
		if (legacy)
		{
			monthly.add(LEGACY_FILE);
		}
		return monthly;
	}

	/** The reverse of {@link #newestFirst}: the legacy file first, then each month oldest first. */
	static List<String> oldestFirst(List<String> names)
	{
		List<String> list = newestFirst(names);
		Collections.reverse(list);
		return list;
	}
}

package com.deadmantoolkit;

import net.runelite.api.GameState;

/**
 * Tells a real login (or world hop / reconnect) apart from the LOGGED_IN that follows every loading screen.
 * The client goes LOGGED_IN -> LOADING -> LOGGED_IN on each region change, so a LOGGED_IN only counts as a login
 * when the state before it (ignoring LOADING) was the login screen, logging in, hopping or a lost connection.
 * Client thread only.
 */
class LoginDetector
{
	/** The last game state seen other than LOADING, or null when unknown. */
	private GameState previous;
	/**
	 * Reset while a loading screen was showing (mid-login or mid region change): the next LOGGED_IN is treated as a
	 * login so the open offers still get sent, at the cost of at most one extra short late window.
	 */
	private boolean resetDuringLoading;

	/** Start over from the client's current state, e.g. when the plugin is enabled. */
	void reset(GameState current)
	{
		resetDuringLoading = current == GameState.LOADING;
		previous = resetDuringLoading ? null : current;
	}

	/** Feed a game state change. Returns true if it is a login. */
	boolean update(GameState state)
	{
		if (state == GameState.LOADING)
		{
			// Loading screens sit between the states we care about; skip over them.
			return false;
		}
		boolean login = isLogin(previous, state) || (resetDuringLoading && state == GameState.LOGGED_IN);
		resetDuringLoading = false;
		previous = state;
		return login;
	}

	/** True when moving from {@code previous} (ignoring LOADING) to {@code current} is a login. */
	static boolean isLogin(GameState previous, GameState current)
	{
		if (current != GameState.LOGGED_IN || previous == null)
		{
			return false;
		}
		switch (previous)
		{
			case LOGIN_SCREEN:
			case LOGIN_SCREEN_AUTHENTICATOR:
			case LOGGING_IN:
			case HOPPING:
			case CONNECTION_LOST:
				return true;
			default:
				return false;
		}
	}
}

package com.deadmantoolkit;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.Collection;
import java.util.TreeSet;
import java.util.stream.Collectors;
import java.util.concurrent.Executor;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import okhttp3.CacheControl;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Read side of the collection server. Requests run on OkHttp's pool; the public methods deliver their callbacks on the
 * Swing EDT, the package-private ones ({@link #itemAsync}, {@link #items}) on the OkHttp thread.
 */
@Slf4j
public class MarketClient
{
	/** Events per Market feed request; the panel also uses it to spot a possible gap in an incremental load. */
	public static final int RECENT_LIMIT = 60;
	private static final int ITEM_LIMIT = 40;
	/**
	 * The Market feed shows live fills only. GE History rows and imported RuneLite records are old trades with no real
	 * time, and a player's first connect sends dozens of them at once; they still count in the item views and prices.
	 * Older servers ignore this parameter; the panel filters too.
	 */
	static final String RECENT_KINDS = TradeEvent.FILL;
	/** Error messages passed to the {@code err} callbacks; {@link #shortReason} makes a status-line version. */
	public static final String UNREACHABLE = "Can't reach the Deadman Tool Kit server.";
	public static final String BAD_RESPONSE = "Unexpected server response.";
	private static final String SERVER_ERROR_PREFIX = "Server error (";
	/**
	 * Opt-in extra fields: confirmed / trusted figures and fill-only last prices. Older servers ignore the parameter
	 * and the fields stay null.
	 */
	static final String INCLUDE = "trust,fill";
	private static final Executor EDT = SwingUtilities::invokeLater;
	/** Runs callbacks on the OkHttp thread that received the response. */
	private static final Executor DIRECT = Runnable::run;

	private final OkHttpClient http;
	private final Gson gson;
	private final HttpUrl base;
	private final int world;

	MarketClient(OkHttpClient http, Gson gson, HttpUrl base, int world)
	{
		this.http = http;
		this.gson = gson;
		this.base = base;
		this.world = world;
	}

	/**
	 * The Market feed and headline stats.
	 *
	 * @param afterId only events with a higher id, or 0 for the newest page. Older servers ignore it and return the
	 *                newest page, so callers must de-duplicate by id.
	 */
	public void recent(long afterId, Consumer<MarketData.Recent> ok, Consumer<String> err)
	{
		HttpUrl.Builder url = url("v1/recent")
			.addQueryParameter("limit", String.valueOf(RECENT_LIMIT))
			.addQueryParameter("kinds", RECENT_KINDS);
		if (afterId > 0)
		{
			url.addQueryParameter("after", String.valueOf(afterId));
		}
		get(url, false, MarketData.Recent.class, EDT, ok, err);
	}

	/** @param fresh skip any HTTP cache (a refresh the user asked for, or right after an upload) */
	public void item(int itemId, boolean fresh, Consumer<MarketData.ItemDetail> ok, Consumer<String> err)
	{
		get(url("v1/item/" + itemId).addQueryParameter("limit", String.valueOf(ITEM_LIMIT)), fresh,
			MarketData.ItemDetail.class, EDT, ok, err);
	}

	/**
	 * Price history. Newer servers return just {@code range}; older ones ignore it and return a year's worth of
	 * {@code step} buckets (365 of them), so callers trim to the range.
	 *
	 * @param range how far back, as the server names it (24h, 7d, 30d, 90d or 1y)
	 * @param step  bucket size, as the server names it (5m, 1h, 6h or 24h)
	 */
	public void series(int itemId, String range, String step, boolean fresh, Consumer<MarketData.Series> ok,
		Consumer<String> err)
	{
		get(url("v1/item/" + itemId + "/series").addQueryParameter("range", range).addQueryParameter("step", step),
			fresh, MarketData.Series.class, EDT, ok, err);
	}

	/**
	 * One item's summary for the GE price line, with callbacks on the OkHttp thread (never the EDT or client thread).
	 * Asks for a single trade: only the summary is used.
	 */
	void itemAsync(int itemId, Consumer<MarketData.ItemDetail> ok, Consumer<String> err)
	{
		get(url("v1/item/" + itemId).addQueryParameter("limit", "1"), false, MarketData.ItemDetail.class, DIRECT, ok, err);
	}

	/**
	 * Summaries of a few items, with callbacks on the OkHttp thread. Older servers ignore {@code ids} and return every
	 * item, so callers filter ({@link OfferQuotes#filter}).
	 */
	void items(Collection<Integer> ids, boolean fresh, Consumer<MarketData.ItemsResponse> ok, Consumer<String> err)
	{
		String list = new TreeSet<>(ids).stream().map(String::valueOf).collect(Collectors.joining(","));
		get(url("v1/items").addQueryParameter("ids", list), fresh, MarketData.ItemsResponse.class, DIRECT, ok, err);
	}

	/** The error message for an HTTP error status. */
	static String serverError(int code)
	{
		return SERVER_ERROR_PREFIX + code + ").";
	}

	/**
	 * A few words for a status line from an error message: "server unreachable", "server error 500" or "bad
	 * response"; anything else as given, without a trailing period.
	 */
	public static String shortReason(String message)
	{
		if (message == null || message.isEmpty())
		{
			return "unknown error";
		}
		if (UNREACHABLE.equals(message))
		{
			return "server unreachable";
		}
		if (BAD_RESPONSE.equals(message))
		{
			return "bad response";
		}
		if (message.startsWith(SERVER_ERROR_PREFIX) && message.endsWith(").") && message.length() > SERVER_ERROR_PREFIX.length() + 2)
		{
			return "server error " + message.substring(SERVER_ERROR_PREFIX.length(), message.length() - 2);
		}
		return message.endsWith(".") ? message.substring(0, message.length() - 1) : message;
	}

	private HttpUrl.Builder url(String path)
	{
		return base.newBuilder()
			.addPathSegments(path)
			.addQueryParameter("world", String.valueOf(world))
			.addQueryParameter("include", INCLUDE);
	}

	/** @param callbacks where {@code ok} / {@code err} run */
	private <T> void get(HttpUrl.Builder url, boolean fresh, Class<T> type, Executor callbacks, Consumer<T> ok,
		Consumer<String> err)
	{
		Request.Builder req = new Request.Builder().url(url.build()).get();
		if (fresh)
		{
			req.cacheControl(CacheControl.FORCE_NETWORK);
		}
		http.newCall(req.build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Market request failed: {}", call.request().url(), e);
				callbacks.execute(() -> err.accept(UNREACHABLE));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (response)
				{
					ResponseBody body = response.body();
					if (!response.isSuccessful() || body == null)
					{
						int code = response.code();
						callbacks.execute(() -> err.accept(serverError(code)));
						return;
					}
					T data = gson.fromJson(body.charStream(), type);
					if (data == null)
					{
						callbacks.execute(() -> err.accept(BAD_RESPONSE));
						return;
					}
					callbacks.execute(() -> ok.accept(data));
				}
				catch (RuntimeException e)
				{
					log.debug("Bad market response", e);
					callbacks.execute(() -> err.accept(BAD_RESPONSE));
				}
			}
		});
	}
}

package com.deadmantoolkit;

import java.util.Collections;
import java.util.List;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import net.runelite.client.util.Text;

/**
 * Response bodies of the collection server's read API, parsed by Gson. Field names are the server's JSON contract.
 * Some fields aren't shown in the panel yet; they're kept to document what the server sends.
 * <p>
 * List fields default to empty when the server leaves them out. That only works while each class keeps its implicit
 * no-arg constructor, so don't add constructors or make the fields final.
 * <p>
 * Every class has value equality, so the panel can skip re-rendering when a refresh returns the same data.
 * <p>
 * Fields added for {@code ?include=trust,fill} are boxed and stay null when an older server leaves them out.
 */
public final class MarketData
{
	private MarketData()
	{
	}

	/**
	 * An item name from the server, as plain text: the server keeps what players' clients sent, so it is never trusted
	 * as markup (Swing renders text starting with "&lt;html&gt;" as HTML, which could even load remote images). Tags are
	 * removed and no angle bracket is left.
	 */
	static String plainName(String name)
	{
		if (name == null)
		{
			return null;
		}
		return Text.removeTags(name).replace("<", "").replace(">", "").trim();
	}

	@Getter
	@EqualsAndHashCode
	public static class Recent
	{
		private Stats stats;
		private List<FeedEvent> events = Collections.emptyList();
	}

	@Getter
	@EqualsAndHashCode
	public static class Stats
	{
		private int openBids;
		private int openAsks;
		private long units24;
		private long gp24;
		private int reporters24;
	}

	@Getter
	@EqualsAndHashCode
	public static class FeedEvent
	{
		private long id;
		private String kind;
		private String side;
		private int itemId;
		private String name;
		private int qty;
		private long price;
		private Long total;
		private long ts;
		private boolean late;
		/** When the server received the event (unix s). */
		private long receivedAt;
		/** Fills only, with ?include=trust: whether the fill is confirmed; null otherwise. */
		private Boolean confirmed;

		public String getName()
		{
			return plainName(name);
		}
	}

	@Getter
	@EqualsAndHashCode
	public static class ItemDetail
	{
		private int id;
		private String name;
		private Summary summary;
		private List<Trade> trades = Collections.emptyList();
		private Book book;

		public String getName()
		{
			return plainName(name);
		}
	}

	@Getter
	@EqualsAndHashCode
	public static class Summary
	{
		private Long lastBuy;
		private Long lastBuyTime;
		private Long lastSell;
		private Long lastSellTime;
		private long vol24;
		private Long avgBuy24;
		private Long avgSell24;
		private Long bestBid;
		private Long bestAsk;

		// ?include=trust (newer servers; null on older ones). "Confirmed" fills come from trusted sources at a normal
		// price, or were matched by an independent counterparty.
		/** Median price of recent confirmed fills, one vote per player; null when there aren't enough. */
		private Long trustedPrice;
		/** How many players' fills that median is based on. */
		private Integer trustedVotes;
		private Long trustedPriceTime;
		private Long confVol24;
		private Long unconfVol24;
		/** Best bid / ask among open offers from trusted sources near the trusted price. */
		private Long trustedBestBid;
		private Long trustedBestAsk;
		// ?include=fill: the latest live fills (GE History rows excluded).
		private Long lastFillBuy;
		private Long lastFillBuyTime;
		private Long lastFillSell;
		private Long lastFillSellTime;
		private Long confAvgBuy24;
		private Long confAvgSell24;
		private Long lastConfBuy;
		private Long lastConfBuyTime;
		private Long lastConfSell;
		private Long lastConfSellTime;
	}

	@Getter
	@EqualsAndHashCode
	public static class Trade
	{
		private String kind;
		private String side;
		private int qty;
		private long price;
		private long ts;
		private boolean late;
