/**
 * One-line banner at the top of the panel counting down to the next weekend breach, or showing the current one.
 * Driven by the panel's 1 s ticker; EDT only.
 */
class BreachBanner
{
	private static final Color ACTIVE_BG = new Color(0x7a2e12);
	private static final int HEIGHT = 22;

	private final JPanel panel = new JPanel(new BorderLayout());
	private final JLabel label = new JLabel();

	/** Next breach start from the in-game message, or null. */
	private Instant correction;
	/** Developer-mode breach preview: added to the real clock (zero normally). */
	private Duration offset = Duration.ZERO;
	private BreachSchedule.Phase shownPhase;

	BreachBanner()
	{
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(new EmptyBorder(3, 6, 3, 6));
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
		panel.setPreferredSize(new Dimension(0, HEIGHT));
		panel.setToolTipText("Weekend breaches at 02/06/10/14/18/22 UTC; corrected from the in-game message when seen.");
		label.setFont(FontManager.getRunescapeSmallFont());
		panel.add(label, BorderLayout.CENTER);
		tick();
	}

	JComponent getComponent()
	{
		return panel;
	}

	/** The game said when the next breach starts. */
	void setCorrection(Instant start)
	{
		correction = start;
		tick();
	}

	/**
	 * Developer-mode breach preview: run the banner on the real clock shifted by {@code offset} (zero = the real
	 * clock), and drop any correction from a game message.
	 */
	void preview(Duration offset)
	{
		this.offset = offset == null ? Duration.ZERO : offset;
		correction = null;
		tick();
	}

	void tick()
	{
		Instant now = Instant.now().plus(offset);
		if (correction != null && now.isAfter(correction.plus(BreachSchedule.SPAWN).plus(BreachSchedule.DESPAWN)))
		{
			correction = null;
		}
		BreachSchedule.State state = BreachSchedule.state(now, correction);
		String text = BreachText.of(state, now, ZoneId.systemDefault());
		if (!text.equals(label.getText()))
		{
			label.setText(text);
		}
		if (state.getPhase() != shownPhase)
		{
			shownPhase = state.getPhase();
			switch (shownPhase)
			{
				case ACTIVE:
					panel.setBackground(ACTIVE_BG);
					label.setForeground(Color.WHITE);
					break;
				case DESPAWN:
					panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
					label.setForeground(ColorScheme.BRAND_ORANGE);
					break;
				default:
					panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
					label.setForeground(ColorScheme.TEXT_COLOR);
					break;
			}
		}
	}
}

package com.deadmantoolkit.ui;

import com.deadmantoolkit.BreachSchedule;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

/**
 * The breach banner's text. Pure: the time and zone are passed in.
 */
final class BreachText
{
	private static final DateTimeFormatter LOCAL_TIME = DateTimeFormatter.ofPattern("EEE HH:mm", Locale.ENGLISH);

	private BreachText()
	{
	}

	static String of(BreachSchedule.State state, Instant now, ZoneId zone)
	{
		Duration left = Duration.between(now, state.getAt());
		switch (state.getPhase())
		{
			case ACTIVE:
				return "Breach active, spawning ends in " + clock(left);
			case DESPAWN:
				return "Breach bosses despawn in ~" + clock(left);
			default:
				return "Next breach in " + countdown(left) + " (" + LOCAL_TIME.format(state.getAt().atZone(zone)) + ")";
		}
	}

	/** mm:ss, never negative. Minutes aren't capped at 59 (phases are at most 30 minutes anyway). */
	static String clock(Duration d)
	{
		long s = Math.max(0, d.getSeconds());
		return String.format("%02d:%02d", s / 60, s % 60);
	}

	/** "1d 4h 12m", dropping leading zero units ("4h 0m", "12m"), and "<1m" under a minute. */
	static String countdown(Duration d)
	{
		long totalMinutes = Math.max(0, d.getSeconds()) / 60;
		if (totalMinutes == 0)
		{
			return "<1m";
		}
		long days = totalMinutes / (24 * 60);
		long hours = totalMinutes / 60 % 24;
		long minutes = totalMinutes % 60;
		if (days > 0)
		{
			return days + "d " + hours + "h " + minutes + "m";
		}
		if (hours > 0)
		{
			return hours + "h " + minutes + "m";
		}
		return minutes + "m";
	}
}

package com.deadmantoolkit.ui;

import com.deadmantoolkit.MarketData;
import java.util.ArrayList;
import java.util.List;

/**
 * The price chart's time ranges and the bucket size requested for each. The chart always spans the whole range,
 * whatever data comes back.
 */
enum ChartRange
{
	H24("24h", "24 hours", 86_400, "5m", 300, 6),
	D7("7d", "7 days", 7 * 86_400, "1h", 3_600, 3),
	D30("30d", "30 days", 30 * 86_400, "6h", 21_600, 2),
	D90("90d", "90 days", 90 * 86_400, "6h", 21_600, 3),
	Y1("1y", "year", 365 * 86_400, "24h", 86_400, 3);

	static final ChartRange DEFAULT = D7;

	private final String label;
	private final String longLabel;
	private final long seconds;
	private final String step;
	private final long stepSeconds;
	private final int maxGapBuckets;

	ChartRange(String label, String longLabel, long seconds, String step, long stepSeconds, int maxGapBuckets)
	{
		this.label = label;
		this.longLabel = longLabel;
		this.seconds = seconds;
		this.step = step;
		this.stepSeconds = stepSeconds;
		this.maxGapBuckets = maxGapBuckets;
	}

	/** Button text, and the server's name for the range (the series request's range parameter). */
	String label()
	{
		return label;
	}

	/** For "No trades in the last ...". */
	String longLabel()
	{
		return longLabel;
	}

	long seconds()
	{
		return seconds;
	}

	/** The server's name for the bucket size requested with this range (the step parameter). */
	String step()
	{
		return step;
	}

	long stepSeconds()
	{
		return stepSeconds;
	}

	/** Two points further apart than this many buckets aren't joined by a line. */
	int maxGapBuckets()
	{
		return maxGapBuckets;
	}

	/**
	 * The buckets overlapping the range ending at {@code now} (unix s), in time order: a bucket that starts before
	 * the range but ends inside it is kept (its trades are in the range). Older servers ignore the range and send more
	 * history, so this always runs.
	 */
	List<MarketData.Point> trim(List<MarketData.Point> points, long now)
	{
		List<MarketData.Point> out = new ArrayList<>();
		if (points == null)
		{
			return out;
		}
		long from = now - seconds;
		for (MarketData.Point p : points)
		{
			if (p != null && p.getTimestamp() + stepSeconds() > from)
			{
				out.add(p);
			}
		}
		out.sort((a, b) -> Long.compare(a.getTimestamp(), b.getTimestamp()));
		return out;
	}
}

