		this.worldEvents = new WorldEventsList(pointArrow);
		this.devTools = devTools;
		this.itemManager = itemManager;
		this.market = market;
		this.myTrades = myTrades;
		this.privacyUrl = base.newBuilder().addPathSegment("privacy").build().toString();
