	 * @param arrowAt where the hint arrow points (that line is highlighted), or null
	 */
	public void setWorldEvents(List<WorldEvents.Event> events, WorldPoint arrowAt)
	{
		worldEvents.set(events, arrowAt);
	}

	/** Developer-mode breach preview: shift the breach timer's clock (zero = real) and drop any correction. */
	public void setBreachPreview(Duration offset)
	{
		breachBanner.preview(offset);
	}

	/** "Import RuneLite GE history" was clicked (either link). */
	private void startImport()
	{
		if (previewFresh)
		{
			// In the fresh-install preview, Import only ends the preview.
			setFreshPreview(false);
			return;
		}
		if (importRunning)
		{
			return;
		}
		importRunning = true;
		updateImportLinks();
		boolean started = importAction.start(result ->
		{
			importRunning = false;
			importResult = result;
			updateImportLinks();
		});
		if (!started)
		{
			importRunning = false;
			importResult = RuneLiteImportAction.Result.problem("An import is already running.");
			updateImportLinks();
		}
	}

	private void updateImportLinks()
	{
		RuneLiteImportAction.Result shown = previewFresh ? null : importResult;
		welcomeImport.setState(importRunning, shown);
		mineImport.setState(importRunning, shown);
	}

	private void dismissImportNotice()
	{
		importNotice = null;
		updateWelcome();
	}

	private void updateWelcome()
	{
		// The fresh-install preview: not connected, GE History not imported (when logged in), no notices yet.
		Boolean imported = previewFresh && historyImported != null ? Boolean.FALSE : historyImported;
		Integer notice = previewFresh ? null : importNotice;
		welcomeCard.update(Onboarding.state(effectiveConnected(), imported, notice), Onboarding.needsLogin(imported), notice);
		// One import link at a time: the welcome card's while it shows its import block.
		homeView.setMineExtraHidden(welcomeCard.showsImportLink());
	}

	/** Reload whatever is on screen. Skipped while the panel is hidden; {@link #onActivate} reloads it. */
	void refresh()
	{
		refresh(false);
	}

	/** @param fresh the user asked for it: skip HTTP caches */
	private void refresh(boolean fresh)
	{
		if (!active)
		{
			return;
		}
		if (CARD_ITEM.equals(currentCard) && itemView.hasItem())
		{
			itemView.load(itemView.getCurrentItem(), fresh);
			return;
		}
		if (homeView.isShowingMine())
		{
			homeView.showMine(shownMyTrades());
			return;
		}
		if (!effectiveConnected())
		{
			homeView.showNotConnected();
			return;
		}
		loadFeed(feedFullNext || lastFeedId <= 0 || feedPollsSinceFull >= FULL_FEED_EVERY);
	}

	/**
	 * Load the Market feed. Incremental loads ask only for events newer than the ones we have (servers that ignore
	 * "after" send the newest page, de-duplicated). A full load asks for the newest page and merges it with what we
	 * have, unless it doesn't connect to it (a gap) or the ids went back (a different or reset server).
	 */
	private void loadFeed(boolean full)
	{
		long previous = lastFeedId;
		long after = full ? 0 : previous;
		int generation = feedGeneration;
		market.recent(after, r ->
		{
			if (generation != feedGeneration)
			{
				return;
			}
			List<MarketData.FeedEvent> events = r.getEvents();
			if (!full && FeedMerge.possibleGap(events, after, MarketClient.RECENT_LIMIT))
			{
				// More happened than one page holds, and we can't tell which page this is (oldest or newest after
				// the id): fetch the newest page instead, which every server returns the same way.
				loadFeed(true);
				return;
			}
			if (full)
			{
				boolean restarted = FeedMerge.idsWentBack(events, previous);
				long base = restarted ? 0 : previous;
				feedEvents = FeedMerge.merge(restarted ? Collections.emptyList() : feedEvents, events, base,
					MarketClient.RECENT_LIMIT);
				lastFeedId = FeedMerge.maxId(events, restarted ? 0 : lastFeedId);
				feedFullNext = false;
				feedPollsSinceFull = 0;
			}
			else
			{
				feedEvents = FeedMerge.merge(feedEvents, events, after, MarketClient.RECENT_LIMIT);
				lastFeedId = FeedMerge.maxId(events, lastFeedId);
				feedPollsSinceFull++;
			}
			if (r.getStats() != null)
			{
				feedStats = r.getStats();
			}
			if (!homeView.isShowingMine() && CARD_HOME.equals(currentCard))
			{
				homeView.showMarket(feedStats, feedEvents);
			}
		}, err ->
		{
			if (generation != feedGeneration)
			{
				return;
			}
			// Whatever went wrong (server down, restarted, replaced), start over from the newest page next time.
			feedFullNext = true;
			if (!homeView.isShowingMine() && CARD_HOME.equals(currentCard))
			{
				homeView.showError(err);
			}
		});
	}

	/** A trade of yours was recorded, or the local log finished loading. */
	public void onMyTradesChanged()
	{
		if (!active)
		{
			return;
		}
		if (CARD_HOME.equals(currentCard) && homeView.isShowingMine())
		{
			homeView.showMine(shownMyTrades());
		}
		else if (CARD_ITEM.equals(currentCard))
		{
			itemView.updateLocal();
		}
	}

	/** Your open offers changed (placed, filled, cancelled, collected, or another account logged in). */
	public void onOffersChanged(List<ActiveOffer> offers)
	{
		this.offers = offers;
		offersSection.setOffers(shownOffers());
		if (active && CARD_ITEM.equals(currentCard))
		{
			itemView.updateLocal();
		}
	}

	/** Your open offers were compared with the market again (or re-evaluated). */
	public void onOfferReport(OfferReport report)
	{
		offerReport = report;
		offersSection.setReport(shownReport());
		if (active && CARD_ITEM.equals(currentCard))
		{
			itemView.updateLocal();
		}
	}

	/** New profit numbers (a trade was counted, another account logged in, or a rebuild ran). */
	public void onProfit(ProfitSnapshot snapshot)
	{
		profit = snapshot;
		profitSection.setSnapshot(shownProfit());
		if (active && CARD_ITEM.equals(currentCard))
		{
			itemView.updateLocal();
		}
	}

	/** An upload with trades of these items reached the server. */
	public void onUploaded(Set<Integer> itemIds)
	{
		if (active && CARD_ITEM.equals(currentCard))
		{
			itemView.onUploaded(itemIds);
		}
	}

	/* ------------------------------------------------------------ search */

	private void runSearch()
	{
		String q = searchField.getText().trim();
		if (q.length() < 2)
		{
			if (CARD_SEARCH.equals(currentCard))
			{
				leaveSearch();
			}
			return;
		}
		searchResults.removeAll();
		List<ItemPrice> results = itemManager.search(q);
		if (results.isEmpty())
		{
			searchResults.add(wrapText("No tradeable items match \"" + q + "\".", ColorScheme.LIGHT_GRAY_COLOR));
		}
		for (ItemPrice ip : results.subList(0, Math.min(MAX_SEARCH_RESULTS, results.size())))
		{
			searchResults.add(tradeRow(itemManager, ip.getId(), ip.getName(), null, null, this::openItem));
			searchResults.add(Box.createVerticalStrut(2));
		}
		searchResults.revalidate();
		searchResults.repaint();
		showCard(CARD_SEARCH);
	}

	private void openFirstResult()
	{
		String q = searchField.getText().trim();
		if (q.length() < 2)
		{
			// Too short to mean one item (a single letter matches hundreds): no jump to whichever sorts first.
			return;
		}
		searchDebounce.stop();
		List<ItemPrice> results = itemManager.search(q);
		if (!results.isEmpty())
		{
			openItem(results.get(0).getId(), results.get(0).getName());
		}
	}

	/**
	 * Back from the search results to the item (if one is open) or home, reloaded: neither was refreshed while the
	 * results covered it (the item view isn't, and home may have missed the newest feed page).
	 */
	private void leaveSearch()
	{
		showCard(itemView.hasItem() ? CARD_ITEM : CARD_HOME);
		feedFullNext = true;
		refresh();
	}

	/* -------------------------------------------------------------- item */

	/** Open the item view (from search, a feed row, the GE, or the right-click menu). */
	public void openItem(int itemId, String name)
	{
		searchDebounce.stop();
		if (!searchField.getText().isEmpty())
		{
			searchField.setText("");
		}
		boolean other = !itemView.hasItem() || itemView.getCurrentItem() != itemId;
		itemView.open(itemId, name);
		if (other && CARD_ITEM.equals(currentCard))
		{
			// Same card, so showCard keeps the scroll position: a different item starts at its top.
			JViewport vp = (JViewport) SwingUtilities.getAncestorOfClass(JViewport.class, this);
			if (vp != null)
			{
				vp.setViewPosition(new Point(0, 0));
			}
		}
		showCard(CARD_ITEM);
		// When hidden (opened from the game), onActivate loads it once the panel is shown.
		if (active)
		{
			itemView.load(itemId);
		}
	}

	/**
	 * Show a card. A different card starts at its top, except that going back home returns to where home was
	 * scrolled to when you left it.
	 */
	private void showCard(String card)
	{
		boolean changed = !card.equals(currentCard);
		JViewport vp = changed ? (JViewport) SwingUtilities.getAncestorOfClass(JViewport.class, this) : null;
		if (vp != null && CARD_HOME.equals(currentCard))
		{
			homeScroll = vp.getViewPosition();
		}
		currentCard = card;
		cards.show(cardPanel, card);
		cardPanel.revalidate();
		if (vp == null)
		{
			return;
		}
		vp.setViewPosition(new Point(0, 0));
		Point back = CARD_HOME.equals(card) ? homeScroll : null;
		if (back != null && back.y > 0)
		{
			SwingUtilities.invokeLater(() ->
			{
				if (!CARD_HOME.equals(currentCard))
				{
					return;
				}
				vp.validate();
				int max = Math.max(0, vp.getViewSize().height - vp.getExtentSize().height);
				vp.setViewPosition(new Point(0, Math.min(back.y, max)));
			});
		}
	}
}

package com.deadmantoolkit.ui;

/**
 * Developer-mode-only actions behind the panel's "Dev tools" row. The plugin passes null on normal installs, and the
 * row isn't built at all. Called on the EDT; implementations must not block.
 */
public interface DevTools
{
	/** Breach preview, same as {@code ::breach <action>}: "soon", "active", "despawn" or "off". */
	void breach(String action);

	/** Re-arm the one-time chat hint and show it in the chatbox now, so it can be previewed. */
	void resetHints();

	/** Test world events, same as {@code ::dgt events <action>}: "sample" or "clear". */
	void worldEvents(String action);
}

package com.deadmantoolkit.ui;

import com.deadmantoolkit.MarketData;
import com.deadmantoolkit.TradeEvent;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Merges an incremental Market feed response ({@code /v1/recent?after=<id>}) into what the panel already shows. Pure.
 * <p>
 * Works with servers that honour {@code after} and with older ones that ignore it (they return the newest rows, which
 * overlap what we have and are de-duplicated by id), whatever order the rows come in.
 */
final class FeedMerge
{
	/** Most events kept for the feed. */
	static final int CAP = 200;

	private FeedMerge()
	{
	}

	/**
	 * @param current  what the feed holds now, newest first
	 * @param incoming the response's events (any order, may include non-trades from servers that ignore kinds)
	 * @param afterId  the id the request asked for events after, or 0 for a full load
	 * @param limit    the request's limit; a full page of only newer events may mean events were skipped
	 * @return live fills only, de-duplicated by id, newest (highest id) first, at most {@code cap}
	 */
	static List<MarketData.FeedEvent> merge(List<MarketData.FeedEvent> current, List<MarketData.FeedEvent> incoming,
		long afterId, int limit, int cap)
	{
		Map<Long, MarketData.FeedEvent> byId = new LinkedHashMap<>();
		if (!possibleGap(incoming, afterId, limit))
		{
			addAll(byId, current);
		}
		// Incoming wins on equal ids: it is the server's latest view of that event.
		addAll(byId, incoming);
		List<MarketData.FeedEvent> out = liveFills(byId.values());
		out.sort((a, b) -> Long.compare(b.getId(), a.getId()));
		return out.size() > cap ? new ArrayList<>(out.subList(0, cap)) : out;
	}

	static List<MarketData.FeedEvent> merge(List<MarketData.FeedEvent> current, List<MarketData.FeedEvent> incoming,
		long afterId, int limit)
	{
		return merge(current, incoming, afterId, limit, CAP);
	}

	/**
	 * True when an incremental response is a full page of events all newer than {@code afterId}: there may be more
	 * between them and what we have, so the old events are dropped rather than shown with a hole in between.
	 */
	static boolean possibleGap(List<MarketData.FeedEvent> incoming, long afterId, int limit)
	{
		if (afterId <= 0 || incoming.isEmpty() || incoming.size() < limit)
		{
			return false;
		}
		for (MarketData.FeedEvent e : incoming)
		{
			if (e.getId() <= afterId)
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Only live fills. Offers placed or cancelled aren't trades and were misread as purchases; GE History rows and
	 * imported records are old trades with no real time ({@link com.deadmantoolkit.MarketClient#RECENT_KINDS}). The
	 * request already asks the server for fills only; older servers ignore that, so filter here too.
	 */
	static List<MarketData.FeedEvent> liveFills(Collection<MarketData.FeedEvent> events)
	{
		List<MarketData.FeedEvent> trades = new ArrayList<>();
		for (MarketData.FeedEvent e : events)
		{
			if (TradeEvent.FILL.equals(e.getKind()))
			{
				trades.add(e);
			}
		}
		return trades;
	}

	/**
	 * True when a full (newest page) response shows that the server's ids are lower than the ones we have: a different
	 * or reset server. An empty newest page means the server has no events at all. The old feed must then be dropped.
	 */
	static boolean idsWentBack(List<MarketData.FeedEvent> newestPage, long previousMaxId)
	{
		return previousMaxId > 0 && maxId(newestPage, 0) < previousMaxId;
	}

	/** The highest id in {@code events}, or {@code previous} if that is higher. */
	static long maxId(Collection<MarketData.FeedEvent> events, long previous)
	{
		long max = previous;
		for (MarketData.FeedEvent e : events)
		{
			max = Math.max(max, e.getId());
		}
		return max;
	}

	private static void addAll(Map<Long, MarketData.FeedEvent> byId, List<MarketData.FeedEvent> events)
	{
		for (MarketData.FeedEvent e : events)
		{
			byId.put(e.getId(), e);
		}
	}
}

package com.deadmantoolkit.ui;

import com.deadmantoolkit.TradeEvent;
import java.time.Instant;
import java.util.Locale;
import net.runelite.client.util.QuantityFormatter;

/**
 * Display text for trades, prices and times.
 */
final class Format
{
	/** Shown instead of a time for trades read from the GE History tab, which has no timestamps. */
	static final String HISTORY_MARK = "history";
	/** Shown with trades imported from RuneLite's GE history, whose time is only approximate. */
	static final String IMPORTED_MARK = "imported";
	/** Tooltip for an imported trade. */
	static final String IMPORTED_TIP = "Imported from RuneLite's Grand Exchange history. The time is approximate: when"
		+ " RuneLite saw the offer complete (after a logout, the next login).";

	private Format()
	{
	}

	static String describe(String kind, String side, int qty, long price)
	{
		String q = QuantityFormatter.formatNumber(qty), p = QuantityFormatter.formatNumber(price);
		boolean buy = TradeEvent.BUY.equals(side);
		String verb = buy ? "Bought" : "Sold";
		switch (kind)
		{
			case TradeEvent.PLACED:
				return (buy ? "Buy" : "Sell") + " offer " + q + " × " + p;
			case TradeEvent.CANCELLED:
				return "Cancelled " + (buy ? "buy" : "sell") + ", " + q + " left";
			default:
				return verb + " " + q + " × " + p;
		}
	}

	/** One trade both sides of which were reported (two plugin users traded with each other). */
	static String traded(int qty, long price)
	{
		return "Traded " + QuantityFormatter.formatNumber(qty) + " × " + QuantityFormatter.formatNumber(price);
	}

	/** Exact below 10m gp, stack format (e.g. 12.5M) above. "-" when unknown. */
	static String gp(Long v)
	{
		if (v == null)
		{
			return "-";
		}
		return v < 10_000_000 ? QuantityFormatter.formatNumber(v) : QuantityFormatter.quantityToStackSize(v);
	}

	/** A compact gp amount with its sign, e.g. "+1.25M", "-350K", "0". */
	static String signedGp(long v)
	{
		if (v == 0)
		{
			return "0";
		}
		if (v == Long.MIN_VALUE)
		{
			v++;
		}
		return (v > 0 ? "+" : "-") + QuantityFormatter.quantityToStackSize(Math.abs(v));
	}

	/** A compact unsigned gp amount, e.g. "1.25M", "950K", "1,500". */
	static String shortGp(long v)
	{
		return QuantityFormatter.quantityToStackSize(v);
	}

	/** How long ago {@code ts} (unix s) was, e.g. "now", "5m", "3h", "2d". Empty when unknown. */
	static String ago(Long ts)
	{
		return ago(ts, Instant.now().getEpochSecond());
	}

	static String ago(Long ts, long now)
	{
		if (ts == null || ts == 0)
		{
			return "";
		}
		long s = Math.max(0, now - ts);
		if (s < 60)
		{
			return "now";
		}
		if (s < 3600)
		{
			return (s / 60) + "m";
		}
		if (s < 86400)
		{
			return (s / 3600) + "h";
		}
		return (s / 86400) + "d";
	}

	/**
	 * The time column for a trade: {@link #HISTORY_MARK} for GE History rows, "imported ~3d" (an approximate age) for
	 * imported trades, otherwise {@link #ago}.
	 */
	static String when(String kind, Long ts)
	{
		if (TradeEvent.HISTORY.equals(kind))
		{
			return HISTORY_MARK;
		}
		if (TradeEvent.IMPORTED.equals(kind))
		{
			String age = approxAgo(ts);
			return age.isEmpty() ? IMPORTED_MARK : IMPORTED_MARK + " " + age;
		}
		return ago(ts);
	}

	/** "~3d" (an approximate age), or empty when unknown or under a minute. */
	static String approxAgo(Long ts)
	{
		String a = ago(ts);
		return a.isEmpty() || "now".equals(a) ? "" : "~" + a;
	}

	/**
	 * The right-hand column of a two-line item row: {@link #when}, except that an imported trade gets its approximate
	 * age above "imported".
	 */
	static String whenTwoLine(String kind, Long ts)
	{
		if (!TradeEvent.IMPORTED.equals(kind))
		{
			return when(kind, ts);
		}
		String age = approxAgo(ts);
		return age.isEmpty() ? IMPORTED_MARK : "<html>" + age + "<br>" + IMPORTED_MARK + "</html>";
	}

	/** The time a Market feed row shows: when it reached the server, but an imported trade's own (approximate) time. */
	static long feedTime(String kind, long receivedAt, long ts)
	{
		return TradeEvent.IMPORTED.equals(kind) ? ts : receivedAt;
	}

	private static final long[] UNITS = {1_000_000_000L, 1_000_000L, 1_000L};
	private static final String[] UNIT_SUFFIX = {"B", "M", "K"};

	/**
	 * A compact gp amount for chart axes: the value's own unit (K/M/B) with as many decimals (up to 3, 2 for K) as
	 * {@code step} needs, so labels a step apart never look the same (e.g. 1.25M and 1.30M; 2.1B; 950K). When that
	 * isn't enough (nearly flat data at a high price) it is the exact number with separators, never a smaller unit
	 * (which read as "1000.0K" or "2,100,002K").
	 *
	 * @param step the difference between neighbouring labels (the tick step)
	 */
	static String compactGp(long v, long step)
	{
		long s = Math.max(1, Math.abs(step));
		long a = Math.abs(v);
		for (int i = 0; i < UNITS.length; i++)
		{
			long unit = UNITS[i];
			if (a < unit)
			{
				continue;
			}
			// Decimals needed so one step is visible: the largest power of ten (unit / 10^d) no bigger than the step.
			int d = 0;
			long res = unit;
			while (res > s && d < 4)
			{
				res /= 10;
				d++;
			}
			// K never needs 3 decimals: "1,002" is as short as "1.002K".
			if (d > (unit == 1_000L ? 2 : 3))
			{
				break;
			}
			String num = d == 0 ? QuantityFormatter.formatNumber(Math.round((double) a / unit))
				: String.format(Locale.ROOT, "%." + d + "f", (double) a / unit);
			return (v < 0 ? "-" : "") + num + UNIT_SUFFIX[i];
		}
		return QuantityFormatter.formatNumber(v);
	}

	/** A short amount for a single value (not an axis), e.g. the chart's volume scale: "1M", "2.1B", "523". */
	static String compactAmount(long v)
	{
		return QuantityFormatter.quantityToStackSize(v);
	}

	/** "just now", "12s ago", "3m ago", "2h ago", "1d ago" for an epoch-ms time; empty when never (0). */
	static String updatedAgo(long ms, long nowMs)
	{
		if (ms <= 0)
		{
			return "";
		}
		long s = Math.max(0, nowMs - ms) / 1000;
		if (s < 5)
		{
			return "just now";
		}
		if (s < 60)
		{
			return s + "s ago";
		}
		if (s < 3600)
		{
			return (s / 60) + "m ago";
		}
		if (s < 86400)
		{
			return (s / 3600) + "h ago";
		}
		return (s / 86400) + "d ago";
	}
}

package com.deadmantoolkit.ui;

import static com.deadmantoolkit.ui.Format.describe;
import static com.deadmantoolkit.ui.Format.when;
import static com.deadmantoolkit.ui.PanelComponents.column;
import static com.deadmantoolkit.ui.PanelComponents.iconButton;
import static com.deadmantoolkit.ui.PanelComponents.mutedLabel;
import static com.deadmantoolkit.ui.PanelComponents.styleTab;
import static com.deadmantoolkit.ui.PanelComponents.tabButton;
import static com.deadmantoolkit.ui.PanelComponents.tradeRow;
import static com.deadmantoolkit.ui.PanelComponents.wrapText;
import com.deadmantoolkit.MarketClient;
import com.deadmantoolkit.MarketData;
import com.deadmantoolkit.TradeEvent;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BiConsumer;
import javax.swing.Box;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.text.JTextComponent;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.QuantityFormatter;

/**
 * Home card: the "Get started" card (when there is something to set up), your open offers, your profit, Market / My trades tabs, an "updated" line
 * with a refresh button, a stats line and the list. The two lists are separate {@link RowList}s, so switching tabs
 * or refreshing never rebuilds rows that are already there. EDT only.
 */
class HomeView
{
	static final String NOT_CONNECTED = "Connect with the \"Get started\" card above, or in the plugin's settings (gear icon), to see the market.";

	private final JPanel panel = column();
	private final JLabel statsLabel = mutedLabel("");
	private final JLabel updatedLabel = mutedLabel("");
	/** "Updated Xs ago" plus the refresh button; only on the Market tab once it has data. */
	private final JPanel updatedRow = new JPanel(new BorderLayout(4, 0));
	private final JTextComponent message = (JTextComponent) wrapText("", ColorScheme.LIGHT_GRAY_COLOR);
	private final RowList<MarketRows.Row> marketList;
	private final RowList<RowList.Keyed<TradeEvent>> mineList;
	/** Shown on the My trades tab only: the "Import RuneLite GE history" link. */
	private final JComponent mineExtra;
	/** The welcome card shows the same import link, so {@link #mineExtra} stays hidden. */
	private boolean mineExtraHidden;

	private boolean showMine;
	/** Epoch ms of the last successful market load, or 0. */
	private long lastUpdated;
	private boolean hasMarketData;
	/** The Market tab's stats text from its last load, put back when switching to it. */
	private String marketStats = "";
	/** Why the last market refresh failed, while its old data is still shown; null if it didn't. */
	private String failed;

	/**
	 * @param welcome   the "Get started" card, shown above the tabs (it hides itself when not needed)
	 * @param offers    "Your offers", below the welcome card (it hides itself when you have none)
	 * @param profit    "Profit", below your offers (it hides itself until there are numbers)
	 * @param onTab     run when a tab is clicked, to load it
	 * @param onRefresh the refresh button
	 * @param onOpen    opens an item from a row
	 * @param mineExtra shown under the stats line on the My trades tab only (the import link), or null
	 */
	HomeView(ItemManager itemManager, JComponent welcome, JComponent offers, JComponent profit, Runnable onTab, Runnable onRefresh,
		BiConsumer<Integer, String> onOpen, JComponent mineExtra)
	{
		marketList = new RowList<>(r -> r.getEvent().getId(), r -> when(r.getEvent().getKind(), feedTime(r.getEvent())),
			r -> marketRow(itemManager, r, onOpen));
		marketList.setEmptyText("No trades yet.");
		mineList = new RowList<>(k -> k.key, k -> when(k.value.getKind(), k.value.getTs()),
			k -> row(itemManager, k.value.getItemId(), k.value.getName(), k.value.getKind(), k.value.getSide(),
				k.value.getQty(), k.value.getPrice(), k.value.getTs(), onOpen));
		mineList.setEmptyText("No trades recorded yet. Trade on world 345 or open your GE History.");
		this.mineExtra = mineExtra;

		JPanel tabs = new JPanel(new GridLayout(1, 2, 4, 0));
		tabs.setOpaque(false);
		JButton marketTab = tabButton("Market");
		JButton mine = tabButton("My trades");
		Runnable style = () ->
		{
			styleTab(marketTab, !showMine);
			styleTab(mine, showMine);
		};
		marketTab.addActionListener(e -> selectTab(false, style, onTab));
		mine.addActionListener(e -> selectTab(true, style, onTab));
		style.run();
		tabs.add(marketTab);
		tabs.add(mine);
		tabs.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		tabs.setAlignmentX(Component.LEFT_ALIGNMENT);

		updatedRow.setOpaque(false);
		updatedRow.setVisible(false);
		updatedRow.add(updatedLabel, BorderLayout.CENTER);
		JButton refresh = iconButton(Icons.refresh(), "Refresh now", 22);
		refresh.addActionListener(e -> onRefresh.run());
		updatedRow.add(refresh, BorderLayout.EAST);
		updatedRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		updatedRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
		statsLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		panel.add(welcome);
		panel.add(offers);
		panel.add(profit);
		panel.add(tabs);
		panel.add(Box.createVerticalStrut(4));
		panel.add(updatedRow);
		panel.add(Box.createVerticalStrut(2));
		panel.add(statsLabel);
		if (mineExtra != null)
		{
			mineExtra.setAlignmentX(Component.LEFT_ALIGNMENT);
			mineExtra.setVisible(false);
			panel.add(Box.createVerticalStrut(2));
			panel.add(mineExtra);
		}
		panel.add(Box.createVerticalStrut(6));
		message.setVisible(false);
		panel.add(message);
		panel.add(marketList.getComponent());
		panel.add(mineList.getComponent());
		mineList.getComponent().setVisible(false);
		// The Market tab is selected first: say it's loading rather than show an empty list.
		showLoading();
	}

	/** The time a feed row shows: arrival, or an imported trade's own approximate time. */
	private static long feedTime(MarketData.FeedEvent e)
	{
		return Format.feedTime(e.getKind(), e.getReceivedAt(), e.getTs());
	}

	/** A Market row: an item's latest trade, as one "Traded" row when both sides of it were reported. */
	private static JComponent marketRow(ItemManager itemManager, MarketRows.Row r, BiConsumer<Integer, String> onOpen)
	{
		MarketData.FeedEvent e = r.getEvent();
		if (!r.isBothSides())
		{
			return row(itemManager, e.getItemId(), e.getName(), e.getKind(), e.getSide(), e.getQty(), e.getPrice(),
				feedTime(e), onOpen);
		}
		return tradeRow(itemManager, e.getItemId(), e.getName(), Format.traded(e.getQty(), e.getPrice()),
			Format.whenTwoLine(e.getKind(), feedTime(e)), onOpen);
	}

	/** An item row; imported trades show their approximate age above "imported", and say so in the tooltip. */
	private static JComponent row(ItemManager itemManager, int itemId, String name, String kind, String side, int qty,
		long price, long ts, BiConsumer<Integer, String> onOpen)
	{
		String line2 = describe(kind, side, qty, price);
		JComponent row = tradeRow(itemManager, itemId, name, line2, Format.whenTwoLine(kind, ts), onOpen);
		if (TradeEvent.IMPORTED.equals(kind))
		{
			row.setToolTipText("<html>" + row.getToolTipText() + "<br>" + Format.IMPORTED_TIP + "</html>");
		}
		return row;
	}

	/** Hide the My trades tab's import link (while the welcome card shows its own), or show it again. */
	void setMineExtraHidden(boolean hidden)
	{
		mineExtraHidden = hidden;
		if (mineExtra != null && mineExtra.isVisible() != (showMine && !hidden))
		{
			mineExtra.setVisible(showMine && !hidden);
		}
	}

	private void selectTab(boolean mine, Runnable style, Runnable onTab)
	{
		if (mine != showMine)
		{
			showMine = mine;
			if (mineExtra != null)
			{
				mineExtra.setVisible(mine && !mineExtraHidden);
			}
			// A different tab starts at its first page and doesn't flash rows as new.
			(mine ? mineList : marketList).reset();
			if (!mine)
			{
				mineList.getComponent().setVisible(false);
				if (hasMarketData)
				{
					// Show the feed we have right away; the load that follows only adds what's new.
					setStats(marketStats);
					message.setVisible(false);
					marketList.getComponent().setVisible(true);
				}
				else
				{
					showLoading();
				}
			}
		}
		style.run();
		onTab.run();
	}

	JComponent getComponent()
	{
		return panel;
	}

	/** True when the "My trades" tab is selected. */
	boolean isShowingMine()
	{
		return showMine;
	}

	void showMine(List<TradeEvent> trades)
	{
		setStats("Your world 345 trades");
		message.setVisible(false);
		marketList.getComponent().setVisible(false);
		mineList.getComponent().setVisible(true);
		mineList.setItems(RowList.withOccurrenceKeys(trades, ItemSections::tradeKey));
		tick();
	}

	void showNotConnected()
	{
		setStats("Not connected");
		showMessage(NOT_CONNECTED);
		marketList.getComponent().setVisible(false);
		mineList.getComponent().setVisible(false);
		tick();
	}

	/** Show the merged Market feed ({@link FeedMerge}): each item's latest trade ({@link MarketRows}), newest first. */
	void showMarket(MarketData.Stats s, List<MarketData.FeedEvent> events)
	{
		marketStats = s == null ? "" : "<html>" + s.getOpenBids() + " bids · " + s.getOpenAsks() + " asks open<br>"
			+ QuantityFormatter.quantityToStackSize(s.getUnits24()) + " units / " + QuantityFormatter.quantityToStackSize(s.getGp24())
			+ " gp traded in 24h</html>";
		setStats(marketStats);
		message.setVisible(false);
		mineList.getComponent().setVisible(false);
		marketList.getComponent().setVisible(true);
		marketList.setItems(MarketRows.latestPerItem(events));
		hasMarketData = true;
		failed = null;
		lastUpdated = System.currentTimeMillis();
		tick();
	}

	/** A market refresh failed: replace the list only if nothing was loaded yet, otherwise just say so. */
	void showError(String text)
	{
		if (!hasMarketData)
		{
			setStats("");
			showMessage(text);
			marketList.getComponent().setVisible(false);
			mineList.getComponent().setVisible(false);
		}
		else
		{
			failed = text;
		}
		tick();
	}

	/** Forget the loaded market (connection changed); the next load starts fresh. */
	void resetMarket()
	{
		// Empty first, then reset: the first real load must not count as new rows.
		marketList.setItems(new ArrayList<>());
		marketList.reset();
		hasMarketData = false;
		marketStats = "";
		lastUpdated = 0;
		failed = null;
		if (!showMine)
		{
			showLoading();
		}
	}

	/** The Market tab before its first load: no list (not "No trades yet."), just a loading line. */
	private void showLoading()
	{
		setStats("");
		showMessage("Loading…");
		marketList.getComponent().setVisible(false);
		mineList.getComponent().setVisible(false);
		tick();
	}

	/** Once a second while shown: update the "updated Xs ago" text (market tab only). */
	void tick()
	{
		String text;
		Color color = ColorScheme.LIGHT_GRAY_COLOR;
		if (showMine || !hasMarketData)
		{
			text = "";
		}
		else if (failed != null)
		{
			// The reason in a few words; the full sentence is in the tooltip.
			text = failedText(failed);
			color = ColorScheme.PROGRESS_ERROR_COLOR;
		}
		else
		{
			text = "Updated " + Format.updatedAgo(lastUpdated, System.currentTimeMillis());
		}
		boolean rowShown = !showMine && hasMarketData;
		if (updatedRow.isVisible() != rowShown)
		{
			updatedRow.setVisible(rowShown);
		}
		if (!text.equals(updatedLabel.getText()))
		{
			updatedLabel.setText(text);
			updatedLabel.setForeground(color);
			updatedLabel.setToolTipText(failed != null ? failed + " Showing the last data received." : null);
		}
	}

	/** The status line after a failed refresh, e.g. "Update failed: server unreachable". */
	static String failedText(String error)
	{
		return "Update failed: " + MarketClient.shortReason(error);
	}

	void stop()
	{
		marketList.stop();
		mineList.stop();
	}

	private void setStats(String text)
	{
		if (!text.equals(statsLabel.getText()))
		{
			statsLabel.setText(text);
		}
	}

	private void showMessage(String text)
	{
		if (!text.equals(message.getText()))
		{
			message.setText(text);
		}
		message.setVisible(true);
	}
}

package com.deadmantoolkit.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.awt.geom.Arc2D;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.ui.ColorScheme;

/**
 * Small icons drawn in code once, so the plugin ships no image files. EDT only (the caches aren't synchronized).
 */
final class Icons
{
	private static final int COG_SIZE = 14;
	private static final int COG_TEETH = 8;
	private static final int DOT_SIZE = 8;
	private static final int REFRESH_SIZE = 12;

	private static ImageIcon cog;
	private static ImageIcon dotOn;
	private static ImageIcon dotOff;
	private static ImageIcon refresh;

	private Icons()
	{
	}

	/** A settings cog. */
	static ImageIcon cog()
	{
		if (cog == null)
		{
			cog = new ImageIcon(drawCog(COG_SIZE, ColorScheme.LIGHT_GRAY_COLOR));
		}
		return cog;
	}

	/** A circular arrow, for refresh buttons. */
	static ImageIcon refresh()
	{
		if (refresh == null)
		{
			refresh = new ImageIcon(drawRefresh(REFRESH_SIZE, ColorScheme.LIGHT_GRAY_COLOR));
		}
		return refresh;
	}

	/** A filled dot (connected) or a ring (not connected) for the status line. */
	static ImageIcon statusDot(boolean on)
	{
		if (on)
		{
			if (dotOn == null)
			{
				dotOn = new ImageIcon(drawDot(DOT_SIZE, PanelComponents.GOOD, true));
			}
			return dotOn;
		}
		if (dotOff == null)
		{
			dotOff = new ImageIcon(drawDot(DOT_SIZE, ColorScheme.LIGHT_GRAY_COLOR, false));
		}
		return dotOff;
	}

	static BufferedImage drawCog(int size, Color color)
	{
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		double c = size / 2.0;
		double body = size * 0.34;
		double hole = size * 0.14;
		double toothW = size * 0.18;
		double toothLen = size * 0.48;
		Area cogArea = new Area(new Ellipse2D.Double(c - body, c - body, body * 2, body * 2));
		Rectangle2D tooth = new Rectangle2D.Double(c - toothW / 2, c - toothLen, toothW, toothLen);
		for (int i = 0; i < COG_TEETH; i++)
		{
			AffineTransform rot = AffineTransform.getRotateInstance(Math.PI * 2 * i / COG_TEETH, c, c);
			cogArea.add(new Area(rot.createTransformedShape(tooth)));
		}
		cogArea.subtract(new Area(new Ellipse2D.Double(c - hole, c - hole, hole * 2, hole * 2)));
		g.setColor(color);
		g.fill(cogArea);
		g.dispose();
		return img;
	}

	static BufferedImage drawRefresh(int size, Color color)
	{
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(color);
		float stroke = Math.max(1.5f, size / 7f);
		g.setStroke(new BasicStroke(stroke, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER));
		double r = size / 2.0 - stroke;
		double c = size / 2.0;
		// Three quarters of a circle, open at the top right, with an arrowhead at the open end.
		g.draw(new Arc2D.Double(c - r, c - r, r * 2, r * 2, 70, 280, Arc2D.OPEN));
		double a = Math.toRadians(70);
		double ex = c + r * Math.cos(a), ey = c - r * Math.sin(a);
		double head = size * 0.32;
		Path2D.Double arrow = new Path2D.Double();
		arrow.moveTo(ex + head * 0.9, ey - head * 0.15);
		arrow.lineTo(ex - head * 0.25, ey - head * 0.75);
		arrow.lineTo(ex - head * 0.1, ey + head * 0.6);
		arrow.closePath();
		g.fill(arrow);
		g.dispose();
		return img;
	}

	private static BufferedImage drawDot(int size, Color color, boolean filled)
	{
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(color);
		if (filled)
		{
			g.fillOval(0, 0, size - 1, size - 1);
		}
		else
		{
			g.drawOval(1, 1, size - 3, size - 3);
		}
		g.dispose();
		return img;
	}
}

package com.deadmantoolkit.ui;

import static com.deadmantoolkit.ui.PanelComponents.column;
