import java.util.List;
import java.util.Objects;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.ImageIcon;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The breaches and Deadman's Chest going on now, one line each under the breach banner: icon, place, and how long ago
 * it spawned (chest) or how long it has left (breach). The tooltip says how exact the map marker is; clicking a line
 * points the game's hint arrow at that event (again to stop). Hidden while there's nothing to show. EDT only.
 */
class WorldEventsList
{
	private static final int ROW_HEIGHT = 20;
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm");

	private final JPanel panel = PanelComponents.column();
	private final Consumer<WorldEvents.Event> onClick;
	private List<WorldEvents.Event> events = Collections.emptyList();
	private WorldPoint arrowAt;
	/** The time labels, in event order, updated each second. */
	private final List<JLabel> times = new ArrayList<>();

	/** @param onClick a line was clicked (point the hint arrow there, or stop) */
	WorldEventsList(Consumer<WorldEvents.Event> onClick)
	{
		this.onClick = onClick;
		panel.setVisible(false);
	}

	JComponent getComponent()
	{
		return panel;
	}

	/** Show these events; {@code arrowAt} is where the hint arrow points (that line is highlighted), or null. */
	void set(List<WorldEvents.Event> events, WorldPoint arrowAt)
	{
		if (events.equals(this.events) && Objects.equals(arrowAt, this.arrowAt))
		{
			return;
		}
		this.events = new ArrayList<>(events);
		this.arrowAt = arrowAt;
		panel.removeAll();
		times.clear();
		Instant now = Instant.now();
		for (WorldEvents.Event e : this.events)
		{
			panel.add(row(e, now));
			panel.add(Box.createVerticalStrut(2));
		}
		if (!this.events.isEmpty())
		{
			panel.add(Box.createVerticalStrut(4));
		}
		panel.setVisible(!this.events.isEmpty());
		panel.revalidate();
		panel.repaint();
	}

	/** Once a second: the times move on. */
	void tick()
	{
		Instant now = Instant.now();
		for (int i = 0; i < times.size() && i < events.size(); i++)
		{
			String t = timeText(events.get(i), now);
			if (!t.equals(times.get(i).getText()))
			{
				times.get(i).setText(t);
			}
		}
	}

	private JComponent row(WorldEvents.Event e, Instant now)
	{
		boolean arrowed = e.getWhere() != null && e.getWhere().getPoint() != null
			&& e.getWhere().getPoint().equals(arrowAt);
		JPanel row = new JPanel(new BorderLayout(5, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		Color edge = arrowed ? ColorScheme.BRAND_ORANGE
			: WorldEventIcons.color(e.getKind());
		row.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0, 2, 0, 0, edge),
			new EmptyBorder(1, 4, 1, 5)));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_HEIGHT));
		row.setPreferredSize(new Dimension(0, ROW_HEIGHT));

		JLabel icon = new JLabel(new ImageIcon(WorldEventIcons.of(e.getKind(),
			e.getWhere() == null ? null : e.getWhere().getAccuracy())));
		row.add(icon, BorderLayout.WEST);

		JLabel text = new JLabel(label(e));
		text.setFont(FontManager.getRunescapeSmallFont());
		text.setForeground(ColorScheme.TEXT_COLOR);
		row.add(text, BorderLayout.CENTER);

		JLabel time = new JLabel(timeText(e, now));
		time.setFont(FontManager.getRunescapeSmallFont());
		time.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		row.add(time, BorderLayout.EAST);
		times.add(time);

		String tip = tooltip(e, arrowed);
		row.setToolTipText(tip);
		text.setToolTipText(tip);
		if (e.getWhere() != null && e.getWhere().known())
		{
			row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			row.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent ev)
				{
					onClick.accept(e);
				}
			});
		}
		return row;
	}

	/** "Chest · north of the Warriors' Guild", "Breach (Multi) · the Bone Yard". */
	static String label(WorldEvents.Event e)
	{
		String kind = e.getKind() == WorldEventMessage.Kind.CHEST ? "Chest"
			: e.getCombat() == WorldEventMessage.Combat.MULTI ? "Breach (Multi)"
			: e.getCombat() == WorldEventMessage.Combat.SINGLE ? "Breach (Single)" : "Breach";
		return kind + " · " + e.getLocation();
	}

	/** A chest: how long since it spawned ("12m"); a breach: how long it has left ("31m left"). */
	static String timeText(WorldEvents.Event e, Instant now)
	{
		if (e.getKind() == WorldEventMessage.Kind.CHEST)
		{
			long m = Math.max(0, Duration.between(e.getAt(), now).toMinutes());
			return m < 1 ? "now" : m + "m";
		}
		long left = Math.max(0, Duration.between(now, e.getUntil()).toMinutes());
		return left + "m left";
	}

	static String tooltip(WorldEvents.Event e, boolean arrowed)
	{
		StringBuilder sb = new StringBuilder("<html>");
		sb.append(e.getKind() == WorldEventMessage.Kind.CHEST ? "Deadman's Chest: " : "Breach: ")
			.append(escape(e.getLocation()));
		String note = WorldEventMarkers.accuracyNote(e.getWhere());
		sb.append("<br>").append(note == null ? "Marked on the world map" : "On the map: " + escape(note));
		if (e.getWhere() != null && e.getWhere().getEntranceName() != null)
		{
			sb.append("<br>Enter at ").append(escape(e.getWhere().getEntranceName()));
		}
		ZoneId zone = ZoneId.systemDefault();
		sb.append("<br>Spawned ").append(CLOCK.format(e.getAt().atZone(zone)));
		if (e.getKind() == WorldEventMessage.Kind.BREACH)
		{
			sb.append(", gone by ").append(CLOCK.format(e.getUntil().atZone(zone)));
		}
		if (e.getSource() == WorldEvents.Source.REPORTED)
		{
			sb.append("<br>Broadcast before you logged in (").append(e.getReporters())
				.append(e.getReporters() == 1 ? " report)" : " reports)");
		}
		else if (e.getSource() == WorldEvents.Source.TEST)
		{
			sb.append("<br>Test event (developer tools)");
		}
		if (e.getWhere() != null && e.getWhere().known())
		{
			sb.append("<br>").append(arrowed ? "Click to remove the hint arrow" : "Click to point the hint arrow here");
		}
		return sb.append("</html>").toString();
	}

	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.deadmantoolkit.world;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.file.StandardOpenOption;
import java.util.HashSet;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Broadcast places the plugin couldn't put on the map, appended to {@value #FILE_NAME} in the plugin folder (one JSON
 * object per line: time, kind, the place as the game wrote it) so the place list ({@link WorldPlaces#RESOURCE}) can be
 * improved. Each place is written once per session. The server keeps the same list across players (when connected),
 * which is where most new names will be found. Executor thread only (disk IO).
 */
@Slf4j
public final class UnresolvedLog
{
	public static final String FILE_NAME = "unknown-places.jsonl";
	/** A session never writes more lines than this (a flood of nonsense can't grow the file much). */
	static final int MAX_PER_SESSION = 100;

	/** The plugin's data folder; may do disk IO. */
	public interface Dir
	{
		Filepath get() throws IOException;
	}

	private final Dir dir;
	private final Gson gson;
	private final Set<String> written = new HashSet<>();

	public UnresolvedLog(Dir dir, Gson gson)
	{
		this.dir = dir;
		this.gson = gson;
	}

	/**
	 * Note a place that couldn't be resolved, or was only matched by a near spelling.
	 *
	 * @param ts      unix seconds
	 * @param test    fed by the developer tools, not the game
	 * @param matched the place a near spelling was read as, or null when it couldn't be placed at all
	 * @return true when a line was written
	 */
	public boolean record(WorldEventMessage.Kind kind, String place, long ts, boolean test, String matched)
	{
		String key = kind.id() + "|" + WorldLocations.key(place);
		if (written.size() >= MAX_PER_SESSION || !written.add(key))
		{
			return false;
		}
		JsonObject o = new JsonObject();
		o.addProperty("ts", ts);
		o.addProperty("kind", kind.id());
		o.addProperty("place", place);
		if (matched != null)
		{
			o.addProperty("readAs", matched);
		}
		if (test)
		{
			o.addProperty("test", true);
		}
		try
		{
			Filepath folder = dir.get();
			if (!folder.exists())
			{
				folder.createDirectories();
			}
			try (BufferedWriter w = folder.joinSegment(FILE_NAME)
				.openBufferedWriter(StandardOpenOption.CREATE, StandardOpenOption.APPEND))
			{
				w.write(gson.toJson(o));
				w.newLine();
			}
			return true;
		}
		catch (IOException ex)
		{
			log.debug("Couldn't note an unknown place: {}", ex.getClass().getSimpleName());
			written.remove(key);
			return false;
		}
	}
}

package com.deadmantoolkit.world;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;

/**
 * World event icons, drawn in code (the plugin ships no image files):
 * <ul>
 * <li>{@link #of}: the small panel icon;</li>
 * <li>{@link #pin}: the world map marker, a round badge on a pointer whose tip is the spot (like clue markers);</li>
 * <li>{@link #edge}: the badge with an arrow on its rim, for a marker pinned to the edge of the world map, turned
 * towards the event ({@value #DIRECTIONS} directions);</li>
 * <li>{@link #minimap}: a small badge for the minimap.</li>
 * </ul>
 * Region-only markers carry a "?". All images are made once and never changed afterwards, so any thread may use them.
 */
public final class WorldEventIcons
{
	public static final int SIZE = 15;
	/** World map badge diameter. */
	static final int BADGE = 26;
	/** Pin: badge plus pointer. */
	static final int PIN_W = BADGE + 4;
	static final int PIN_H = BADGE + 16;
	/** Edge marker: badge plus the arrow around it. */
	static final int EDGE = BADGE + 18;
	static final int MINIMAP = 15;
	static final int DIRECTIONS = 16;

	static final Color CHEST_GOLD = new Color(0xf2c230);
	static final Color CHEST_WOOD = new Color(0x8a5524);
	static final Color CHEST_BG = new Color(0x3a2410);
	static final Color BREACH_PURPLE = new Color(0xb45cff);
	static final Color BREACH_BG = new Color(0x2a0a40);
	static final Color OUTLINE = new Color(0x111111);

	private static final int CHEST = 0;
	private static final int BREACH = 1;

	/** [kind][rough] */
	private static final BufferedImage[][] PANEL = new BufferedImage[2][2];
	private static final BufferedImage[][] PIN = new BufferedImage[2][2];
	private static final BufferedImage[][] MINI = new BufferedImage[2][2];
	/** [kind][rough][direction] */
	private static final BufferedImage[][][] EDGES = new BufferedImage[2][2][DIRECTIONS];

	static
	{
		for (int k = 0; k < 2; k++)
		{
			for (int r = 0; r < 2; r++)
			{
				boolean rough = r == 1;
				PANEL[k][r] = panel(k, rough);
				PIN[k][r] = pin(k, rough);
				MINI[k][r] = badgeImage(k, rough, MINIMAP);
				for (int d = 0; d < DIRECTIONS; d++)
				{
					EDGES[k][r][d] = edge(k, rough, d * 2 * Math.PI / DIRECTIONS);
				}
			}
		}
	}

	private WorldEventIcons()
	{
	}

	private static int kind(WorldEventMessage.Kind kind)
	{
		return kind == WorldEventMessage.Kind.CHEST ? CHEST : BREACH;
	}

	private static int rough(WorldLocations.Accuracy accuracy)
	{
		return accuracy == WorldLocations.Accuracy.REGION ? 1 : 0;
	}

	/** The panel icon ({@value #SIZE} px); "rough" (a "?") when only the region is known. */
	public static BufferedImage of(WorldEventMessage.Kind kind, WorldLocations.Accuracy accuracy)
	{
		return PANEL[kind(kind)][rough(accuracy)];
	}

	/** The world map marker; its pointer tip (bottom centre) is the spot. */
	public static BufferedImage pin(WorldEventMessage.Kind kind, WorldLocations.Accuracy accuracy)
	{
		return PIN[kind(kind)][rough(accuracy)];
	}

	/** The marker at the edge of the world map, its arrow pointing at {@code angle} (radians, screen: 0 = right, y down). */
	public static BufferedImage edge(WorldEventMessage.Kind kind, WorldLocations.Accuracy accuracy, double angle)
	{
		return EDGES[kind(kind)][rough(accuracy)][direction(angle)];
	}

	public static BufferedImage minimap(WorldEventMessage.Kind kind, WorldLocations.Accuracy accuracy)
	{
		return MINI[kind(kind)][rough(accuracy)];
	}

	/** The nearest of the {@value #DIRECTIONS} directions to {@code angle}. */
	static int direction(double angle)
	{
		double turn = angle / (2 * Math.PI);
		int d = (int) Math.round((turn - Math.floor(turn)) * DIRECTIONS);
		return d % DIRECTIONS;
	}

	/** The colour of a kind (pointers, arrows, the panel's edge). */
	public static Color color(WorldEventMessage.Kind kind)
	{
		return kind == WorldEventMessage.Kind.CHEST ? CHEST_GOLD : BREACH_PURPLE;
	}

	/* ---------------------------------------------------------------- drawing */

	private static Graphics2D start(BufferedImage img)
	{
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		return g;
	}

	/** The 15 px panel icon: the glyph alone. */
	private static BufferedImage panel(int kind, boolean rough)
	{
		BufferedImage img = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = start(img);
		glyph(g, kind);
		if (rough)
		{
			question(g, 8, 8, 7);
		}
		g.dispose();
		return img;
	}

	/** A round badge of diameter {@code d} with the glyph in it. */
	private static BufferedImage badgeImage(int kind, boolean rough, int d)
	{
		BufferedImage img = new BufferedImage(d, d, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = start(img);
		badge(g, kind, rough, 0, 0, d);
		g.dispose();
		return img;
	}

	private static BufferedImage pin(int kind, boolean rough)
	{
		BufferedImage img = new BufferedImage(PIN_W, PIN_H, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = start(img);
		double cx = PIN_W / 2.0;
		// Pointer from under the badge to the spot.
		Path2D p = new Path2D.Double();
		p.moveTo(cx - 7, BADGE - 4);
		p.lineTo(cx + 7, BADGE - 4);
		p.lineTo(cx, PIN_H - 1);
		p.closePath();
		g.setColor(OUTLINE);
		g.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.draw(p);
		g.setColor(colorOf(kind));
		g.fill(p);
		badge(g, kind, rough, (PIN_W - BADGE) / 2.0, 1, BADGE);
		g.dispose();
		return img;
	}

	private static BufferedImage edge(int kind, boolean rough, double angle)
	{
		BufferedImage img = new BufferedImage(EDGE, EDGE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = start(img);
		double c = EDGE / 2.0;
		// The arrow: its tip near the image's edge, its base under the badge.
		Path2D a = new Path2D.Double();
		a.moveTo(c + (EDGE / 2.0 - 1), c);
		a.lineTo(c + BADGE / 2.0 - 3, c - 8);
		a.lineTo(c + BADGE / 2.0 - 3, c + 8);
		a.closePath();
		Shape arrow = AffineTransform.getRotateInstance(angle, c, c).createTransformedShape(a);
		g.setColor(OUTLINE);
		g.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.draw(arrow);
		g.setColor(colorOf(kind));
		g.fill(arrow);
		badge(g, kind, rough, c - BADGE / 2.0, c - BADGE / 2.0, BADGE);
		g.dispose();
		return img;
	}

	private static Color colorOf(int kind)
	{
		return kind == CHEST ? CHEST_GOLD : BREACH_PURPLE;
	}

	/** Dark outline, white ring, dark disc, the glyph scaled into it. */
	private static void badge(Graphics2D g, int kind, boolean rough, double x, double y, double d)
	{
		g.setColor(OUTLINE);
		g.fill(new Ellipse2D.Double(x, y, d, d));
		g.setColor(Color.WHITE);
		g.fill(new Ellipse2D.Double(x + 1.5, y + 1.5, d - 3, d - 3));
		g.setColor(kind == CHEST ? CHEST_BG : BREACH_BG);
		double inner = d - 6;
		g.fill(new Ellipse2D.Double(x + 3, y + 3, inner, inner));
		AffineTransform saved = g.getTransform();
		double glyph = inner * 0.86;
		g.translate(x + (d - glyph) / 2, y + (d - glyph) / 2);
		g.scale(glyph / SIZE, glyph / SIZE);
		glyph(g, kind);
		g.setTransform(saved);
		if (rough)
		{
			double q = Math.max(7, d * 0.42);
			question(g, x + d - q, y + d - q, q);
		}
	}

	/** The chest or breach drawing in a 15 x 15 box. */
	private static void glyph(Graphics2D g, int kind)
	{
		g.setStroke(new BasicStroke(1f));
		if (kind == CHEST)
		{
			g.setColor(CHEST_WOOD);
			g.fill(new RoundRectangle2D.Double(1.5, 6, 12, 7.5, 2, 2));
			g.fill(new RoundRectangle2D.Double(1.5, 2.5, 12, 4.5, 4, 4));
			g.setColor(OUTLINE);
			g.draw(new RoundRectangle2D.Double(1.5, 6, 12, 7.5, 2, 2));
			g.draw(new RoundRectangle2D.Double(1.5, 2.5, 12, 4.5, 4, 4));
			g.setColor(CHEST_GOLD);
			g.fill(new java.awt.geom.Rectangle2D.Double(4, 3, 1.2, 10));
			g.fill(new java.awt.geom.Rectangle2D.Double(9.8, 3, 1.2, 10));
			g.fill(new java.awt.geom.Rectangle2D.Double(6, 6, 3, 3));
		}
		else
		{
			g.setColor(OUTLINE);
			g.fill(new Ellipse2D.Double(0.5, 0.5, 14, 14));
			g.setColor(BREACH_PURPLE);
			g.fill(new Ellipse2D.Double(1.5, 1.5, 12, 12));
			g.setColor(new Color(0x1a0530));
			g.fill(new Ellipse2D.Double(4, 4, 7, 7));
			g.setColor(new Color(0xf0d8ff));
			g.setStroke(new BasicStroke(1.3f));
			g.drawArc(3, 3, 9, 9, 30, 200);
		}
	}

	/** A "?" badge of diameter {@code d} at ({@code x}, {@code y}): only the region is known. */
	private static void question(Graphics2D g, double x, double y, double d)
	{
		g.setColor(OUTLINE);
		g.fill(new Ellipse2D.Double(x, y, d, d));
		g.setColor(Color.WHITE);
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, (int) Math.round(d * 0.95)));
		java.awt.FontMetrics fm = g.getFontMetrics();
		g.drawString("?", (float) (x + (d - fm.stringWidth("?")) / 2), (float) (y + d / 2 + fm.getAscent() * 0.36));
	}
}

package com.deadmantoolkit.world;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws nothing itself: while the world map is open it turns the arrows of edge-pinned world event markers towards
 * their events (RuneLite's world map overlay draws the markers). One cheap pass over a handful of markers per frame.
 */
public final class WorldEventMapOverlay extends Overlay
{
	private final Client client;
	private final Supplier<WorldEventMarkers> markers;

	public WorldEventMapOverlay(Client client, Supplier<WorldEventMarkers> markers)
	{
		this.client = client;
		this.markers = markers;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.MANUAL);
		drawAfterInterface(InterfaceID.WORLDMAP);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WorldEventMarkers m = markers.get();
		if (m != null)
		{
			m.updateEdges(client.getWorldMap());
		}
		return null;
	}
}

package com.deadmantoolkit.world;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/**
 * Puts world events on the world map, like clue and quest markers: a pin whose tip is the spot; off screen, a badge
 * pinned to the edge of the map with an arrow turned towards the event (clicking it moves the map there). The label
 * ("Breach (Multi): North of Edgeville") is the marker's name, which RuneLite shows as "Focus on ..." when hovered;
 * there is no separate tooltip to overlap it. A place on another map (Zanaris) also gets a marker at its surface
 * entrance. Optionally sets the game's hint arrow to one event; only clears a hint arrow it set itself.
 * Client thread only.
 */
public final class WorldEventMarkers
{
	/** Our map points, so only ours are ever removed. */
	static final class EventPoint extends WorldMapPoint
	{
		private final WorldEventMessage.Kind kind;
		private final WorldLocations.Accuracy accuracy;

		EventPoint(WorldPoint at, WorldEventMessage.Kind kind, WorldLocations.Accuracy accuracy, String label)
		{
			super(at, WorldEventIcons.pin(kind, accuracy));
			this.kind = kind;
			this.accuracy = accuracy;
			setImagePoint(pinTip());
			setTarget(at);
			setSnapToEdge(true);
			setJumpOnClick(true);
			setName(label);
		}

		private static Point pinTip()
		{
			return new Point(WorldEventIcons.PIN_W / 2, WorldEventIcons.PIN_H);
		}

		@Override
		public void onEdgeSnap()
		{
			// Centred badge; the arrow is turned towards the event on every frame (updateEdges).
			setImagePoint(null);
		}

		@Override
		public void onEdgeUnsnap()
		{
			setImage(WorldEventIcons.pin(kind, accuracy));
			setImagePoint(pinTip());
		}

		/** Turn the edge arrow towards the event, seen from the middle of the shown map. */
		void pointFrom(Point mapCentre)
		{
			WorldPoint at = getWorldPoint();
			// Screen angle: x to the right, y down (the map's north is up).
			double angle = Math.atan2(-(at.getY() - mapCentre.getY()), at.getX() - mapCentre.getX());
			BufferedImage img = WorldEventIcons.edge(kind, accuracy, angle);
			if (img != getImage())
			{
				setImage(img);
			}
		}
	}

	private final WorldMapPointManager manager;
	private final Client client;
	private final List<EventPoint> shown = new ArrayList<>();
	/** The hint arrow target this class set, or null. */
	private WorldPoint arrow;

	public WorldEventMarkers(WorldMapPointManager manager, Client client)
	{
		this.manager = manager;
		this.client = client;
	}

	/**
	 * Show exactly these events.
	 *
	 * @param arrowTo where the hint arrow should point (an event's spot), or null for none
	 */
	public void show(List<WorldEvents.Event> events, WorldPoint arrowTo)
	{
		removePoints();
		for (WorldEvents.Event e : events)
		{
			WorldLocations.Resolved where = e.getWhere();
			if (where == null || !where.known())
			{
				continue;
			}
			add(new EventPoint(where.getPoint(), e.getKind(), where.getAccuracy(), label(e, null)));
			if (where.getEntrance() != null)
			{
				add(new EventPoint(where.getEntrance(), e.getKind(), where.getAccuracy(), label(e, where.getEntranceName())));
			}
		}
		setArrow(arrowTo);
	}

	public void clear()
	{
		removePoints();
		setArrow(null);
	}

	/** World map open (overlay, every frame): keep the arrows of edge-pinned markers turned towards their events. */
	public void updateEdges(WorldMap map)
	{
		if (shown.isEmpty() || map == null)
		{
			return;
		}
		Point centre = map.getWorldMapPosition();
		if (centre == null)
		{
			return;
		}
		for (EventPoint p : shown)
		{
			if (p.isCurrentlyEdgeSnapped())
			{
				p.pointFrom(centre);
			}
		}
	}

	/** For tests and the overlay. */
	List<EventPoint> shown()
	{
		return Collections.unmodifiableList(shown);
	}

	private void add(EventPoint p)
	{
		manager.add(p);
		shown.add(p);
	}

	private void removePoints()
	{
		if (!shown.isEmpty())
		{
			manager.removeIf(p -> p instanceof EventPoint);
			shown.clear();
		}
	}

	/**
	 * The marker's label: "Deadman's Chest: north of the Warriors' Guild", "Breach (Multi): North of Edgeville",
	 * with how rough it is ("~ somewhere in Asgarnia") or, for an entrance, where you go in.
	 */
	static String label(WorldEvents.Event e, String entranceName)
	{
		StringBuilder sb = new StringBuilder(e.getKind() == WorldEventMessage.Kind.CHEST ? "Deadman's Chest" : "Breach");
		if (e.getCombat() != null)
		{
			sb.append(e.getCombat() == WorldEventMessage.Combat.MULTI ? " (Multi)" : " (Single)");
		}
		sb.append(": ").append(e.getLocation());
		if (entranceName != null)
		{
			sb.append(" - enter at ").append(entranceName);
		}
		else
		{
			String note = accuracyNote(e.getWhere());
			if (note != null)
			{
				sb.append(" (").append(note).append(')');
			}
		}
		return sb.toString();
	}

	/** How rough a marker is, in a few words; null when exact. */
	public static String accuracyNote(WorldLocations.Resolved where)
	{
		if (where == null)
		{
			return "place unknown";
		}
		switch (where.getAccuracy())
		{
			case APPROXIMATE:
				return "roughly, within " + where.getRadius() + " tiles";
			case REGION:
				return "somewhere in " + where.getPlace();
			case UNKNOWN:
				return "place unknown";
			default:
				return where.isFuzzy() ? "read as " + where.getPlace() : null;
		}
	}

	private void setArrow(WorldPoint to)
	{
		if (to != null && to.equals(arrow) && client.hasHintArrow())
		{
			return;
		}
		if (arrow != null && client.hasHintArrow() && arrow.equals(client.getHintArrowPoint()))
		{
			client.clearHintArrow();
		}
		arrow = null;
		if (to != null && !client.hasHintArrow())
		{
			client.setHintArrow(to);
			arrow = to;
		}
	}
}

package com.deadmantoolkit.world;

import java.util.Locale;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;
import net.runelite.client.util.Text;

/**
 * A world event broadcast the game sends on Deadman world 345:
 * <ul>
 * <li>"A Deadman's Chest has spawned at north of the Warriors' Guild!" (about once an hour, around :15);</li>
 * <li>"A breach has spawned at &lt;place&gt;! Powerful monsters now roam the area (Single)." (weekend breaches; several
 * at once, each Single or Multi combat).</li>
 * </ul>
 * Pure: colour tags, curly apostrophes, letter case and spacing don't matter. The place is kept as the game wrote it
 * (for display and for the server's list of places); {@link WorldLocations} works out where it is.
 */
@Value
public class WorldEventMessage
{
	public enum Kind
	{
		CHEST, BREACH;

		/** The wire / log name: "chest" or "breach". */
		public String id()
		{
			return name().toLowerCase(Locale.ROOT);
		}
	}

	public enum Combat
	{
		SINGLE, MULTI;

		public String id()
		{
			return name().toLowerCase(Locale.ROOT);
		}
	}

	/** Longest place text kept; the game's are far shorter. */
	public static final int MAX_LOCATION = 80;

	/** "spawned at north of the Grand Exchange", but also "spawned throughout Zanaris". */
	private static final String VERB = "has\\s+(?:spawned|appeared|opened|emerged)\\s+"
		+ "(?:at|in|on|near|inside|by|throughout|across|around|within)\\s+";
	private static final Pattern CHEST = Pattern.compile(
		"\\ba\\s+deadman'?s\\s+chest\\s+" + VERB + "(.+?)\\s*[!.]*\\s*$", Pattern.CASE_INSENSITIVE);
	private static final Pattern BREACH = Pattern.compile("\\ba\\s+breach\\s+" + VERB, Pattern.CASE_INSENSITIVE);
	private static final Pattern COMBAT_NOTE = Pattern.compile("\\s*\\((?:single|multi)[^)]*\\)\\s*$", Pattern.CASE_INSENSITIVE);
	/** A place has at least one letter or digit. */
	private static final Pattern HAS_WORD = Pattern.compile("[\\p{L}\\p{N}]");
	private static final Pattern MULTI = Pattern.compile("\\bmulti(?:[- ]?way|[- ]?combat)?\\b", Pattern.CASE_INSENSITIVE);
	private static final Pattern SINGLE = Pattern.compile("\\bsingle(?:[- ]?way|[- ]?combat)?\\b", Pattern.CASE_INSENSITIVE);

	Kind kind;
	/** The place as the game wrote it (tags removed, trimmed). */
	String location;
	/** Breaches only, when the message says; null otherwise. */
	Combat combat;

	/** The event a game message announces, or empty for any other text. */
	public static Optional<WorldEventMessage> parse(String raw)
	{
		if (raw == null || raw.isEmpty())
		{
			return Optional.empty();
		}
		String text = clean(raw);
		Matcher m = CHEST.matcher(text);
		if (m.find())
		{
			return of(Kind.CHEST, m.group(1), null);
		}
		m = BREACH.matcher(text);
		if (m.find())
		{
			// The place ends at the "!" (or, failing that, at the end of the sentence); the rest says Single / Multi.
			String after = text.substring(m.end());
			int cut = after.indexOf('!');
			if (cut < 0)
			{
				cut = after.indexOf(". ");
			}
			String place = cut < 0 ? after : after.substring(0, cut);
			String rest = cut < 0 ? place : after.substring(cut + 1);
			Combat combat = MULTI.matcher(rest).find() ? Combat.MULTI : SINGLE.matcher(rest).find() ? Combat.SINGLE : null;
			place = COMBAT_NOTE.matcher(place.replaceAll("[.!\\s]+$", "")).replaceAll("").replaceAll("[.!\\s]+$", "");
			return of(Kind.BREACH, place, combat);
		}
		return Optional.empty();
	}

	/** The game's wording of an event (the developer tools feed this to {@link #parse}). */
	public static String gameText(Kind kind, String location, Combat combat)
	{
		if (kind == Kind.CHEST)
		{
			return "A Deadman's Chest has spawned at " + location + "!";
		}
		return "A breach has spawned at " + location + "! Powerful monsters now roam the area"
			+ (combat == null ? "." : combat == Combat.MULTI ? " (Multi)." : " (Single).");
	}

	private static Optional<WorldEventMessage> of(Kind kind, String place, Combat combat)
	{
		String p = place.trim();
		if (p.length() > MAX_LOCATION || !HAS_WORD.matcher(p).find())
		{
			return Optional.empty();
		}
		return Optional.of(new WorldEventMessage(kind, p, combat));
	}

	/** Tags removed, curly apostrophes made straight, spaces collapsed. */
	static String clean(String raw)
	{
		return Text.removeTags(raw)
			.replace('’', '\'')
			.replace('‘', '\'')
			.replace(' ', ' ')
			.replaceAll("\\s+", " ")
			.trim();
	}
}

package com.deadmantoolkit.world;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * World events on the minimap: an event within the minimap's reach is drawn at its spot; one further away gets an
 * arrow on the minimap's rim pointing towards it (the minimap turns with the camera; the arrows turn with it). A place
 * on another map is pointed at through its surface entrance. Region-only events point at the region's middle.
 */
public final class WorldEventMinimapOverlay extends Overlay
{
	/** Distance of the arrow from the minimap's centre, in pixels (the minimap's radius is about 73). */
	static final int RIM = 54;
	/** How far ahead the direction is sampled, in tiles. */
	private static final int STEP_TILES = 4;
	/** Surface world coordinates end about here (underground areas and other maps lie further north). */
	private static final int SURFACE_MAX_Y = 4200;

	private final Client client;
	/** The events to show now (empty when hidden, or not logged in on world 345). Client thread. */
	private final Supplier<List<WorldEvents.Event>> events;

	public WorldEventMinimapOverlay(Client client, Supplier<List<WorldEvents.Event>> events)
	{
		this.client = client;
		this.events = events;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		List<WorldEvents.Event> list = events.get();
		if (list.isEmpty())
		{
			return null;
		}
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return null;
		}
		LocalPoint here = me.getLocalLocation();
		WorldPoint at = me.getWorldLocation();
		if (here == null || at == null)
		{
			return null;
		}
		Point centre = Perspective.localToMinimap(client, here);
		if (centre == null)
		{
			return null; // minimap hidden
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		for (WorldEvents.Event e : list)
		{
			WorldPoint target = target(e, at);
			if (target == null)
			{
				continue;
			}
			int dx = target.getX() - at.getX();
			int dy = target.getY() - at.getY();
			BufferedImage icon = WorldEventIcons.minimap(e.getKind(), e.getWhere().getAccuracy());
			Point spot = Perspective.localToMinimap(client,
				new LocalPoint(here.getX() + dx * Perspective.LOCAL_TILE_SIZE, here.getY() + dy * Perspective.LOCAL_TILE_SIZE,
					here.getWorldView()));
			if (spot != null && Math.hypot(spot.getX() - centre.getX(), spot.getY() - centre.getY()) <= RIM)
			{
				g.drawImage(icon, spot.getX() - icon.getWidth() / 2, spot.getY() - icon.getHeight() / 2, null);
				continue;
			}
			double len = Math.hypot(dx, dy);
			if (len < 1)
			{
				continue;
			}
			Point step = Perspective.localToMinimap(client, new LocalPoint(
				here.getX() + (int) Math.round(dx / len * STEP_TILES * Perspective.LOCAL_TILE_SIZE),
				here.getY() + (int) Math.round(dy / len * STEP_TILES * Perspective.LOCAL_TILE_SIZE), here.getWorldView()));
			if (step == null)
			{
				continue;
			}
			double vx = step.getX() - centre.getX();
			double vy = step.getY() - centre.getY();
			double vl = Math.hypot(vx, vy);
			if (vl < 0.5)
			{
				continue;
			}
			drawArrow(g, centre, vx / vl, vy / vl, e.getKind(), icon);
		}
		return null;
	}

	/** Where to point for {@code e} from {@code at}: its spot, or the surface entrance of a place on another map. */
	static WorldPoint target(WorldEvents.Event e, WorldPoint at)
	{
		WorldLocations.Resolved w = e.getWhere();
		if (w == null || !w.known())
		{
			return null;
		}
		WorldPoint p = w.getPoint();
		boolean meOnSurface = at.getY() < SURFACE_MAX_Y;
		boolean itOnSurface = p.getY() < SURFACE_MAX_Y;
		if (meOnSurface == itOnSurface)
		{
			// Underground both: only when it's the same area (a few hundred tiles at most).
			return itOnSurface || Math.abs(p.getX() - at.getX()) + Math.abs(p.getY() - at.getY()) < 400 ? p : null;
		}
		return meOnSurface ? w.getEntrance() : null;
	}

	/** An arrow on the rim in direction (ux, uy) with the event's badge just inside it. */
	private static void drawArrow(Graphics2D g, Point centre, double ux, double uy, WorldEventMessage.Kind kind,
		BufferedImage icon)
	{
		double bx = centre.getX() + ux * RIM;
		double by = centre.getY() + uy * RIM;
		// Perpendicular for the arrow's base.
		double px = -uy;
		double py = ux;
		Path2D a = new Path2D.Double();
		a.moveTo(bx + ux * 9, by + uy * 9);
		a.lineTo(bx + px * 6, by + py * 6);
		a.lineTo(bx - px * 6, by - py * 6);
		a.closePath();
		g.setStroke(new BasicStroke(2.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(WorldEventIcons.OUTLINE);
		g.draw(a);
		g.setColor(WorldEventIcons.color(kind));
		g.fill(a);
		double ix = bx - ux * (icon.getWidth() / 2.0 + 1);
		double iy = by - uy * (icon.getHeight() / 2.0 + 1);
		g.drawImage(icon, (int) Math.round(ix - icon.getWidth() / 2.0), (int) Math.round(iy - icon.getHeight() / 2.0), null);
	}
}

package com.deadmantoolkit.world;

import com.deadmantoolkit.BreachSchedule;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import lombok.Value;

/**
 * The world events going on now: the current Deadman's Chest and any breaches. Times come from the broadcast itself
 * (when it arrived, or the server's first report), never from a fixed schedule, since the game is up to a minute or so
 * off its :00 / :15 marks.
 * <ul>
 * <li>One chest at a time: a new chest replaces the last one, which otherwise stays listed {@link #CHEST_LIFE}.</li>
 * <li>Breaches come in waves of several; each is listed {@link #BREACH_LIFE}: its 15 minutes of spawning, then
 * {@link #AFTER_SPAWN} more (the monsters left can stay up to 30 minutes, but by then the breach is over).</li>
 * <li>The same event reported again (the broadcast repeated, or the server's copy of one seen here) within
 * {@link #SAME} is one event: the earliest time wins, and a sighting here wins over the server's.</li>
 * </ul>
 * Pure; one thread (the client thread).
 */
public final class WorldEvents
{
	/** How long a breach stays listed after its spawning ends. */
	static final Duration AFTER_SPAWN = Duration.ofMinutes(5);
	public static final Duration BREACH_LIFE = BreachSchedule.SPAWN.plus(AFTER_SPAWN);
	/** A chest is soon looted: it is listed this long after its broadcast (or until the next chest). */
	public static final Duration CHEST_LIFE = Duration.ofMinutes(10);
	/** Reports of one event this far apart (or less) are the same event. */
	static final Duration SAME = Duration.ofMinutes(5);
	/** Most breaches kept at once; a wave is far smaller. */
	static final int MAX_BREACHES = 16;

	/** Where an event came from. */
	public enum Source
	{
		/** The broadcast arrived in this client. */
		SEEN,
		/** The server's list (other players saw it; for late logins). */
		REPORTED,
		/** The developer tools. */
		TEST
	}

	@Value
	public static class Event
	{
		WorldEventMessage.Kind kind;
		/** As the game wrote it. */
		String location;
		/** Breaches: Single / Multi when known. */
		WorldEventMessage.Combat combat;
		Instant at;
		Instant until;
		WorldLocations.Resolved where;
		Source source;
		/** Players who reported it to the server (0 when only seen here). */
		int reporters;

		/** Same kind and place (wording compared like {@link WorldLocations#key}). */
		boolean samePlace(WorldEventMessage.Kind k, String text)
		{
			return kind == k && WorldLocations.key(location).equals(WorldLocations.key(text));
		}
	}

	private Event chest;
	private final List<Event> breaches = new ArrayList<>();

	/**
	 * Add an event.
	 *
	 * @return true when the list changed (a new event, or a better copy of one listed)
	 */
	public boolean add(WorldEventMessage m, Instant at, WorldLocations.Resolved where, Source source, int reporters)
	{
		Instant until = at.plus(m.getKind() == WorldEventMessage.Kind.CHEST ? CHEST_LIFE : BREACH_LIFE);
		Event e = new Event(m.getKind(), m.getLocation(), m.getCombat(), at, until, where, source, reporters);
		if (m.getKind() == WorldEventMessage.Kind.CHEST)
		{
			if (chest != null && chest.samePlace(m.getKind(), m.getLocation()) && near(chest.at, at))
			{
				Event merged = merge(chest, e);
				boolean changed = !merged.equals(chest);
				chest = merged;
				return changed;
			}
			if (chest != null && at.isBefore(chest.at))
			{
				// An older chest (a late server report): the newer one stays.
				return false;
			}
			chest = e;
			return true;
		}
		for (int i = 0; i < breaches.size(); i++)
		{
			Event b = breaches.get(i);
			if (b.samePlace(m.getKind(), m.getLocation()) && near(b.at, at))
			{
				Event merged = merge(b, e);
				boolean changed = !merged.equals(b);
				breaches.set(i, merged);
				return changed;
			}
		}
		breaches.add(e);
		breaches.sort(Comparator.comparing(Event::getAt));
		while (breaches.size() > MAX_BREACHES)
		{
			breaches.remove(0);
		}
		return true;
	}

	/** Forget everything (logged out of world 345, or the developer tools' clear). */
	public void clear()
	{
		chest = null;
		breaches.clear();
	}

	/** Drop ended events. @return true when something was dropped */
	public boolean expire(Instant now)
	{
		boolean changed = false;
		if (chest != null && !now.isBefore(chest.until))
		{
			chest = null;
			changed = true;
		}
		changed |= breaches.removeIf(b -> !now.isBefore(b.until));
		return changed;
	}

	/** The chest (if any) first, then breaches, oldest first. Call {@link #expire} first. */
	public List<Event> active()
	{
		List<Event> out = new ArrayList<>();
		if (chest != null)
		{
			out.add(chest);
		}
		out.addAll(breaches);
		return out;
	}

	/** Re-resolve every place (after a newer place list arrived). */
	public void reresolve(WorldLocations locations)
	{
		if (chest != null)
		{
			chest = withWhere(chest, locations.resolve(chest.location));
		}
		breaches.replaceAll(b -> withWhere(b, locations.resolve(b.location)));
	}

	private static Event withWhere(Event e, WorldLocations.Resolved where)
	{
		return new Event(e.kind, e.location, e.combat, e.at, e.until, where, e.source, e.reporters);
	}

	private static boolean near(Instant a, Instant b)
	{
		return Duration.between(a, b).abs().compareTo(SAME) <= 0;
	}

	/** One event from two reports: the earliest time, a sighting here over the server's, the most reporters. */
	private static Event merge(Event a, Event b)
	{
		Event first = b.at.isBefore(a.at) ? b : a;
		Source source = a.source == Source.SEEN || b.source == Source.SEEN ? Source.SEEN : first.source;
		WorldEventMessage.Combat combat = a.combat != null ? a.combat : b.combat;
		WorldLocations.Resolved where = better(a.where, b.where);
		return new Event(first.kind, first.location, combat, first.at, first.until, where, source,
			Math.max(a.reporters, b.reporters));
	}

	private static WorldLocations.Resolved better(WorldLocations.Resolved a, WorldLocations.Resolved b)
	{
		if (a == null)
		{
			return b;
		}
		if (b == null)
		{
			return a;
		}
		return b.getAccuracy().ordinal() < a.getAccuracy().ordinal() ? b : a;
	}
}

package com.deadmantoolkit.world;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * Where a broadcast's place text is on the map. Handles:
 * <ul>
 * <li>known places and their other names ("Warriors' Guild", "the GE"), whatever the case, punctuation, "the" and
 * compass spelling ("Northwest", "north-west");</li>
 * <li>the game's own wording of a known event spot ("Outside the Al Kharid bank" is a chest tile, not the bank);</li>
 * <li>near spellings and shortenings of a whole name ("North of Edge Monastry"): every word must line up with the
 * name's (the same, a shortening of at least 4 letters, or a letter or two off in a long word), and only one place
 * may fit; such a match is marked {@link Resolved#isFuzzy()};</li>
 * <li>a direction from a place ("north of the Warriors' Guild"): the marker moves about {@value #NEAR} tiles that way,
 * marked approximate;</li>
 * <li>kingdoms and regions ("Kingdom of Asgarnia", "North of Asgarnia", "the eastern Asgarnian kingdom"): a rough
 * marker in that part of the region;</li>
 * <li>wording around the place ("Throughout", "Within", "Surrounding", "On top of", "The mounds at", "near", ...);</li>
 * <li>places on another map (Zanaris, the Mole Hole): their own spot plus their surface entrance.</li>
 * </ul>
 * Anything else resolves to {@link Accuracy#UNKNOWN} and is collected so the place file can grow. Immutable once built
 * (any thread may build one; {@link #resolve} only reads).
 */
public final class WorldLocations
{
	public enum Accuracy
	{
		/** The spot itself (a known place). */
		EXACT,
		/** Near a known place ("north of ..."), or a place mentioned in longer wording. */
		APPROXIMATE,
		/** Only the kingdom or region is known. */
		REGION,
		/** Not a place the plugin knows. */
		UNKNOWN;

		public String id()
		{
			return name().toLowerCase(Locale.ROOT);
		}
	}

	@Value
	public static class Resolved
	{
		Accuracy accuracy;
		/** Where the marker goes; null when unknown. */
		WorldPoint point;
		/** About how far off the marker may be, in tiles (0 when exact). */
		int radius;
		/** The place it was matched to ("Warriors' Guild", "Asgarnia"); null when unknown. */
		String place;
		/** For places on another map: the surface entrance and its name; null otherwise. */
		WorldPoint entrance;
		String entranceName;
		/** Matched by a near spelling or a shortening, not the place's own wording. */
		boolean fuzzy;

		static final Resolved UNKNOWN = new Resolved(Accuracy.UNKNOWN, null, 0, null, null, null, false);

		public boolean known()
		{
			return point != null;
		}

		/** How the plugin rates this match when telling the server (a fuzzy match is never "exact"). */
		public Accuracy reported()
		{
			return fuzzy && accuracy == Accuracy.EXACT ? Accuracy.APPROXIMATE : accuracy;
		}
	}

	/** How far "north of X" is from X, in tiles. */
	static final int NEAR = 24;
	/** A direction within a region moves this share of its radius. */
	private static final double REGION_SHIFT = 0.6;

	private static final String DIR = "north east|north west|south east|south west|north|south|east|west";
	private static final Pattern DIRECTION_OF = Pattern.compile("^(?:(.*?)\\s)??(" + DIR + ")(?:ern)?\\s(?:of|from)\\s(.+)$");
	private static final Pattern DIRECTION_ADJ = Pattern.compile("^(" + DIR + "|central|middle)(?:ern)?\\s(?:part of\\s)?(.+)$");
	/** One-word compass spellings, written as two words in match keys. */
	private static final Map<String, String> COMPASS = new HashMap<>();

	static
	{
		for (String ns : new String[]{"north", "south"})
		{
			for (String ew : new String[]{"east", "west"})
			{
				COMPASS.put(ns + ew, ns + " " + ew);
				COMPASS.put(ns + ew + "ern", ns + " " + ew + "ern");
			}
		}
	}

	/** Used when a place file has no wording of its own. */
	private static final List<String> LEADS = Arrays.asList(
		"the outskirts of", "the area around", "the mounds at", "the mounds of", "the area near", "somewhere in",
		"just outside", "the area of", "the ruins at", "the top of", "the mounds", "surrounding", "throughout",
		"on top of", "the area", "outside", "within", "around", "nearby", "inside", "deep in", "near", "in", "at",
		"on", "by");
	private static final List<String> TAILS = Arrays.asList("kingdom", "region", "area", "lands", "province");

	/** One name or alias, split into words for the near-spelling match. */
	private static final class Name
	{
		final String[] words;
		final WorldPlaces.Place place;

		Name(String key, WorldPlaces.Place place)
		{
			this.words = key.split(" ");
			this.place = place;
		}
	}

	private final WorldPlaces.Table table;
	private final List<WorldPlaces.Place> places;
	private final List<String> leads;
	private final List<String> tails;
	/** Match key of a name or alias -> place. */
	private final Map<String, WorldPlaces.Place> byName = new HashMap<>();
	/** Names longest first, for finding a place inside longer wording. */
	private final List<String> namesLongestFirst;
	private final List<Name> names = new ArrayList<>();

	/** The places bundled with the plugin ({@link WorldPlaces#RESOURCE}). Reads a resource: not on the client thread. */
	public static WorldLocations load(Gson gson)
	{
		return new WorldLocations(WorldPlaces.bundled(gson));
	}

	public WorldLocations(WorldPlaces.Table table)
	{
		this.table = table;
		this.places = table.getPlaces();
		this.leads = table.getLeads().isEmpty() ? words(LEADS) : table.getLeads();
		this.tails = table.getTails().isEmpty() ? words(TAILS) : table.getTails();
		for (WorldPlaces.Place p : places)
		{
			index(p.getName(), p);
			for (String a : p.getAliases())
			{
				index(a, p);
			}
		}
		List<String> all = new ArrayList<>(byName.keySet());
		all.sort((a, b) -> b.length() - a.length());
		namesLongestFirst = Collections.unmodifiableList(all);
	}

	private void index(String name, WorldPlaces.Place p)
	{
		String k = matchKey(name);
		if (!k.isEmpty() && byName.putIfAbsent(k, p) == null)
		{
			names.add(new Name(k, p));
		}
	}

	/** Words in match-key form, longest first, without duplicates or empties. */
	static List<String> words(List<String> in)
	{
		LinkedHashSet<String> out = new LinkedHashSet<>();
		for (String w : in)
		{
			String k = w == null ? "" : matchKey(w);
			if (!k.isEmpty())
			{
				out.add(k);
			}
		}
		List<String> list = new ArrayList<>(out);
		list.sort((a, b) -> b.length() - a.length());
		return Collections.unmodifiableList(list);
	}

	/** The places this resolver knows (for tests and the developer tools). */
	List<WorldPlaces.Place> places()
	{
		return places;
	}

	/** The place file in use. */
	public WorldPlaces.Table table()
	{
		return table;
	}

	/** The revision of the place file in use (higher is newer). */
	public long revision()
	{
		return table.getRevision();
	}

	public Resolved resolve(String text)
	{
		if (text == null)
		{
			return Resolved.UNKNOWN;
		}
		String full = matchKey(text);
		// The broadcast's exact wording is often a place of its own ("Outside the Al Kharid bank" is a chest spot,
		// not the bank), so the full text goes first, before any wording is dropped.
		WorldPlaces.Place exact = byName.get(full);
		if (exact != null)
		{
			return at(exact, null, exact.isRegion() ? Accuracy.REGION : Accuracy.EXACT, false);
		}
		String k = stripLeads(full);
		if (k.isEmpty())
		{
			return Resolved.UNKNOWN;
		}
		// A whole name: "West Ardougne" is a place, not west of Ardougne.
		WorldPlaces.Place whole = lookup(k);
		if (whole != null)
		{
			return at(whole, null, whole.isRegion() ? Accuracy.REGION : Accuracy.EXACT, false);
		}
		// A whole name spelled a little differently or shortened ("North of Edge Monastry").
		WorldPlaces.Place near = nearSpelling(full);
		if (near == null && !k.equals(full))
		{
			near = nearSpelling(k);
		}
		if (near != null)
		{
			return at(near, null, near.isRegion() ? Accuracy.REGION : Accuracy.EXACT, true);
		}

		// "north of X", also inside longer wording ("the ruins west of X").
		Matcher m = DIRECTION_OF.matcher(k);
		if (m.matches())
		{
			Resolved r = shifted(m.group(3), m.group(2));
			if (r != null)
			{
				return r;
			}
		}
		// "northern X", "the southern X kingdom", "north X", "central X".
		m = DIRECTION_ADJ.matcher(k);
		if (m.matches())
		{
			Resolved r = shifted(m.group(2), m.group(1));
			if (r != null)
			{
				return r;
			}
		}
		// A known place somewhere in longer wording ("the old ruins by Lumbridge"): near it.
		WorldPlaces.Place p = mentioned(k);
		if (p != null)
		{
			return at(p, null, p.isRegion() ? Accuracy.REGION : Accuracy.APPROXIMATE, false);
		}
		return Resolved.UNKNOWN;
	}

	/** {@code rest} moved towards {@code direction}, or null when {@code rest} isn't a known place. */
	private Resolved shifted(String rest, String direction)
	{
		String r = stripLeads(rest);
		WorldPlaces.Place p = lookup(r);
		boolean fuzzy = false;
		if (p == null)
		{
			p = nearSpelling(r);
			fuzzy = p != null;
		}
		if (p == null)
		{
			p = mentioned(r);
		}
		if (p == null)
		{
			return null;
		}
		return at(p, direction, p.isRegion() ? Accuracy.REGION : Accuracy.APPROXIMATE, fuzzy);
	}

	private Resolved at(WorldPlaces.Place p, String direction, Accuracy accuracy, boolean fuzzy)
	{
		WorldPoint base = p.getPoint();
		int radius = p.isRegion() ? p.getRadius() : accuracy == Accuracy.EXACT ? 0 : NEAR;
		WorldPoint point = base;
		if (direction != null)
		{
			int distance = p.isRegion() ? (int) Math.round(p.getRadius() * REGION_SHIFT) : NEAR;
			int[] d = unit(direction);
			if (d[0] != 0 && d[1] != 0)
			{
				// Diagonal: the same distance, not further.
				distance = (int) Math.round(distance / Math.sqrt(2));
			}
			point = new WorldPoint(base.getX() + d[0] * distance, base.getY() + d[1] * distance, base.getPlane());
			if (p.isRegion())
			{
				radius = (int) Math.round(p.getRadius() * (1 - REGION_SHIFT));
			}
		}
		return new Resolved(accuracy, point, radius, p.getName(), p.getEntrance(), p.getEntranceName(), fuzzy);
	}

	/** {dx, dy} for a direction word (north is +y, east is +x); {0, 0} for central. */
	private static int[] unit(String direction)
	{
		String d = direction.replace(" ", "");
		int dx = d.contains("east") ? 1 : d.contains("west") ? -1 : 0;
		int dy = d.startsWith("north") ? 1 : d.startsWith("south") ? -1 : 0;
		return new int[]{dx, dy};
	}

	/** A place by its whole name, also with "kingdom" / "region" / ... dropped from either end. */
	private WorldPlaces.Place lookup(String k)
	{
		WorldPlaces.Place p = byName.get(k);
		if (p != null)
		{
			return p;
		}
		String s = k;
		if (s.startsWith("kingdom of "))
		{
			s = s.substring("kingdom of ".length());
		}
		for (String tail : tails)
		{
			if (s.endsWith(" " + tail))
			{
				s = s.substring(0, s.length() - tail.length() - 1);
			}
		}
		s = stripLeads(s);
		return s.equals(k) ? null : byName.get(s);
	}

	/**
	 * The one place whose name (or alias) lines up word for word with {@code k}, allowing shortenings and small
	 * misspellings ({@link #wordScore}); null when none does, or when two different places fit equally well.
	 */
	WorldPlaces.Place nearSpelling(String k)
	{
		String[] q = k.split(" ");
		int best = 0;
		WorldPlaces.Place found = null;
		boolean tie = false;
		for (Name n : names)
		{
			if (n.words.length != q.length)
			{
				continue;
			}
			int score = 0;
			int exactWords = 0;
			for (int i = 0; i < q.length && score >= 0; i++)
			{
				int s = wordScore(q[i], n.words[i]);
				if (s == 0)
				{
					score = -1;
				}
				else
				{
					score += s;
					exactWords += s == 3 ? 1 : 0;
				}
			}
			// A lone short word that isn't spelled out ("edge") is too weak to guess from.
			if (score <= 0 || (q.length == 1 && exactWords == 0 && q[0].length() < 5))
			{
				continue;
			}
			if (score > best)
			{
				best = score;
				found = n.place;
				tie = false;
			}
			else if (score == best && n.place != found)
			{
				tie = true;
			}
		}
		return tie ? null : found;
	}

	/**
	 * How well a word of the broadcast fits a word of a name: 3 the same, 2 a shortening of the name's word (at least 4
	 * letters, "edge" for "edgeville"), 1 the name's word with a letter or two more ("mines" for "mine") or a
	 * misspelling (one letter off in a word of 5+, two in a word of 8+), 0 no fit. Numbers and compass words must be
	 * exact (north and south differ by two letters).
	 */
	static int wordScore(String q, String n)
	{
		if (q.equals(n))
		{
			return 3;
		}
		if (COMPASS_WORDS.contains(q) || COMPASS_WORDS.contains(n) || hasDigit(q) || hasDigit(n))
		{
			return 0;
		}
		int min = Math.min(q.length(), n.length());
		if (min >= 4 && n.startsWith(q))
		{
			return 2;
		}
		if (min >= 4 && q.startsWith(n) && q.length() - n.length() <= 2)
		{
			return 1;
		}
		if (min >= 5)
		{
			int allowed = min >= 8 ? 2 : 1;
			if (Math.abs(q.length() - n.length()) <= allowed && distance(q, n, allowed) <= allowed)
			{
				return 1;
			}
		}
		return 0;
	}

	private static final java.util.Set<String> COMPASS_WORDS = new java.util.HashSet<>(Arrays.asList(
		"north", "south", "east", "west", "northern", "southern", "eastern", "western", "of", "from"));

	private static boolean hasDigit(String s)
	{
		for (int i = 0; i < s.length(); i++)
		{
			if (Character.isDigit(s.charAt(i)))
			{
				return true;
			}
		}
		return false;
	}

	/** Optimal string alignment distance (a swap of two neighbours counts once), stopping early above {@code max}. */
	static int distance(String a, String b, int max)
	{
		int[][] d = new int[a.length() + 1][b.length() + 1];
		for (int i = 0; i <= a.length(); i++)
		{
			d[i][0] = i;
		}
		for (int j = 0; j <= b.length(); j++)
		{
			d[0][j] = j;
		}
		for (int i = 1; i <= a.length(); i++)
		{
			int rowMin = Integer.MAX_VALUE;
			for (int j = 1; j <= b.length(); j++)
			{
				int cost = a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1;
				int v = Math.min(Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1), d[i - 1][j - 1] + cost);
				if (i > 1 && j > 1 && a.charAt(i - 1) == b.charAt(j - 2) && a.charAt(i - 2) == b.charAt(j - 1))
				{
					v = Math.min(v, d[i - 2][j - 2] + 1);
				}
				d[i][j] = v;
				rowMin = Math.min(rowMin, v);
			}
			if (rowMin > max)
			{
				return max + 1;
			}
		}
		return d[a.length()][b.length()];
	}

	/** The longest known name that appears as whole words in {@code k}, or null. */
	private WorldPlaces.Place mentioned(String k)
	{
		String padded = " " + k + " ";
		for (String name : namesLongestFirst)
		{
			// Very short names (an alias like "ge") only count on their own, never inside other wording.
			if (name.length() >= 4 && padded.contains(" " + name + " "))
			{
				return byName.get(name);
			}
		}
		return null;
	}

	private String stripLeads(String k)
	{
		String s = k;
		boolean changed = true;
		while (changed)
		{
			changed = false;
			for (String lead : leads)
			{
				if (s.startsWith(lead + " "))
				{
					s = s.substring(lead.length() + 1);
					changed = true;
				}
			}
		}
		return s;
	}

	/**
	 * The text in a comparable form: lower case, apostrophes dropped ("Warriors' Guild" and "warriors guild" match),
	 * other punctuation as spaces, spaces collapsed. The server groups place names by the same key.
	 */
	public static String key(String text)
	{
		return text.toLowerCase(Locale.ROOT)
			.replace("’", "")
			.replace("'", "")
			.replaceAll("[^a-z0-9]+", " ")
			.trim();
	}

	/**
	 * {@link #key} for matching: also without "the" (the game says "north of the X" and "north of X" alike) and with
	 * one-word compass spellings split ("northwest" -> "north west", "northeastern" -> "north eastern").
	 */
	public static String matchKey(String text)
	{
		String k = key(text);
		if (k.isEmpty())
		{
			return k;
		}
		StringBuilder sb = new StringBuilder(k.length());
		for (String w : k.split(" "))
		{
			if (w.equals("the"))
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(' ');
			}
			String c = COMPASS.get(w);
			sb.append(c != null ? c : w);
		}
		return sb.toString();
	}
}

package com.deadmantoolkit.world;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.util.Text;

/**
 * The places a broadcast can name: towns, guilds, landmarks and Wilderness spots with their map coordinates, and the
 * kingdoms and regions a broadcast sometimes names instead ("North of Asgarnia", "the Kingdom of Kandarin"). Places on
 * another map (Zanaris, the Mole Hole, Mor Ul Rek) give their own coordinates and a surface entrance. The file also
 * lists the wording dropped around a place ("Throughout", "the mounds at", "... kingdom").
 * <p>
 * A copy, {@value #RESOURCE}, ships with the plugin; the server serves the current one (GET v1/world-places), so places
 * can be added or fixed without a plugin release. Whichever copy has the highest {@code revision} is used (the
 * server's is also saved in the plugin folder for the next start). Names the plugin can't place are collected
 * ({@link UnresolvedLog}, and the server's list) so the file can grow.
 */
@Slf4j
public final class WorldPlaces
{
	static final String RESOURCE = "world-places.json";
	/** Radius of a place that doesn't give one, in tiles. */
	static final int SPOT = 8;
	/** Bounds on a place file (any copy, including the server's): only names and map tiles, never more than this. */
	static final int MAX_ENTRIES = 5000;
	static final int MAX_ALIASES = 20;
	static final int MAX_NAME = 80;
	static final int MAX_RADIUS = 600;
	static final int MAX_COORD = 16384;
	static final int MAX_WORDS = 100;

	@Value
	public static class Place
	{
		String name;
		/** Other names, matched like {@link #name} (case, apostrophes and punctuation don't matter). */
		List<String> aliases;
		WorldPoint point;
		/** A kingdom or region, not one spot: markers are rough, and direction words move them further. */
		boolean region;
		/** How far the place spreads, in tiles. */
		int radius;
		/** For places on another map: where you go in from the surface, and what it is; null otherwise. */
		WorldPoint entrance;
		String entranceName;
	}

	/** A parsed copy of the file. */
	@Value
	public static class Table
	{
		/** Higher is newer. */
		long revision;
		List<Place> places;
		/** Words dropped from the front of a place before matching, longest first; empty for the built-in list. */
		List<String> leads;
		/** Words dropped from the end ("kingdom", "region"); empty for the built-in list. */
		List<String> tails;

		static final Table EMPTY = new Table(0, Collections.emptyList(), Collections.emptyList(), Collections.emptyList());
	}

	/** The file's shape (Gson). */
	static final class FileData
	{
		int version;
		long revision;
		Wording wording;
		List<Entry> places;
		List<Entry> regions;
	}

	static final class Wording
	{
		List<String> leads;
		List<String> tails;
	}

	static final class Entry
	{
		String name;
		List<String> aliases;
		Integer x;
		Integer y;
		Integer plane;
		Integer radius;
		Entrance entrance;
	}

	static final class Entrance
	{
		String name;
		Integer x;
		Integer y;
		Integer plane;
	}

	private WorldPlaces()
	{
	}

	/** The copy bundled with the plugin; empty (and a warning logged) if it can't be read. */
	public static Table bundled(Gson gson)
	{
		try (InputStream in = WorldPlaces.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("{} is missing; world event places won't be shown on the map", RESOURCE);
				return Table.EMPTY;
			}
			try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				return parse(gson.fromJson(r, FileData.class));
			}
		}
		catch (IOException | JsonParseException ex)
		{
			log.warn("Couldn't read {}", RESOURCE, ex);
			return Table.EMPTY;
		}
	}

	/** A copy from the server or the plugin folder; null when it isn't one (or has no places). */
	public static Table parse(Gson gson, String json)
	{
		try
		{
			Table t = parse(gson.fromJson(json, FileData.class));
			return t.getPlaces().isEmpty() ? null : t;
		}
		catch (JsonParseException ex)
		{
			return null;
		}
	}

	/** The usable entries of {@code data}; entries without a name or coordinates are skipped. */
	static Table parse(FileData data)
	{
		if (data == null)
		{
			return Table.EMPTY;
		}
		List<Place> out = new ArrayList<>();
		add(out, data.places, false);
		add(out, data.regions, true);
		// In match-key form ("the" dropped, so "the mounds at" is "mounds at"), longest first.
		List<String> leads = data.wording == null || data.wording.leads == null ? Collections.emptyList()
			: WorldLocations.words(bounded(data.wording.leads));
		List<String> tails = data.wording == null || data.wording.tails == null ? Collections.emptyList()
			: WorldLocations.words(bounded(data.wording.tails));
		return new Table(data.revision, Collections.unmodifiableList(out), leads, tails);
	}

	private static void add(List<Place> out, List<Entry> entries, boolean region)
	{
		if (entries == null)
		{
			return;
		}
		for (Entry e : entries)
		{
			if (out.size() >= MAX_ENTRIES)
			{
				return;
			}
			String name = text(e == null ? null : e.name);
			if (name == null || !onMap(e.x, e.y, e.plane))
			{
				continue;
			}
			List<String> aliases = new ArrayList<>();
			if (e.aliases != null)
			{
				for (String a : e.aliases)
				{
					String alias = text(a);
					if (alias != null && aliases.size() < MAX_ALIASES)
					{
						aliases.add(alias);
					}
				}
			}
			WorldPoint entrance = null;
			String entranceName = null;
			if (e.entrance != null && onMap(e.entrance.x, e.entrance.y, e.entrance.plane) && text(e.entrance.name) != null)
			{
				entrance = new WorldPoint(e.entrance.x, e.entrance.y, e.entrance.plane == null ? 0 : e.entrance.plane);
				entranceName = text(e.entrance.name);
			}
			int radius = e.radius == null || e.radius < 0 ? SPOT : Math.min(e.radius, MAX_RADIUS);
			out.add(new Place(name, Collections.unmodifiableList(aliases),
				new WorldPoint(e.x, e.y, e.plane == null ? 0 : e.plane), region, radius, entrance, entranceName));
		}
	}

	/** At most {@value #MAX_WORDS} words of at most {@value #MAX_NAME} characters. */
	private static List<String> bounded(List<String> words)
	{
		List<String> out = new ArrayList<>();
		for (String w : words)
		{
			String t = text(w);
			if (t != null && out.size() < MAX_WORDS)
			{
				out.add(t);
			}
		}
		return out;
	}

	/** Plain text (no markup), trimmed, at most {@value #MAX_NAME} characters; null when unusable. */
	private static String text(String s)
	{
		if (s == null)
		{
			return null;
		}
		String t = Text.removeTags(s).trim();
		return t.isEmpty() || t.length() > MAX_NAME ? null : t;
	}

	/** A tile in the game world (coordinates within its bounds, plane 0-3). */
	private static boolean onMap(Integer x, Integer y, Integer plane)
	{
		return x != null && y != null && x >= 0 && x < MAX_COORD && y >= 0 && y < MAX_COORD
			&& (plane == null || (plane >= 0 && plane <= 3));
	}
}

package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class AccountIdTest
{
	@Test
	public void knownVectors()
	{
		// sha256("deadman-ge-tracker:123456789")
		assertEquals("77c9f0b595b7169fa5ed9141da926410d64dcc0e29f230bfbf782246d49e6b01", AccountId.of(123456789L));
		// sha256("deadman-ge-tracker:-42")
		assertEquals("5e91e63dc4c2292f25e8b179ee7bab1cef0a7ab2603f3fbb76a5656af6350f27", AccountId.of(-42L));
	}

	@Test
	public void saltedLowercaseHex()
	{
		String id = AccountId.of(Long.MAX_VALUE);
		assertEquals(64, id.length());
		assertTrue(id.matches("[0-9a-f]{64}"));
		// Not the plain hash of the account hash: the prefix is included.
		assertNotEquals("15e2b0d3c33891ebb0f1ef609ec419420c20e320ce94c65fbc8c3312448eb225", AccountId.of(123456789L));
		assertNotEquals(AccountId.of(1L), AccountId.of(2L));
		assertEquals(AccountId.of(7L), AccountId.of(7L));
	}
