package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import net.runelite.api.events.CommandExecuted;
import org.junit.Test;

/** The developer-mode ::breach preview: command parsing, clock offsets and the command handler. */
public class BreachPreviewTest
{
	/** A Wednesday: no breach for days. */
	private static final Instant WED = Instant.parse("2026-10-07T12:34:56Z");
	/** A Saturday during a real breach (14:00 UTC start). */
	private static final Instant SAT = Instant.parse("2026-10-10T14:05:00Z");

	private static Optional<BreachPreview.Command> parse(String... args)
	{
		return BreachPreview.parse(args);
	}

	@Test
	public void parsesCommands()
	{
		assertEquals(BreachPreview.Action.SOON, parse("soon").get().getAction());
		assertEquals(BreachPreview.Action.ACTIVE, parse("ACTIVE").get().getAction());
		assertEquals(BreachPreview.Action.DESPAWN, parse("despawn").get().getAction());
		assertEquals(BreachPreview.Action.OFF, parse("off").get().getAction());
		assertEquals(new BreachPreview.Command(BreachPreview.Action.MSG, 1, 5), parse("msg", "1", "5").get());
		assertEquals(new BreachPreview.Command(BreachPreview.Action.MSG, 0, 0), parse("msg", "0", "0").get());
		assertFalse(parse().isPresent());
		assertFalse(BreachPreview.parse(null).isPresent());
		assertFalse(parse("later").isPresent());
		assertFalse(parse("soon", "now").isPresent());
		assertFalse(parse("msg", "1").isPresent());
		assertFalse(parse("msg", "1", "x").isPresent());
		assertFalse(parse("msg", "-1", "5").isPresent());
		assertFalse(parse("msg", "1000", "5").isPresent());
	}

	private static BreachSchedule.State shifted(BreachPreview.Action a, Instant real)
	{
		Duration off = BreachPreview.offset(a, real, Duration.ZERO);
		return BreachSchedule.state(real.plus(off), null);
	}

	@Test
	public void offsetsPutTheRealScheduleWhereAsked()
	{
		for (Instant real : new Instant[]{WED, SAT})
		{
			Duration soon = BreachPreview.offset(BreachPreview.Action.SOON, real, Duration.ZERO);
			BreachSchedule.State s = BreachSchedule.state(real.plus(soon), null);
			assertEquals(BreachSchedule.Phase.UPCOMING, s.getPhase());
			assertEquals(Duration.ofMinutes(2), Duration.between(real.plus(soon), s.getAt()));
			// ...and two minutes later it is active, then despawning: the banner runs through its phases on its own.
			assertEquals(BreachSchedule.Phase.ACTIVE, BreachSchedule.state(real.plus(soon).plus(Duration.ofMinutes(2)), null).getPhase());

			BreachSchedule.State active = shifted(BreachPreview.Action.ACTIVE, real);
			assertEquals(BreachSchedule.Phase.ACTIVE, active.getPhase());
			assertEquals(BreachSchedule.SPAWN, Duration.between(real.plus(BreachPreview.offset(BreachPreview.Action.ACTIVE,
				real, Duration.ZERO)), active.getAt()));

			Duration d = BreachPreview.offset(BreachPreview.Action.DESPAWN, real, Duration.ZERO);
			BreachSchedule.State despawn = BreachSchedule.state(real.plus(d), null);
			assertEquals(BreachSchedule.Phase.DESPAWN, despawn.getPhase());
			assertEquals(BreachSchedule.DESPAWN, Duration.between(real.plus(d), despawn.getAt()));
		}
		Duration current = Duration.ofHours(5);
		assertEquals(Duration.ZERO, BreachPreview.offset(BreachPreview.Action.OFF, WED, current));
		assertEquals(current, BreachPreview.offset(BreachPreview.Action.MSG, WED, current));
	}

	@Test
	public void msgFeedsTheParserInTheGamesWords()
	{
		assertEquals("The next breach will appear in 1 hour, 5 minutes.", BreachPreview.gameMessage(1, 5));
		assertEquals("The next breach will appear in 2 hours, 1 minute.", BreachPreview.gameMessage(2, 1));
		assertEquals(Optional.of(Duration.ofMinutes(65)), BreachMessage.parse(BreachPreview.gameMessage(1, 5)));
		assertEquals(Optional.of(Duration.ofMinutes(121)), BreachMessage.parse(BreachPreview.gameMessage(2, 1)));
		assertEquals(Optional.of(Duration.ZERO), BreachMessage.parse(BreachPreview.gameMessage(0, 0)));
	}

	@Test
	public void commandHandler()
	{
		List<String> chat = new ArrayList<>();
		List<String> fed = new ArrayList<>();
		Duration[] offset = {Duration.ZERO};
		BreachCommands commands = new BreachCommands(new BreachCommands.Target()
		{
			@Override
			public Duration offset()
			{
				return offset[0];
			}

			@Override
			public void preview(Duration o)
			{
				offset[0] = o;
			}

			@Override
			public void gameMessage(String gameText)
			{
				fed.add(gameText);
			}
		}, chat::add, () -> WED);

		commands.onCommandExecuted(new CommandExecuted("other", new String[]{"soon"}));
		assertTrue(chat.isEmpty());

		commands.onCommandExecuted(new CommandExecuted("breach", new String[]{"soon"}));
		assertEquals(BreachPreview.offset(BreachPreview.Action.SOON, WED, Duration.ZERO), offset[0]);
		assertEquals("Breach preview: next breach starts in 2 minutes.", chat.get(0));

		commands.onCommandExecuted(new CommandExecuted("breach", new String[]{"msg", "1", "5"}));
		assertEquals(1, fed.size());
		assertEquals("The next breach will appear in 1 hour, 5 minutes.", fed.get(0));
		// msg only feeds the parser; the clock stays where it was.
		assertEquals(BreachPreview.offset(BreachPreview.Action.SOON, WED, Duration.ZERO), offset[0]);

		commands.onCommandExecuted(new CommandExecuted("breach", new String[]{"off"}));
		assertEquals(Duration.ZERO, offset[0]);
		assertEquals("Breach preview off: real clock and schedule.", chat.get(chat.size() - 1));

		commands.onCommandExecuted(new CommandExecuted("breach", new String[]{"bogus"}));
		assertEquals(BreachPreview.USAGE, chat.get(chat.size() - 1));
	}
}

package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import com.deadmantoolkit.BreachSchedule.Phase;
import com.deadmantoolkit.BreachSchedule.State;
import java.time.Duration;
import java.time.Instant;
import org.junit.Test;

public class BreachScheduleTest
{
	// 2026-10-09 is a Friday, 10th Saturday, 11th Sunday, 12th Monday.
	private static Instant t(String iso)
	{
		return Instant.parse(iso);
	}

	@Test
	public void fridayNightGivesSaturday0200()
	{
		assertEquals(t("2026-10-10T02:00:00Z"), BreachSchedule.nextStart(t("2026-10-09T23:00:00Z")));
		assertEquals(new State(Phase.UPCOMING, t("2026-10-10T02:00:00Z")), BreachSchedule.state(t("2026-10-09T23:00:00Z"), null));
	}

	@Test
	public void phasesAroundAStart()
	{
		assertEquals(new State(Phase.ACTIVE, t("2026-10-10T02:15:00Z")), BreachSchedule.state(t("2026-10-10T02:00:00Z"), null));
		assertEquals(new State(Phase.ACTIVE, t("2026-10-10T02:15:00Z")), BreachSchedule.state(t("2026-10-10T02:14:59Z"), null));
		assertEquals(new State(Phase.DESPAWN, t("2026-10-10T02:45:00Z")), BreachSchedule.state(t("2026-10-10T02:15:00Z"), null));
		assertEquals(new State(Phase.DESPAWN, t("2026-10-10T02:45:00Z")), BreachSchedule.state(t("2026-10-10T02:44:59Z"), null));
		assertEquals(new State(Phase.UPCOMING, t("2026-10-10T06:00:00Z")), BreachSchedule.state(t("2026-10-10T02:45:00Z"), null));
		// Just before: still upcoming.
		assertEquals(new State(Phase.UPCOMING, t("2026-10-10T02:00:00Z")), BreachSchedule.state(t("2026-10-10T01:59:59Z"), null));
	}

	@Test
	public void sundayEveningAndAfter()
	{
		assertEquals(new State(Phase.ACTIVE, t("2026-10-11T22:15:00Z")), BreachSchedule.state(t("2026-10-11T22:10:00Z"), null));
		assertEquals(new State(Phase.DESPAWN, t("2026-10-11T22:45:00Z")), BreachSchedule.state(t("2026-10-11T22:30:00Z"), null));
		assertEquals(new State(Phase.UPCOMING, t("2026-10-17T02:00:00Z")), BreachSchedule.state(t("2026-10-11T23:00:00Z"), null));
	}

	@Test
	public void weekdaysGiveNextSaturday()
	{
		for (int day = 12; day <= 16; day++)
		{
			for (int hour : new int[]{0, 2, 12, 22, 23})
			{
				Instant now = t(String.format("2026-10-%02dT%02d:30:00Z", day, hour));
				assertEquals(now.toString(), new State(Phase.UPCOMING, t("2026-10-17T02:00:00Z")), BreachSchedule.state(now, null));
			}
		}
	}

	@Test
	public void twelveStartsPerWeek()
	{
		Instant now = t("2026-10-12T00:00:00Z");
		Instant end = now.plus(Duration.ofDays(7));
		int count = 0;
		for (Instant s = BreachSchedule.nextStart(now); s.isBefore(end); s = BreachSchedule.nextStart(s))
		{
			count++;
			assertEquals(s, BreachSchedule.lastStart(s));
			assertEquals(s, BreachSchedule.lastStart(s.plusSeconds(3599)));
		}
		assertEquals(12, count);
	}

	@Test
	public void correctionOverridesUpcomingThenExpires()
	{
		Instant now = t("2026-10-10T03:00:00Z");
		// The game says 04:30, off schedule: trusted.
		Instant corr = BreachSchedule.correct(now, Duration.ofMinutes(90));
		assertEquals(t("2026-10-10T04:30:00Z"), corr);
		assertEquals(new State(Phase.UPCOMING, corr), BreachSchedule.state(now, corr));
		assertEquals(new State(Phase.ACTIVE, t("2026-10-10T04:45:00Z")), BreachSchedule.state(t("2026-10-10T04:31:00Z"), corr));
		assertEquals(new State(Phase.DESPAWN, t("2026-10-10T05:15:00Z")), BreachSchedule.state(t("2026-10-10T05:00:00Z"), corr));
		// After its 45 minutes the schedule takes over again.
		assertEquals(new State(Phase.UPCOMING, t("2026-10-10T06:00:00Z")), BreachSchedule.state(t("2026-10-10T05:15:00Z"), corr));
	}

	@Test
	public void correctionSnapsToANearbyScheduledStart()
	{
		// "1 hour, 5 minutes" at 00:55:40 predicts 02:00:40; the game rounds, so it's the 02:00 breach.
		assertEquals(t("2026-10-10T02:00:00Z"), BreachSchedule.correct(t("2026-10-10T00:55:40Z"), Duration.ofMinutes(65)));
		assertEquals(t("2026-10-10T02:00:00Z"), BreachSchedule.correct(t("2026-10-10T01:59:30Z"), Duration.ofMinutes(1)));
		// Ten minutes off is a real change.
		assertEquals(t("2026-10-10T02:10:00Z"), BreachSchedule.correct(t("2026-10-10T01:00:00Z"), Duration.ofMinutes(70)));
	}

	@Test
	public void correctionInThePastIsIgnored()
	{
		Instant corr = t("2026-10-09T10:00:00Z");
		assertEquals(new State(Phase.UPCOMING, t("2026-10-10T02:00:00Z")), BreachSchedule.state(t("2026-10-09T23:00:00Z"), corr));
	}
}

package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.time.Duration;
import java.time.Instant;
import org.junit.Test;

public class BuyLimitResetTest
{
	private static final Instant NOW = Instant.parse("2026-10-07T12:00:00Z");

	@Test
	public void keyAndValue()
	{
		assertEquals("buylimit_4151", BuyLimitReset.key(4151));
		// RuneLite's ConfigManager stores an Instant as its ISO text.
		assertEquals(Instant.parse("2026-10-07T14:14:30.123Z"), BuyLimitReset.parse("2026-10-07T14:14:30.123Z"));
		assertEquals(Instant.ofEpochMilli(1791300000000L), BuyLimitReset.parse("1791300000000"));
		assertNull(BuyLimitReset.parse(null));
		assertNull(BuyLimitReset.parse(""));
		assertNull(BuyLimitReset.parse("soon"));
		assertNull(BuyLimitReset.parse("99999999999999999999999"));
	}

	@Test
	public void leftOutWhileRuneLitesGePluginShowsIt()
	{
		Instant in2h14 = NOW.plus(Duration.ofMinutes(134));
		// Defaults (no values saved): the GE plugin is on and shows "Buy limit: N (2:14)" itself.
		assertTrue(BuyLimitReset.coreShowsReset(null, null));
		assertTrue(BuyLimitReset.coreShowsReset("true", "true"));
		assertNull(BuyLimitReset.forGeLine(true, null, null, in2h14, NOW));
		// The GE plugin off, or its reset timer off: the DMM line shows it.
		assertFalse(BuyLimitReset.coreShowsReset("false", null));
		assertFalse(BuyLimitReset.coreShowsReset(null, "false"));
		assertEquals("2h 14m", BuyLimitReset.forGeLine(true, "false", null, in2h14, NOW));
		assertEquals("2h 14m", BuyLimitReset.forGeLine(true, "true", " false ", in2h14, NOW));
		// Never on a sell offer, nor when no reset is coming.
		assertNull(BuyLimitReset.forGeLine(false, "false", "false", in2h14, NOW));
		assertNull(BuyLimitReset.forGeLine(true, "false", "false", NOW.minusSeconds(1), NOW));
	}

	@Test
	public void remainingOnlyWhileInTheFuture()
	{
		assertEquals("2h 14m", BuyLimitReset.remaining(NOW.plus(Duration.ofMinutes(134)).plusSeconds(59), NOW));
		assertEquals("4h 0m", BuyLimitReset.remaining(NOW.plus(Duration.ofHours(4)), NOW));
		assertEquals("14m", BuyLimitReset.remaining(NOW.plus(Duration.ofMinutes(14)), NOW));
		assertEquals("<1m", BuyLimitReset.remaining(NOW.plusSeconds(59), NOW));
		assertNull(BuyLimitReset.remaining(NOW, NOW));
		assertNull(BuyLimitReset.remaining(NOW.minusSeconds(1), NOW));
		assertNull(BuyLimitReset.remaining(null, NOW));
		assertEquals(NOW.plusSeconds(1), BuyLimitReset.future(NOW.plusSeconds(1), NOW));
		assertNull(BuyLimitReset.future(NOW, NOW));
	}
}

