package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.deadmantoolkit.world.WorldEventMessage;
import java.util.Optional;
import org.junit.Test;

public class DevCommandsTest
{
	private static Optional<DevCommands.Action> action(String... args)
	{
		return DevCommands.parse(args).map(DevCommands.Command::getAction);
	}

	private static String gameText(String... args)
	{
		return DevCommands.parse(args).map(DevCommands.Command::getGameText).orElseThrow(AssertionError::new);
	}

	@Test
	public void freshPreview()
	{
		assertEquals(Optional.of(DevCommands.Action.FRESH_ON), action("fresh"));
		assertEquals(Optional.of(DevCommands.Action.FRESH_ON), action("FRESH", "on"));
		assertEquals(Optional.of(DevCommands.Action.FRESH_OFF), action("fresh", "Off"));
	}

	@Test
	public void hints()
	{
		assertEquals(Optional.of(DevCommands.Action.HINTS), action("hints"));
	}

	@Test
	public void worldEvents()
	{
		WorldEventMessage chest = WorldEventMessage.parse(gameText("chest", "north", "of", "the", "Warriors'", "Guild")).get();
		assertEquals(WorldEventMessage.Kind.CHEST, chest.getKind());
		assertEquals("north of the Warriors' Guild", chest.getLocation());

		WorldEventMessage breach = WorldEventMessage.parse(gameText("breach", "the", "Bone", "Yard", "MULTI")).get();
		assertEquals("the Bone Yard", breach.getLocation());
		assertEquals(WorldEventMessage.Combat.MULTI, breach.getCombat());
		// A one-word place that happens to be a combat word is still the place.
		assertEquals("Single", WorldEventMessage.parse(gameText("breach", "Single")).get().getLocation());

		assertEquals(Optional.of(DevCommands.Action.EVENTS_SAMPLE), action("events", "sample"));
		assertEquals(Optional.of(DevCommands.Action.EVENTS_CLEAR), action("events", "CLEAR"));
		for (String s : DevCommands.SAMPLE)
		{
			assertTrue(s, WorldEventMessage.parse(s).isPresent());
		}
	}

	@Test
	public void rejectsAnythingElse()
	{
		assertFalse(action().isPresent());
		assertFalse(DevCommands.parse(null).isPresent());
		assertFalse(action("fresh", "maybe").isPresent());
		assertFalse(action("hints", "now").isPresent());
		assertFalse(action("fresh", "off", "now").isPresent());
		assertFalse(action("breach").isPresent());
		assertFalse(action("chest").isPresent());
		assertFalse(action("events").isPresent());
		assertFalse(action("events", "maybe").isPresent());
	}
}

package com.deadmantoolkit;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BooleanSupplier;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.Buffer;

/**
 * A scripted collection server for tests: an OkHttp interceptor answers each path from a queue of canned replies
 * (default 200). No network. Records every request with its body.
 */
final class FakeServer
{
	static final HttpUrl BASE = HttpUrl.get("http://localhost:1");
	static final String REGISTER = "/v1/register";
	static final String SUBMIT = "/v1/submit";
	static final String ME = "/v1/me";
	private static final MediaType JSON = MediaType.parse("application/json");

	/** A canned reply: an HTTP status and body, or a network failure. */
	static final class Reply
	{
		final int code;
		final String body;
		final boolean ioFailure;
		/** When set, the reply waits for this latch (to keep a request in flight). */
		final CountDownLatch hold;

		private Reply(int code, String body, boolean ioFailure, CountDownLatch hold)
		{
			this.code = code;
			this.body = body;
			this.ioFailure = ioFailure;
			this.hold = hold;
		}
	}

	static Reply status(int code)
	{
		return new Reply(code, "{}", false, null);
	}

	static Reply json(int code, String body)
	{
		return new Reply(code, body, false, null);
	}

	static Reply ioFailure()
	{
		return new Reply(0, null, true, null);
	}

	static Reply heldUntil(CountDownLatch latch)
	{
		return new Reply(200, "{\"ok\":true}", false, latch);
	}

	/** A register response issuing {@code token}. */
	static Reply token(String token)
	{
		return json(200, "{\"installId\":\"x\",\"token\":\"" + token + "\"}");
	}

	/** A token-shaped value (43 characters of base64url) made of {@code c}. */
	static String tok(char c)
	{
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < 43; i++)
		{
			sb.append(c);
		}
		return sb.toString();
	}

	/** A recorded request. */
	static final class Seen
	{
		final Request request;
		final String body;

		Seen(Request request, String body)
		{
			this.request = request;
			this.body = body;
		}

		String path()
		{
			return request.url().encodedPath();
		}

		String auth()
		{
			return request.header("Authorization");
		}

		JsonObject json()
		{
			return new Gson().fromJson(body, JsonObject.class);
		}
	}

	final BlockingQueue<Seen> requests = new LinkedBlockingQueue<>();
	private final Map<String, Deque<Reply>> replies = new HashMap<>();
	private final AtomicInteger tokenSeq = new AtomicInteger();
	/** Runs before each reply is sent, e.g. to flip a setting mid-chain. */
	volatile Runnable beforeReply = () ->
	{
	};

	/** Queue replies for {@code path}, used in order; after they run out, the default applies. */
	synchronized FakeServer on(String path, Reply... rs)
	{
		Deque<Reply> q = replies.computeIfAbsent(path, k -> new ArrayDeque<>());
		for (Reply r : rs)
		{
			q.addLast(r);
		}
		return this;
	}

	private synchronized Reply next(String path)
	{
		Deque<Reply> q = replies.get(path);
		Reply r = q == null ? null : q.pollFirst();
		if (r != null)
		{
			return r;
		}
		// Default: registration issues a new token each time, everything else succeeds.
		if (REGISTER.equals(path))
		{
			return token(tok((char) ('a' + tokenSeq.getAndIncrement() % 26)));
		}
		return json(200, "{\"ok\":true}");
	}

	OkHttpClient client()
	{
		return new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				Request req = chain.request();
				String body = null;
				if (req.body() != null)
				{
					Buffer buf = new Buffer();
					req.body().writeTo(buf);
					body = buf.readUtf8();
				}
				requests.add(new Seen(req, body));
				Reply r = next(req.url().encodedPath());
				if (r.hold != null)
				{
					try
					{
						r.hold.await(10, TimeUnit.SECONDS);
					}
					catch (InterruptedException e)
					{
						Thread.currentThread().interrupt();
					}
				}
				beforeReply.run();
				if (r.ioFailure)
				{
					throw new IOException("fake network failure");
				}
				return new Response.Builder().request(req).protocol(Protocol.HTTP_1_1).code(r.code).message("fake")
					.body(ResponseBody.create(JSON, r.body)).build();
			})
			.build();
	}

	Seen next() throws InterruptedException
	{
		Seen s = requests.poll(5, TimeUnit.SECONDS);
		assertNotNull("expected a request", s);
		return s;
	}

	/** The next request, or null if none arrives within {@code ms}. */
	Seen poll(long ms) throws InterruptedException
	{
		return requests.poll(ms, TimeUnit.MILLISECONDS);
	}

	/** Waits for the uploader's in-flight chain to end. */
	static void awaitIdle(TradeUploader up) throws InterruptedException
	{
		for (int i = 0; i < 500 && up.isInFlight(); i++)
		{
			TimeUnit.MILLISECONDS.sleep(10);
		}
		assertFalse("in-flight flag stuck", up.isInFlight());
	}

	/** Waits until {@code cond} holds (up to 5 s). */
	static boolean await(BooleanSupplier cond) throws InterruptedException
	{
		for (int i = 0; i < 500; i++)
		{
			if (cond.getAsBoolean())
			{
				return true;
			}
			TimeUnit.MILLISECONDS.sleep(10);
		}
		return cond.getAsBoolean();
	}

	/** An identity over an in-memory map, with real random UUIDs. */
	static InstallIdentity identity(Map<String, String> store)
	{
		return new InstallIdentity(new InstallIdentity.Store()
		{
			@Override
			public synchronized String get(String key)
			{
				return store.get(key);
			}

			@Override
			public synchronized void set(String key, String value)
			{
				store.put(key, value);
			}

			@Override
			public synchronized void unset(String key)
			{
				store.remove(key);
			}
		}, () -> UUID.randomUUID().toString());
	}
}

package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.deadmantoolkit.GeHistory.Cell;
import com.deadmantoolkit.GeHistory.Entry;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;

public class GeHistoryTest
{
	private static Cell text(String t)
	{
		return new Cell(t, -1, 0);
	}

	private static Cell item(int id, int qty)
	{
		return new Cell("", id, qty);
	}

	@Test
	public void parsesRows()
	{
		List<Cell> cells = Arrays.asList(
			text(""), text("Bought:"), item(4151, 2), text("Abyssal whip"), text("600,000 coins<br>= 300,000 each"),
			text(""), text("Sold:"), item(385, 500), text("Shark"), text("<col=ffffff>450,000</col> coins")
		);
		List<Entry> rows = GeHistory.parse(cells);
		assertEquals(2, rows.size());
		assertTrue(rows.get(0).isBuy());
		assertEquals(4151, rows.get(0).getItemId());
		assertEquals(2, rows.get(0).getQty());
		assertEquals(600_000, rows.get(0).getTotal());
		assertFalse(rows.get(1).isBuy());
		assertEquals(450_000, rows.get(1).getTotal());
	}

	@Test
	public void toleratesPriceBeforeItem()
	{
		List<Entry> rows = GeHistory.parse(Arrays.asList(text("Sold:"), text("1,000 coins"), item(560, 10)));
		assertEquals(1, rows.size());
		assertEquals(560, rows.get(0).getItemId());
		assertEquals(1000, rows.get(0).getTotal());
	}

	@Test
	public void countNewFirstRead()
	{
		assertEquals(3, GeHistory.countNew(Collections.emptyList(), Arrays.asList("a", "b", "c")));
	}

	@Test
	public void countNewNothingChanged()
	{
		assertEquals(0, GeHistory.countNew(Arrays.asList("a", "b", "c"), Arrays.asList("a", "b", "c")));
	}

	@Test
	public void countNewWithNewRowsOnTop()
	{
		// List is capped, so old rows fall off the bottom as new ones arrive.
		assertEquals(2, GeHistory.countNew(Arrays.asList("a", "b", "c"), Arrays.asList("x", "y", "a")));
	}

	@Test
	public void countNewWithRepeatedIdenticalTrades()
	{
		assertEquals(1, GeHistory.countNew(Arrays.asList("a", "a", "b"), Arrays.asList("a", "a", "a", "b")));
	}

	@Test
	public void countNewWhenEverythingRolledOver()
	{
		List<String> cur = new ArrayList<>(Arrays.asList("p", "q", "r"));
		assertEquals(3, GeHistory.countNew(Arrays.asList("a", "b", "c"), cur));
	}

	@Test
	public void newEventsOldestFirstSkippingLiveRows()
	{
		List<Entry> entries = Arrays.asList(
			new Entry(true, 4151, 3, 1_000_000),
			new Entry(false, 385, 500, 450_000),
			new Entry(true, 560, 10, 1_000),
			new Entry(true, 1, 1, 1)
		);
		AtomicInteger n = new AtomicInteger();
		List<String> asked = new ArrayList<>();
		List<TradeEvent> ev = GeHistory.newEvents(entries, 3, sig ->
		{
			asked.add(sig);
			return sig.equals("sell|385|500|450000");
		}, 777, 345, () -> "hist:" + n.incrementAndGet());

		assertEquals(Arrays.asList("buy|560|10|1000", "sell|385|500|450000", "buy|4151|3|1000000"), asked);
		assertEquals(2, ev.size());

		TradeEvent a = ev.get(0);
		assertEquals("hist:1", a.getId());
		assertEquals(TradeEvent.HISTORY, a.getKind());
		assertEquals("buy", a.getSide());
		assertEquals(560, a.getItemId());
		assertEquals(10, a.getQty());
		assertEquals(100, a.getPrice());
		assertEquals(Long.valueOf(1_000), a.getTotal());
		assertEquals(777, a.getTs());
		assertEquals(345, a.getWorld());
		assertTrue(a.isLate());

		TradeEvent b = ev.get(1);
		assertEquals("hist:2", b.getId());
		assertEquals(4151, b.getItemId());
		// 1,000,000 / 3 rounds to the nearest gp.
		assertEquals(333_333, b.getPrice());
	}

	@Test
	public void newEventsRoundsHalfUp()
	{
		List<TradeEvent> ev = GeHistory.newEvents(Collections.singletonList(new Entry(false, 4151, 2, 5)), 1,
			sig -> false, 1, 345, () -> "hist:x");
		assertEquals("sell", ev.get(0).getSide());
		assertEquals(3, ev.get(0).getPrice());
	}

	@Test
	public void newEventsWithNothingNew()
	{
		assertTrue(GeHistory.newEvents(Collections.singletonList(new Entry(true, 4151, 1, 1)), 0,
			sig -> false, 1, 345, () -> "hist:x").isEmpty());
	}
}

package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.time.Instant;
import net.runelite.client.util.Text;
import org.junit.Test;

public class GePriceTextTest
{
	private static final String M = GePriceText.MARKER;
	private static final String LINE = M + " last 1.25M/1.24M";

	@Test
	public void emptyFeeAppends()
	{
		assertEquals("Examine<br>Buy limit: 100<br>" + LINE, GePriceText.insert("Examine<br>Buy limit: 100", "", LINE));
		assertEquals(LINE, GePriceText.insert("", "", LINE));
	}

	@Test
	public void lineGoesBeforeTheFee()
	{
		String core = "Examine<br>Buy limit: 100<br>Fee text";
		assertEquals("Examine<br>Buy limit: 100<br>" + LINE + "<br>Fee text", GePriceText.insert(core, "Fee text", LINE));
		// The script's own "<br><br>" before the fee survives.
		assertEquals("Examine<br><br>" + LINE + "<br>Fee", GePriceText.insert("Examine<br><br>Fee", "Fee", LINE));
	}

	@Test
	public void feeNotAtTheEndAppends()
	{
		assertEquals("Examine<br>" + LINE, GePriceText.insert("Examine", "Fee", LINE));
	}

	@Test
	public void insertIsIdempotentAndReplaces()
	{
		String once = GePriceText.insert("Examine<br>Limit", "", LINE);
		assertEquals(once, GePriceText.insert(once, "", LINE));
		String other = M + " no trades yet";
		assertEquals("Examine<br>Limit<br>" + other, GePriceText.insert(once, "", other));

		String withFee = GePriceText.insert("Examine<br>Fee", "Fee", LINE);
		assertEquals(withFee, GePriceText.insert(withFee, "Fee", LINE));
	}

	@Test
	public void stripOnlyRemovesOurLine()
	{
		assertEquals("Examine<br><col=ff0000>Other</col><br>Fee",
			GePriceText.strip("Examine<br><col=ff0000>Other</col><br>" + LINE + "<br>Fee"));
		assertEquals("Examine", GePriceText.strip("Examine<br>" + LINE));
		assertEquals("Rest", GePriceText.strip(LINE + "<br>Rest"));
		assertEquals("", GePriceText.strip(LINE));
		assertEquals("No marker here", GePriceText.strip("No marker here"));
	}

	@Test
	public void lineWithMissingValues()
	{
		String l = GePriceText.line(1_250_000L, null, null, 1_260_000L, 523);
		assertTrue(l.startsWith(M + " "));
		assertEquals("DMM last 1.25M/- · bid - ask 1.26M · 523/24h", Text.removeTags(l));
	}

	@Test
	public void noDataAtAll()
	{
		assertEquals(M + " no trades yet", GePriceText.line(null, null, null, null, 0));
		assertEquals(M + " no trades yet", GePriceText.line((MarketData.Summary) null));
	}

	@Test
	public void billionsAreCompact()
	{
		String l = Text.removeTags(GePriceText.line(2_147_000_000L, 2_100_000_000L, 2_000_000_000L, 2_140_000_000L, 12));
		assertTrue(l, l.contains("2.14B/2.1B"));
		assertTrue(l.length() <= GePriceText.MAX_VISIBLE);
	}

	@Test
	public void worstCaseStillFitsWithBidAsk()
	{
		// The widest values each format to five characters ("9,999", "99.9K", "2.14B").
		String l = Text.removeTags(GePriceText.line(9_999L, 99_999L, 2_147_000_000L, 9_998L, 2_147_000_000L));
		assertTrue(l, l.length() <= GePriceText.MAX_VISIBLE);
		assertTrue(l, l.contains(" bid 2.14B ask 9,998"));
	}

	@Test
	public void fromSummary()
	{
		MarketData.Summary s = new Gson().fromJson("{\"lastBuy\":1250000,\"lastSell\":1240000,\"bestBid\":1230000,"
			+ "\"bestAsk\":1260000,\"vol24\":523}", MarketData.Summary.class);
		assertEquals("DMM last 1.25M/1.24M · bid 1.23M ask 1.26M · 523/24h", Text.removeTags(GePriceText.line(s)));
		assertFalse(GePriceText.line(s).contains("<br>"));
	}

	@Test
	public void buyLimitResetJoinsTheLine()
	{
		MarketData.Summary s = new Gson().fromJson("{\"lastBuy\":1250000,\"lastSell\":1240000,\"bestBid\":1230000,"
			+ "\"bestAsk\":1260000,\"vol24\":523}", MarketData.Summary.class);
		// Too long with the bid / ask part, so that goes first.
		assertEquals("DMM last 1.25M/1.24M · 523/24h · limit resets in 2h 14m",
			Text.removeTags(GePriceText.line(s, "2h 14m")));
		assertEquals(Text.removeTags(GePriceText.line(s)), Text.removeTags(GePriceText.line(s, null)));
		// Short values keep everything.
		assertEquals("DMM last 5/6 · bid 4 ask 7 · 3/24h · limit resets in 14m",
			Text.removeTags(GePriceText.line(5L, 6L, 4L, 7L, 3, "14m")));
		assertEquals("DMM no trades yet · limit resets in 3h 59m",
			Text.removeTags(GePriceText.line((MarketData.Summary) null, "3h 59m")));
		// RuneLite's GE plugin shows the reset itself by default: then it is left out and bid / ask stay.
		Instant now = Instant.parse("2026-10-07T12:00:00Z");
		assertEquals("DMM last 1.25M/1.24M · bid 1.23M ask 1.26M · 523/24h", Text.removeTags(GePriceText.line(s,
			BuyLimitReset.forGeLine(true, null, null, now.plusSeconds(134 * 60), now))));
		// The widest values: always within the limit, with the short form if needed.
		for (String left : new String[]{"<1m", "59m", "3h 59m"})
		{
			String l = Text.removeTags(GePriceText.line(2_147_000_000L, 2_100_000_000L, 2_000_000_000L, 2_140_000_000L,
				2_147_000_000L, left));
			assertTrue(l, l.length() <= GePriceText.MAX_VISIBLE);
			assertTrue(l, l.endsWith(left));
		}
	}
}

package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import com.google.gson.Gson;
import java.io.IOException;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Collections;
import java.util.UUID;
import net.runelite.client.util.Filepath;
import org.junit.Assume;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import org.slf4j.LoggerFactory;

/** The install id and token live in a file in the plugin folder, never in the (logged, shared, synced) config. */
public class IdentityFileTest
{
	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	private final Gson gson = new Gson();

	private Filepath dir()
	{
		return Filepath.Unchecked.getRooted(tmp.getRoot().toPath()).joinSegment("deadman-tool-kit");
	}

	private Path file()
	{
		return tmp.getRoot().toPath().resolve("deadman-tool-kit").resolve(IdentityFile.FILE_NAME);
	}

	private InstallIdentity identity()
	{
		return new InstallIdentity(new IdentityFile(this::dir, gson), () -> UUID.randomUUID().toString());
	}

	@Test
	public void tokenAndIdGoToTheFileAndSurviveARestart() throws IOException
	{
		InstallIdentity a = identity();
		String id = a.installId();
		String token = FakeServer.tok('t');
		a.setToken(id, token);
		String text = new String(Files.readAllBytes(file()), StandardCharsets.UTF_8);
		assertTrue(text.contains(id) && text.contains(token));

		InstallIdentity b = identity();
		assertEquals(id, b.installId());
		assertEquals(token, b.token());
		b.clearToken(id);
		assertNull(identity().token());
		assertNotEquals(id, b.rotateInstallId());
		assertNotEquals(id, identity().installId());
	}

	@Test
	public void anUnwritableFolderKeepsTheValuesForTheSession()
	{
		InstallIdentity a = new InstallIdentity(new IdentityFile(() ->
		{
			throw new IOException("read-only");
		}, gson), () -> UUID.randomUUID().toString());
		String id = a.installId();
		assertEquals("the same id all session", id, a.installId());
		a.setToken(id, FakeServer.tok('s'));
		assertEquals(FakeServer.tok('s'), a.token());
	}

	@Test
	public void aFileThatCantBeReadRightNowIsNeverReplaced() throws IOException
	{
		String id = "00000000-0000-0000-0000-0000000000cc";
		Files.createDirectories(file().getParent());
		Files.write(file(), ("{\"installId\":\"" + id + "\",\"installToken\":\"" + FakeServer.tok('u') + "\"}")
			.getBytes(StandardCharsets.UTF_8));
		InstallIdentity a;
		String temp;
		try (FileChannel ch = FileChannel.open(file(), StandardOpenOption.WRITE); FileLock lock = ch.lock())
		{
			boolean blocked;
			try
			{
				Files.readAllBytes(file());
				blocked = false;
			}
			catch (IOException ex)
			{
				blocked = true;
			}
			Assume.assumeTrue("needs a lock that blocks reads (Windows)", blocked);
			a = identity();
			temp = a.installId();
			assertNotEquals(id, temp);
		}
		// Readable again later in the session: the session's values still stay in memory only.
		a.setToken(temp, FakeServer.tok('v'));
		assertEquals(FakeServer.tok('v'), a.token());
		assertEquals("the file still holds this PC's id and key", id, identity().installId());
		assertEquals(FakeServer.tok('u'), identity().token());
	}

	@Test
	public void lostIdsAreKeptInTheFile()
	{
		InstallIdentity a = identity();
		String first = a.installId();
		String second = a.replaceInstallId();
		a.rotateInstallId();
		assertNotEquals(first, second);
		assertEquals(Collections.singletonList(first), identity().lostInstallIds());
	}

	@Test
	public void aCorruptFileIsReplacedAndNothingIsLogged() throws IOException
	{
		Logger root = (Logger) LoggerFactory.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME);
		ListAppender<ILoggingEvent> logs = new ListAppender<>();
		logs.start();
		root.addAppender(logs);
		Level level = root.getLevel();
		root.setLevel(Level.DEBUG);
		try
		{
			Files.createDirectories(file().getParent());
			Files.write(file(), "{not json".getBytes(StandardCharsets.UTF_8));
			InstallIdentity a = identity();
			String id = a.installId();
			String token = FakeServer.tok('c');
			a.setToken(id, token);
			assertEquals(token, identity().token());
			for (ILoggingEvent e : logs.list)
			{
				assertFalse(e.getFormattedMessage().contains(token));
			}
		}
		finally
		{
			root.detachAppender(logs);
			root.setLevel(level);
		}
	}
}

package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import org.junit.Test;

public class ItemQuoteCacheTest
{
	private final Map<Integer, List<Consumer<MarketData.ItemDetail>>> pending = new HashMap<>();
	private final Map<Integer, List<Consumer<String>>> failing = new HashMap<>();
	private int fetches;
	private final ItemQuoteCache cache = new ItemQuoteCache((id, ok, err) ->
	{
		fetches++;
		pending.computeIfAbsent(id, k -> new ArrayList<>()).add(ok);
		failing.computeIfAbsent(id, k -> new ArrayList<>()).add(err);
	});

	private static MarketData.ItemDetail detail(int id)
	{
		return new Gson().fromJson("{\"id\":" + id + ",\"summary\":{\"lastBuy\":5}}", MarketData.ItemDetail.class);
	}

	private void answer(int id)
	{
		List<Consumer<MarketData.ItemDetail>> list = pending.remove(id);
		list.get(list.size() - 1).accept(detail(id));
	}

	@Test
	public void freshHitsDoNotFetch()
	{
		assertNull(cache.request(1, 0, null));
		answer(1);
		assertNotNull(cache.request(1, 1_000, null));
		assertNotNull(cache.request(1, ItemQuoteCache.TTL_MS, null));
		assertEquals(1, fetches);
	}

	@Test
	public void oldEntriesRefetchButStillShow()
	{
		cache.request(1, 0, null);
		answer(1);
		MarketData.ItemDetail first = cache.request(1, ItemQuoteCache.TTL_MS + 1, null);
		// Shown while the refetch runs.
		assertNotNull(first);
		assertEquals(2, fetches);
		// Too old to show at all.
		assertNull(cache.peek(1, ItemQuoteCache.MAX_AGE_MS + 1));
	}

	@Test
	public void concurrentRequestsMakeOneFetchAndAllWaitersRun()
	{
		int[] ready = new int[1];
		cache.request(7, 0, () -> ready[0]++);
		cache.request(7, 10, () -> ready[0]++);
		assertEquals(1, fetches);
		assertEquals(0, ready[0]);
		answer(7);
		assertEquals(2, ready[0]);
		assertNotNull(cache.peek(7, 20));
	}

	@Test
	public void failureBacksOffForTheTtl()
	{
		int[] ready = new int[1];
		cache.request(3, 0, () -> ready[0]++);
		failing.get(3).get(0).accept("down");
		assertEquals(0, ready[0]);
		assertNull(cache.request(3, 1_000, null));
		assertEquals(1, fetches);
		cache.request(3, ItemQuoteCache.TTL_MS, null);
		assertEquals(2, fetches);
	}

	@Test
	public void lruCap()
	{
		for (int id = 0; id <= ItemQuoteCache.MAX_ENTRIES; id++)
		{
			cache.request(id, 0, null);
			answer(id);
		}
		// The first one was evicted; the newest are kept.
		assertNull(cache.peek(0, 1));
		assertNotNull(cache.peek(ItemQuoteCache.MAX_ENTRIES, 1));
	}

	@Test
	public void clearDropsLateResponses()
	{
		int[] ready = new int[1];
		cache.request(9, 0, () -> ready[0]++);
		cache.clear();
		answer(9);
		assertEquals(0, ready[0]);
		assertNull(cache.peek(9, 1));
	}

	@Test
	public void returnsTheStoredDetail()
	{
		cache.request(2, 0, null);
		MarketData.ItemDetail d = detail(2);
		pending.remove(2).get(0).accept(d);
		assertSame(d, cache.peek(2, 1));
	}
}

package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.time.Instant;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class LocalTradeLogTest
{
	private static final YearMonth JAN = YearMonth.of(2026, 1);
	private static final YearMonth FEB = YearMonth.of(2026, 2);
	private static final int[] CHUNKS = {7, ReverseLineReader.DEFAULT_CHUNK};

	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	private final Gson gson = new Gson();

	private Filepath dir()
	{
		return Filepath.Unchecked.getRooted(tmp.getRoot().toPath()).joinSegment("deadman-tool-kit");
	}

	private static TradeEvent ev(String id, long ts)
	{
		return ev(id, TradeEvent.FILL, ts);
	}

	private static TradeEvent ev(String id, String kind, long ts)
	{
		return TradeEvent.builder().id(id).kind(kind).side(TradeEvent.BUY).itemId(4151).qty(1).price(1).ts(ts).world(345).build();
	}

	private List<String> lines(TradeEvent... events)
	{
		List<String> out = new ArrayList<>();
		for (TradeEvent e : events)
		{
			out.add(gson.toJson(DeadmanToolKitPlugin.logLine(gson, e, "acct1")));
		}
		return out;
	}

	private static List<String> ids(List<TradeEvent> events)
	{
		return events.stream().map(TradeEvent::getId).collect(Collectors.toList());
	}

	@Test
	public void monthIsUtc()
	{
		long lastSecondOfJan = Instant.parse("2026-01-31T23:59:59Z").getEpochSecond();
		assertEquals(JAN, LocalTradeLog.monthOf(lastSecondOfJan));
		assertEquals(FEB, LocalTradeLog.monthOf(lastSecondOfJan + 1));
		assertEquals("trades-2026-01.jsonl", LocalTradeLog.fileName(JAN));
		assertEquals("trades-0999-12.jsonl", LocalTradeLog.fileName(YearMonth.of(999, 12)));
	}

	@Test
	public void appendCreatesFolderAndGoesToTheMonthsFile() throws Exception
	{
		Filepath dir = dir();
		assertFalse(dir.exists());
		LocalTradeLog.append(dir, JAN, lines(ev("a", 1)));
		LocalTradeLog.append(dir, FEB, lines(ev("b", 2)));
		LocalTradeLog.append(dir, JAN, lines(ev("c", 3)));
		assertTrue(dir.joinSegment("trades-2026-01.jsonl").exists());
		assertTrue(dir.joinSegment("trades-2026-02.jsonl").exists());
		assertFalse(dir.joinSegment(LogFiles.LEGACY_FILE).exists());

		List<String> seen = new ArrayList<>();
		LocalTradeLog.forEachInFile(dir, "trades-2026-01.jsonl", gson, (o, e) -> seen.add(e.getId()));
		assertEquals(Arrays.asList("a", "c"), seen);
	}

	@Test
	public void readNewestWithoutLogIsEmpty() throws Exception
	{
		assertTrue(LocalTradeLog.readNewest(dir(), gson, 300).isEmpty());
	}

	@Test
	public void readNewestReturnsOldestFirstAcrossFiles() throws Exception
	{
		Filepath dir = dir();
		dir.createDirectories();
		dir.joinSegment(LogFiles.LEGACY_FILE).write(gson.toJson(ev("l1", 1)) + "\n" + gson.toJson(ev("l2", 2)) + "\n");
		LocalTradeLog.append(dir, JAN, lines(ev("j1", 10), ev("j2", 11)));
		LocalTradeLog.append(dir, FEB, lines(ev("f1", 20)));
		for (int chunk : CHUNKS)
		{
			assertEquals(Arrays.asList("l1", "l2", "j1", "j2", "f1"), ids(LocalTradeLog.readNewest(dir, gson, 300, chunk)));
			assertEquals(Arrays.asList("j2", "f1"), ids(LocalTradeLog.readNewest(dir, gson, 2, chunk)));
		}
	}

	@Test
	public void legacyOnly() throws Exception
	{
		Filepath dir = dir();
		dir.createDirectories();
		dir.joinSegment(LogFiles.LEGACY_FILE).write(gson.toJson(ev("a", 1)) + "\n" + gson.toJson(ev("b", 2)) + "\n");
		assertEquals(Arrays.asList("a", "b"), ids(LocalTradeLog.readNewest(dir, gson, 300)));
	}

	@Test
	public void readNewestStopsBeforeOlderFiles() throws Exception
	{
		Filepath dir = dir();
		dir.createDirectories();
		// The oldest file starts with a corrupt line; it must not matter (or be reached) when newer files suffice.
		dir.joinSegment(LogFiles.LEGACY_FILE).write("not json {\n" + gson.toJson(ev("old", 1)) + "\n");
		LocalTradeLog.append(dir, JAN, lines(ev("j1", 10), ev("j2", 11)));
		assertEquals(Arrays.asList("j1", "j2"), ids(LocalTradeLog.readNewest(dir, gson, 2)));
		assertEquals(Arrays.asList("old", "j1", "j2"), ids(LocalTradeLog.readNewest(dir, gson, 3)));
	}

	@Test
	public void placedEventsAreSkippedAndNotCounted() throws Exception
	{
		Filepath dir = dir();
		LocalTradeLog.append(dir, JAN, lines(ev("f1", 1), ev("p1", TradeEvent.PLACED, 2), ev("f2", 3),
