			+ "\"lastBuyTime\":20,\"vol24\":5,\"bestAsk\":12},\"trades\":[{\"kind\":\"history\",\"side\":\"buy\",\"qty\":1,"
			+ "\"price\":10,\"ts\":30,\"late\":true}],\"book\":{\"bids\":[{\"price\":9,\"offers\":2,\"qty\":100}]}}",
