	@Test
	public void trustFieldsAreNullOnOlderServers()
	{
		MarketData.Summary s = gson.fromJson("{\"lastBuy\":10,\"vol24\":5}", MarketData.Summary.class);
		assertNull(s.getTrustedPrice());
		assertNull(s.getTrustedVotes());
