package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import com.deadmantoolkit.OfferWatch.Flag;
import com.deadmantoolkit.OfferWatch.OfferStatus;
import com.deadmantoolkit.OfferWatch.Quote;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class OfferWatchTest
{
	private static final int BONES = 536;
	private static final long PLACED = 1_000_000;
	private static final long NOW = PLACED + 3600;
	private static final long STALE = 6 * 3600;

	private static ActiveOffer sell(int slot, String key, long price)
	{
		return new ActiveOffer(slot, key, BONES, "Dragon bones", false, price, 100, 40, PLACED);
	}

	private static ActiveOffer buy(int slot, String key, long price)
	{
		return new ActiveOffer(slot, key, BONES, "Dragon bones", true, price, 100, 0, PLACED);
	}

	private static Quote quote(Long bid, Long ask, Long lastBuy, Long lastBuyTime, Long lastSell, Long lastSellTime)
	{
		return new Quote(bid, ask, lastBuy, lastBuyTime, lastSell, lastSellTime);
	}

	private static OfferStatus one(ActiveOffer o, Quote q)
	{
		return one(o, q, Collections.emptyList(), NOW);
	}

	private static OfferStatus one(ActiveOffer o, Quote q, List<TradeEvent> trades, long now)
	{
		Map<Integer, Quote> quotes = q == null ? Collections.emptyMap() : Collections.singletonMap(BONES, q);
		return OfferWatch.evaluate(Collections.singletonList(o), quotes, trades, now, STALE).get(o.getSlot());
	}

	private static TradeEvent fill(String key, boolean buy, long price, long ts)
	{
		return TradeEvent.builder().kind(TradeEvent.FILL).side(buy ? TradeEvent.BUY : TradeEvent.SELL).itemId(BONES)
			.qty(1).price(price).offerKey(key).ts(ts).build();
	}

	@Test
	public void sellUndercutByLowerAsk()
	{
		OfferStatus s = one(sell(0, "a", 1_250_000), quote(null, 1_240_000L, null, null, null, null));
		assertEquals(Flag.UNDERCUT, s.getFlag());
		assertEquals(Long.valueOf(1_240_000), s.getCompeting());
		assertEquals("a", s.getOfferKey());
	}

	@Test
	public void sellUndercutByFillAfterListing()
	{
		OfferStatus s = one(sell(0, "a", 1_250_000), quote(null, null, null, null, 1_200_000L, PLACED + 60));
		assertEquals(Flag.UNDERCUT, s.getFlag());
		assertEquals(Long.valueOf(1_200_000), s.getCompeting());
	}

	@Test
	public void fillBeforeListingIsIgnored()
	{
		assertEquals(Flag.OK, one(sell(0, "a", 1_250_000), quote(null, null, null, null, 1_200_000L, PLACED - 1)).getFlag());
		assertEquals(Flag.OK, one(sell(0, "a", 1_250_000), quote(null, null, null, null, 1_200_000L, PLACED)).getFlag());
	}

	@Test
	public void equalPriceIsNotFlagged()
	{
		assertEquals(Flag.OK, one(sell(0, "a", 1_250_000), quote(null, 1_250_000L, null, null, 1_250_000L, NOW)).getFlag());
		assertEquals(Flag.OK, one(buy(0, "b", 1_250_000), quote(1_250_000L, null, 1_250_000L, NOW, null, null)).getFlag());
	}

	@Test
	public void myOtherOfferAtTheBestPriceIsIgnored()
	{
		ActiveOffer high = sell(0, "a", 1_250_000);
		ActiveOffer low = sell(1, "b", 1_200_000);
		Map<Integer, OfferStatus> out = OfferWatch.evaluate(Arrays.asList(high, low),
			Collections.singletonMap(BONES, quote(null, 1_200_000L, null, null, null, null)), Collections.emptyList(), NOW, STALE);
		assertEquals(Flag.OK, out.get(0).getFlag());
		assertEquals(Flag.OK, out.get(1).getFlag());
	}

	@Test
	public void myOwnFillAfterListingIsIgnored()
	{
		List<TradeEvent> mine = Collections.singletonList(fill("other", false, 1_210_000, PLACED + 30));
		assertEquals(Flag.OK, one(sell(0, "a", 1_250_000), quote(null, null, null, null, 1_210_000L, PLACED + 30), mine, NOW).getFlag());
		// An older fill of mine at that price doesn't hide a newer trade by someone else.
		List<TradeEvent> old = Collections.singletonList(fill("other", false, 1_210_000, PLACED - 100));
		assertEquals(Flag.UNDERCUT, one(sell(0, "a", 1_250_000), quote(null, null, null, null, 1_210_000L, PLACED + 30), old, NOW).getFlag());
	}

	@Test
	public void buyOutbidByHigherBid()
	{
		OfferStatus s = one(buy(0, "b", 1_000), quote(1_100L, null, null, null, null, null));
		assertEquals(Flag.OUTBID, s.getFlag());
		assertEquals(Long.valueOf(1_100), s.getCompeting());
	}

	@Test
	public void buyOutbidByFillAboveAfterBidding()
	{
		assertEquals(Flag.OUTBID, one(buy(0, "b", 1_000), quote(null, null, 1_050L, PLACED + 5, null, null)).getFlag());
		assertEquals(Flag.OK, one(buy(0, "b", 1_000), quote(null, null, 1_050L, PLACED - 5, null, null)).getFlag());
	}

	@Test
	public void staleAfterThreshold()
	{
		ActiveOffer o = sell(0, "a", 1_000);
		Quote q = quote(null, null, null, null, null, null);
		assertEquals(Flag.OK, one(o, q, Collections.emptyList(), PLACED + STALE).getFlag());
		OfferStatus s = one(o, q, Collections.emptyList(), PLACED + STALE + 1);
		assertEquals(Flag.STALE, s.getFlag());
		assertEquals(STALE + 1, s.getIdleSecs());
		// A recent fill of this offer resets the clock.
		assertEquals(Flag.OK, one(o, q, Collections.singletonList(fill("a", false, 1_000, PLACED + STALE)), PLACED + STALE + 1).getFlag());
	}

	@Test
	public void undercutWinsOverStale()
	{
		OfferStatus s = one(sell(0, "a", 1_000), quote(null, 900L, null, null, null, null), Collections.emptyList(), PLACED + STALE * 2);
		assertEquals(Flag.UNDERCUT, s.getFlag());
	}

	@Test
	public void missingQuoteIsOk()
	{
		OfferStatus s = one(sell(0, "a", 1_000), null);
		assertEquals(Flag.OK, s.getFlag());
		assertEquals("No market data", s.getDetail());
		assertNull(s.getCompeting());
	}

	@Test
	public void unknownPlacementNeverStaleNorFillChecked()
	{
		ActiveOffer o = new ActiveOffer(0, "a", BONES, "Dragon bones", false, 1_000, 10, 0, 0);
		OfferStatus s = OfferWatch.evaluate(Collections.singletonList(o),
			Collections.singletonMap(BONES, quote(null, null, null, null, 900L, NOW)), Collections.emptyList(), NOW, STALE).get(0);
		assertEquals(Flag.OK, s.getFlag());
		assertEquals(-1, s.getIdleSecs());
	}

	@Test
	public void alertMessage()
	{
		ActiveOffer o = sell(0, "a", 1_250_000);
		OfferStatus s = one(o, quote(null, 1_240_000L, null, null, null, null));
		assertEquals("Deadman Tool Kit: your Dragon bones sell offer (1,250,000) was undercut at 1,240,000.",
			OfferWatch.alertMessage(o, s));
		OfferStatus b = one(buy(0, "b", 20_000_000), quote(21_000_000L, null, null, null, null, null));
		assertEquals("Deadman Tool Kit: your Dragon bones buy offer (20M) was outbid at 21M.",
			OfferWatch.alertMessage(buy(0, "b", 20_000_000), b));
		assertNull(OfferWatch.alertMessage(o, one(o, null)));
	}

	@Test
	public void gePriceHistoryImportedLaterIsNoUndercut()
	{
		com.google.gson.Gson gson = new com.google.gson.Gson();
		// The batch summary's last sell is a 3-week-old GE History row uploaded (ts = import time) after you listed.
		MarketData.ItemSummary batch = gson.fromJson("{\"id\":536,\"lastSell\":1100000,\"lastSellTime\":" + (PLACED + 1800) + "}",
			MarketData.ItemSummary.class);
		assertEquals(Flag.OK, one(sell(0, "a", 1_250_000), Quote.of(batch)).getFlag());

		// The item detail: only its live fills count.
		MarketData.Summary sum = gson.fromJson("{\"lastSell\":1100000,\"lastSellTime\":" + (PLACED + 1800) + "}",
			MarketData.Summary.class);
		List<MarketData.Trade> history = Arrays.asList(gson.fromJson(
			"{\"kind\":\"history\",\"side\":\"sell\",\"qty\":1,\"price\":1100000,\"ts\":" + (PLACED + 1800) + "}",
			MarketData.Trade.class), gson.fromJson(
			"{\"kind\":\"fill\",\"side\":\"sell\",\"qty\":1,\"price\":1000000,\"ts\":" + (PLACED + 1700) + ",\"late\":true}",
			MarketData.Trade.class));
		assertEquals(Flag.OK, one(sell(0, "a", 1_250_000), Quote.of(sum, history)).getFlag());

		List<MarketData.Trade> live = Arrays.asList(gson.fromJson(
			"{\"kind\":\"fill\",\"side\":\"sell\",\"qty\":1,\"price\":1200000,\"ts\":" + (PLACED + 60) + "}",
			MarketData.Trade.class), history.get(0));
		OfferStatus s = one(sell(0, "a", 1_250_000), Quote.of(sum, live));
		assertEquals(Flag.UNDERCUT, s.getFlag());
		assertEquals(Long.valueOf(1_200_000), s.getCompeting());
	}

	@Test
	public void quotesPreferTheTrustedBook()
	{
		com.google.gson.Gson gson = new com.google.gson.Gson();
		MarketData.ItemSummary both = gson.fromJson("{\"id\":536,\"bestBid\":2000000000,\"bestAsk\":1,"
			+ "\"trustedBestBid\":1240000,\"trustedBestAsk\":1260000}", MarketData.ItemSummary.class);
		Quote q = Quote.of(both);
		assertEquals(Long.valueOf(1_240_000), q.getBestBid());
		assertEquals(Long.valueOf(1_260_000), q.getBestAsk());
		// A fake 1 gp ask doesn't undercut a 1.25M sell offer when the trusted book is known.
		assertEquals(Flag.OK, one(sell(0, "a", 1_250_000), Quote.of(gson.fromJson("{\"id\":536,\"bestAsk\":1,"
			+ "\"trustedBestAsk\":1300000}", MarketData.ItemSummary.class))).getFlag());

		// Older servers (or no trusted offers yet): the raw book.
		Quote raw = Quote.of(gson.fromJson("{\"id\":536,\"bestBid\":5,\"bestAsk\":6}", MarketData.ItemSummary.class));
		assertEquals(Long.valueOf(5), raw.getBestBid());
		assertEquals(Long.valueOf(6), raw.getBestAsk());

		MarketData.Summary s = gson.fromJson("{\"bestBid\":5,\"bestAsk\":6,\"trustedBestAsk\":7}", MarketData.Summary.class);
		Quote detail = Quote.of(s, Collections.emptyList());
		assertEquals(Long.valueOf(5), detail.getBestBid());
		assertEquals(Long.valueOf(7), detail.getBestAsk());
	}
}

package com.deadmantoolkit;

import static com.deadmantoolkit.Onboarding.Step.CONNECT;
import static com.deadmantoolkit.Onboarding.Step.CONNECT_AND_IMPORT;
import static com.deadmantoolkit.Onboarding.Step.HIDDEN;
import static com.deadmantoolkit.Onboarding.Step.IMPORT;
import static com.deadmantoolkit.Onboarding.Step.IMPORTED_NOTICE;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class OnboardingTest
{
	@Test
	public void loggedIn()
	{
		assertEquals(CONNECT_AND_IMPORT, Onboarding.state(false, false, null));
		assertEquals(CONNECT, Onboarding.state(false, true, null));
		assertEquals(IMPORT, Onboarding.state(true, false, null));
		assertEquals(HIDDEN, Onboarding.state(true, true, null));
	}

	@Test
	public void notLoggedIn()
	{
		// Unknown import state: the steps (with "log in first") only ride along with the connect block.
		assertEquals(CONNECT_AND_IMPORT, Onboarding.state(false, null, null));
		assertEquals(HIDDEN, Onboarding.state(true, null, null));
		assertTrue(Onboarding.needsLogin(null));
		assertFalse(Onboarding.needsLogin(false));
		assertFalse(Onboarding.needsLogin(true));
	}

	@Test
	public void importNotice()
	{
		assertEquals(IMPORTED_NOTICE, Onboarding.state(true, true, 12));
		assertEquals(IMPORTED_NOTICE, Onboarding.state(true, true, 0));
		// Still not connected: the connect block stays (the card adds the notice line to it).
		assertEquals(CONNECT, Onboarding.state(false, true, 12));
	}

	@Test
	public void chatHint()
	{
		assertTrue(Onboarding.shouldShowChatHint(false, false));
		assertTrue(Onboarding.shouldShowChatHint(false, true));
		assertTrue(Onboarding.shouldShowChatHint(true, false));
		assertFalse(Onboarding.shouldShowChatHint(true, true));
	}
}

package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZoneOffset;
import org.junit.Test;

public class ProfitBookTest
{
	private static final ZoneId UTC = ZoneOffset.UTC;
	private static final int ITEM = 536;
	/** 2026-03-10T12:00Z */
	private static final long T0 = Instant.parse("2026-03-10T12:00:00Z").getEpochSecond();

	static TradeEvent fill(String side, int qty, long price, long ts)
	{
		return trade(TradeEvent.FILL, ITEM, side, qty, price, ts);
	}

	static TradeEvent trade(String kind, int item, String side, int qty, long price, long ts)
	{
		return TradeEvent.builder().id(kind + side + qty + "@" + price + "/" + ts).kind(kind).side(side).itemId(item)
			.qty(qty).price(price).total(price * qty).ts(ts).world(345).name("Dragon bones").build();
	}

	@Test
	public void buyThenSellRealizesAgainstAverageCost()
	{
		ProfitBook b = new ProfitBook();
		assertTrue(b.apply(fill(TradeEvent.BUY, 10, 100, T0), UTC));
		assertTrue(b.apply(fill(TradeEvent.SELL, 4, 150, T0), UTC));
		ProfitBook.Position p = b.position(ITEM);
		assertEquals(200, p.realized);
		assertEquals(6, p.held);
		assertEquals(600, p.basis);
		assertEquals(200, b.getAllTime());

		ProfitSnapshot s = b.snapshot(LocalDate.of(2026, 3, 10), false, true);
		assertEquals(100, s.item(ITEM).getAvgCost());
		assertEquals(200, s.today(LocalDate.of(2026, 3, 10)));
		assertEquals("Dragon bones", s.item(ITEM).getName());
	}

	@Test
	public void movingAverageAfterAnotherBuy()
	{
		ProfitBook b = new ProfitBook();
		b.apply(fill(TradeEvent.BUY, 10, 100, T0), UTC);
		b.apply(fill(TradeEvent.SELL, 4, 150, T0), UTC);
		b.apply(fill(TradeEvent.BUY, 6, 200, T0), UTC);
		assertEquals(150, b.snapshot(LocalDate.of(2026, 3, 10), false, false).item(ITEM).getAvgCost());
		// Selling everything at 150 breaks even on the moving average.
		b.apply(fill(TradeEvent.SELL, 12, 150, T0), UTC);
		ProfitBook.Position p = b.position(ITEM);
		assertEquals(0, p.held);
		assertEquals(0, p.basis);
		assertEquals(200, p.realized);
	}

	@Test
	public void sellBeyondHeldSplitsOffUnknownBasis()
	{
		ProfitBook b = new ProfitBook();
		b.apply(fill(TradeEvent.BUY, 2, 100, T0), UTC);
		b.apply(fill(TradeEvent.SELL, 5, 120, T0), UTC);
		ProfitBook.Position p = b.position(ITEM);
		assertEquals(40, p.realized);
		assertEquals(0, p.held);
		assertEquals(3, p.unknownQty);
		assertEquals(360, p.unknownProceeds);
		assertEquals(360, b.getUnknownProceeds());
		assertEquals(40, b.getAllTime());
	}

	@Test
	public void sellWithNoBuysIsAllUnknownNotProfit()
	{
		ProfitBook b = new ProfitBook();
		b.apply(fill(TradeEvent.SELL, 5, 1_000, T0), UTC);
		assertEquals(0, b.getAllTime());
		assertEquals(5_000, b.getUnknownProceeds());
		assertTrue(b.daily().isEmpty());
		ProfitSnapshot s = b.snapshot(LocalDate.of(2026, 3, 10), false, false);
		assertTrue(s.hasData());
		assertTrue(s.getTop().isEmpty());
		assertEquals(5_000, s.item(ITEM).getUnknownProceeds());
	}

	@Test
	public void historyRowsCountSeparatelyToo()
	{
		ProfitBook b = new ProfitBook();
		b.apply(trade(TradeEvent.HISTORY, ITEM, TradeEvent.BUY, 10, 100, T0), UTC);
		b.apply(trade(TradeEvent.HISTORY, ITEM, TradeEvent.SELL, 10, 130, T0), UTC);
		b.apply(fill(TradeEvent.BUY, 1, 100, T0), UTC);
		b.apply(fill(TradeEvent.SELL, 1, 110, T0), UTC);
		assertEquals(310, b.getAllTime());
		assertEquals(300, b.getHistoryAllTime());
		assertEquals(300, b.position(ITEM).historyRealized);
		assertEquals(310, b.position(ITEM).realized);
	}

	@Test
	public void placedAndCancelledAreIgnored()
	{
		ProfitBook b = new ProfitBook();
		assertFalse(b.apply(trade(TradeEvent.PLACED, ITEM, TradeEvent.BUY, 10, 100, T0), UTC));
		assertFalse(b.apply(trade(TradeEvent.CANCELLED, ITEM, TradeEvent.SELL, 10, 100, T0), UTC));
		assertTrue(b.isEmpty());
		assertNull(b.position(ITEM));
	}

	@Test
	public void totalMissingFallsBackToPriceTimesQty()
	{
		ProfitBook b = new ProfitBook();
		b.apply(fill(TradeEvent.BUY, 3, 10, T0).toBuilder().total(null).build(), UTC);
		assertEquals(30, b.position(ITEM).basis);
	}

	@Test
	public void dailyBucketsUseTheZoneAndSevenDayWindow()
	{
		ZoneId ny = ZoneId.of("America/New_York");
		ProfitBook b = new ProfitBook();
		b.apply(fill(TradeEvent.BUY, 100, 100, T0), ny);
		// 2026-03-17T03:00Z is still the 16th in New York.
		long lateEvening = Instant.parse("2026-03-17T03:00:00Z").getEpochSecond();
		b.apply(fill(TradeEvent.SELL, 1, 110, lateEvening), ny);
		long sixDaysBefore = Instant.parse("2026-03-10T16:00:00Z").getEpochSecond();
		b.apply(fill(TradeEvent.SELL, 1, 120, sixDaysBefore), ny);
		long sevenDaysBefore = Instant.parse("2026-03-09T16:00:00Z").getEpochSecond();
		b.apply(fill(TradeEvent.SELL, 1, 140, sevenDaysBefore), ny);

		assertEquals(Long.valueOf(10), b.daily().get("2026-03-16"));
		LocalDate today = LocalDate.of(2026, 3, 16);
		ProfitSnapshot s = b.snapshot(today, false, false);
		assertEquals(10, s.today(today));
		assertEquals(30, s.last7(today));
		assertEquals(70, s.getAllTime());
		// The snapshot only keeps what the 7-day window can still need.
		assertFalse(s.getRecentDaily().containsKey("2026-03-09"));
		// A later day: nothing today, the 7-day window has moved on.
		assertEquals(0, s.today(today.plusDays(1)));
		assertEquals(10, s.last7(today.plusDays(1)));
	}

	@Test
	public void dailyIsPruned()
	{
		ProfitBook b = new ProfitBook();
		b.apply(fill(TradeEvent.BUY, 1_000, 1, T0), UTC);
		for (int d = 0; d < ProfitBook.DAILY_DAYS + 50; d++)
		{
			b.apply(fill(TradeEvent.SELL, 1, 2, T0 + d * 86_400L), UTC);
		}
		assertTrue(b.daily().size() <= ProfitBook.DAILY_DAYS + 1);
		assertEquals(LocalDate.of(2026, 3, 10).plusDays(ProfitBook.DAILY_DAYS + 49).toString(),
			b.daily().keySet().stream().reduce((x, y) -> y).get());
		// All time still counts every day.
		assertEquals(ProfitBook.DAILY_DAYS + 50, b.getAllTime());
	}

	@Test
	public void billionsDontOverflow()
	{
		ProfitBook b = new ProfitBook();
		long price = 2_000_000_000L;
		b.apply(fill(TradeEvent.BUY, 1_000, price, T0), UTC);
		b.apply(fill(TradeEvent.BUY, 1_000, price, T0), UTC);
		b.apply(fill(TradeEvent.SELL, 999, price + 1, T0), UTC);
		ProfitBook.Position p = b.position(ITEM);
		assertEquals(999, p.realized);
		assertEquals(1_001, p.held);
		assertEquals(1_001 * price, p.basis);
		assertEquals(price, b.snapshot(LocalDate.of(2026, 3, 10), false, false).item(ITEM).getAvgCost());
	}

	@Test
	public void mulDivRoundsAndSurvivesOverflow()
	{
		assertEquals(3, ProfitBook.mulDiv(10, 1, 3));
		assertEquals(7, ProfitBook.mulDiv(20, 1, 3));
		assertEquals(Long.MAX_VALUE / 2, ProfitBook.mulDiv(Long.MAX_VALUE / 2, 1_000_000, 1_000_000));
		assertEquals(4_611_686_018_427_387_904L, ProfitBook.mulDiv(Long.MAX_VALUE, 3, 6));
	}

	@Test
	public void topItemsBestFirst()
	{
		ProfitBook b = new ProfitBook();
		for (int item = 1; item <= 7; item++)
		{
			b.apply(trade(TradeEvent.FILL, item, TradeEvent.BUY, 1, 100, T0), UTC);
			b.apply(trade(TradeEvent.FILL, item, TradeEvent.SELL, 1, 100 + item * 10, T0), UTC);
		}
		ProfitSnapshot s = b.snapshot(LocalDate.of(2026, 3, 10), false, false);
		assertEquals(ProfitBook.TOP, s.getTop().size());
		assertEquals(7, s.getTop().get(0).getItemId());
		assertEquals(70, s.getTop().get(0).getRealized());
		assertEquals(3, s.getTop().get(4).getItemId());
	}

	@Test
	public void jsonRoundTrip()
	{
		Gson gson = new Gson();
		ProfitBook b = new ProfitBook();
		b.apply(fill(TradeEvent.BUY, 10, 100, T0), UTC);
		b.apply(fill(TradeEvent.SELL, 4, 150, T0), UTC);
		b.apply(trade(TradeEvent.HISTORY, 4151, TradeEvent.SELL, 1, 2_000_000, T0), UTC);
		ProfitBook back = gson.fromJson(gson.toJson(b), ProfitBook.class).sanitized();
		assertTrue(back.sameAs(b));
		assertEquals("Dragon bones", back.position(ITEM).name);

		// A damaged or older file without some fields still loads.
		ProfitBook partial = gson.fromJson("{\"allTime\":5}", ProfitBook.class).sanitized();
		assertEquals(5, partial.getAllTime());
		assertTrue(partial.isEmpty());
		assertTrue(partial.apply(fill(TradeEvent.BUY, 1, 1, T0), UTC));
		ProfitBook nulls = gson.fromJson("{\"items\":null,\"daily\":null}", ProfitBook.class).sanitized();
		assertTrue(nulls.apply(fill(TradeEvent.SELL, 1, 1, T0), UTC));
	}
}

package com.deadmantoolkit;

import static com.deadmantoolkit.ProfitBookTest.trade;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.nio.charset.StandardCharsets;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import net.runelite.client.util.Filepath;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class ProfitStoreTest
{
	private static final String A = AccountId.of(1L);
	private static final String B = AccountId.of(2L);
	private static final Clock CLOCK = Clock.fixed(Instant.parse("2026-03-20T12:00:00Z"), ZoneOffset.UTC);
	private static final long JAN = Instant.parse("2026-01-15T12:00:00Z").getEpochSecond();
	private static final long FEB = Instant.parse("2026-02-15T12:00:00Z").getEpochSecond();
	private static final long APR = Instant.parse("2026-04-01T00:00:01Z").getEpochSecond();

	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	private final Gson gson = new Gson();
	private final List<ProfitSnapshot> published = new CopyOnWriteArrayList<>();
	private ScheduledExecutorService executor;

	@Before
	public void setUp()
	{
		executor = Executors.newSingleThreadScheduledExecutor();
	}

	@After
	public void tearDown()
	{
		executor.shutdownNow();
	}

	private Filepath dir()
	{
		return Filepath.Unchecked.getRooted(tmp.getRoot().toPath()).joinSegment("deadman-tool-kit");
	}

	private ProfitStore store()
	{
		return new ProfitStore(this::dir, gson, executor, CLOCK, published::add);
	}

	/** Run {@code r} on the executor and wait for it (and everything queued before it). */
	private void on(Runnable r) throws Exception
	{
		executor.submit(r).get(10, TimeUnit.SECONDS);
	}

	private void awaitRebuild(ProfitStore s) throws Exception
	{
		for (int i = 0; i < 1_000; i++)
		{
			if (!executor.submit(s::isRebuilding).get(10, TimeUnit.SECONDS))
			{
				return;
			}
		}
		throw new AssertionError("rebuild never finished");
	}

	private static TradeEvent buy(int qty, long price, long ts)
	{
		return trade(TradeEvent.FILL, 536, TradeEvent.BUY, qty, price, ts);
	}

	private static TradeEvent sell(int qty, long price, long ts)
	{
		return trade(TradeEvent.FILL, 536, TradeEvent.SELL, qty, price, ts);
	}

	private void log(String acct, TradeEvent... events) throws Exception
	{
		List<String> lines = new ArrayList<>();
		for (TradeEvent e : events)
		{
			lines.add(gson.toJson(DeadmanToolKitPlugin.logLine(gson, e, acct)));
		}
		LocalTradeLog.append(dir(), LocalTradeLog.monthOf(events[0].getTs()), lines);
	}

	private void legacy(TradeEvent... events) throws Exception
	{
		StringBuilder sb = new StringBuilder();
		for (TradeEvent e : events)
		{
			sb.append(gson.toJson(e)).append('\n');
		}
		Filepath d = dir();
		d.createDirectories();
		d.joinSegment(LogFiles.LEGACY_FILE).write(sb.toString().getBytes(StandardCharsets.UTF_8));
	}

	private static ProfitBook live(TradeEvent... events)
	{
		ProfitBook b = new ProfitBook();
		for (TradeEvent e : events)
		{
			b.apply(e, ZoneOffset.UTC);
		}
		return b;
	}

	@Test
	public void fileNameIsFromTheHashOnly()
	{
		assertEquals("profit-" + A.substring(0, 16) + ".json", ProfitStore.fileName(A));
		assertNull(ProfitStore.fileName("Zezima"));
		assertNull(ProfitStore.fileName("../../x"));
		assertNull(ProfitStore.fileName(null));
		assertNull(ProfitStore.fileName("abc"));
	}

	@Test
	public void savesAndLoadsPerAccount() throws Exception
	{
		ProfitStore s = store();
		on(() -> s.load(A));
		on(() -> s.apply(A, Arrays.asList(buy(10, 100, JAN), sell(4, 150, JAN)), false));
		assertEquals(200, published.get(published.size() - 1).getAllTime());
		// Switching account saves the old one first.
		on(() -> s.load(B));
		assertTrue(dir().joinSegment(ProfitStore.fileName(A)).isFile());
		assertEquals(0, published.get(published.size() - 1).getAllTime());
		on(() -> s.apply(B, Collections.singletonList(sell(1, 5, JAN)), false));
		on(s::close);
		assertTrue(dir().joinSegment(ProfitStore.fileName(B)).isFile());
		// A closed store ignores late events.
		int count = published.size();
		on(() -> s.apply(B, Collections.singletonList(sell(1, 5, JAN)), false));
		assertEquals(count, published.size());

		ProfitStore again = store();
		on(() -> again.load(A));
		assertTrue(again.book().sameAs(live(buy(10, 100, JAN), sell(4, 150, JAN))));
		on(() -> again.load(B));
		assertEquals(5, again.book().getUnknownProceeds());
	}

	@Test
	public void applyToAnotherAccountSwitchesFirst() throws Exception
	{
		ProfitStore s = store();
		on(() -> s.load(A));
		on(() -> s.apply(B, Collections.singletonList(buy(1, 1, JAN)), false));
		on(() -> s.apply(null, Collections.singletonList(sell(1, 3, JAN)), false));
		on(() -> s.load(A));
		assertTrue(s.book().isEmpty());
		on(() -> s.load(B));
		assertEquals(2, s.book().getAllTime());
	}

	@Test
	public void debouncedSaveWritesTheFile() throws Exception
	{
		ProfitStore s = store();
		on(() -> s.load(A));
		on(() -> s.apply(A, Collections.singletonList(buy(1, 1, JAN)), false));
		assertFalse(dir().joinSegment(ProfitStore.fileName(A)).exists());
		on(s::saveNow);
		assertTrue(dir().joinSegment(ProfitStore.fileName(A)).isFile());
	}

	@Test
	public void damagedFileStartsFromZero() throws Exception
	{
		Filepath d = dir();
		d.createDirectories();
		d.joinSegment(ProfitStore.fileName(A)).write("{not json".getBytes(StandardCharsets.UTF_8));
		ProfitStore s = store();
		on(() -> s.load(A));
		assertTrue(s.book().isEmpty());
		assertFalse(published.isEmpty());
	}

	@Test
	public void rebuildFiltersOtherAccountsAndIncludesLegacy() throws Exception
	{
		TradeEvent l1 = buy(10, 100, JAN - 86_400 * 60);
		legacy(l1);
		TradeEvent a1 = sell(4, 150, JAN), a2 = buy(6, 200, FEB), a3 = sell(12, 160, FEB);
		TradeEvent b1 = sell(100, 1_000, JAN);
		log(A, a1);
		log(B, b1);
		log(A, a2, a3);

		ProfitStore s = store();
		on(() -> s.load(A));
		on(s::rebuild);
		awaitRebuild(s);
		assertTrue(s.book().sameAs(live(l1, a1, a2, a3)));
		assertTrue(dir().joinSegment(ProfitStore.fileName(A)).isFile());
		ProfitSnapshot last = published.get(published.size() - 1);
		assertFalse(last.isRebuilding());
		assertTrue(last.isLogAvailable());
		assertTrue(published.stream().anyMatch(ProfitSnapshot::isRebuilding));
	}

	@Test
	public void rebuildCountsEventsRecordedWhileItRunsOnce() throws Exception
	{
		TradeEvent l1 = buy(10, 100, JAN - 86_400 * 60);
		legacy(l1);
		TradeEvent a1 = sell(2, 150, JAN), a2 = buy(4, 120, FEB);
		log(A, a1);
		log(A, a2);
		ProfitStore s = store();
		on(() -> s.load(A));
		// Count what's already logged live too, so the store starts with the same numbers.
		on(() -> s.apply(A, Arrays.asList(l1, a1, a2), false));

		// Queue the rebuild and, behind it, events recorded meanwhile, the way the plugin does: append, then apply.
		TradeEvent feb2 = sell(3, 200, FEB + 60), apr = sell(1, 300, APR);
		executor.execute(s::rebuild);
		for (TradeEvent e : Arrays.asList(feb2, apr))
		{
			executor.execute(() ->
			{
				try
				{
					log(A, e);
				}
				catch (Exception ex)
				{
					throw new IllegalStateException(ex);
				}
				s.apply(A, Collections.singletonList(e), true);
			});
		}
		awaitRebuild(s);
		// The April file didn't exist when the rebuild listed the log; it is still read, and nothing counts twice.
		assertTrue(s.book().sameAs(live(l1, a1, a2, feb2, apr)));
	}

	@Test
	public void rebuildWithoutAccountOrLogStillPublishes() throws Exception
	{
		ProfitStore s = store();
		on(s::rebuild);
		assertEquals(1, published.size());
		assertFalse(published.get(0).isLogAvailable());
		on(() -> s.load(A));
		on(s::rebuild);
		awaitRebuild(s);
		assertTrue(s.book().isEmpty());
		assertFalse(published.get(published.size() - 1).isRebuilding());
	}

	@Test
	public void belongsTo()
	{
		JsonObject legacy = new JsonObject();
		assertTrue(ProfitStore.belongsTo(legacy, A));
		JsonObject mine = new JsonObject();
		mine.addProperty("acct", A);
		assertTrue(ProfitStore.belongsTo(mine, A));
		assertFalse(ProfitStore.belongsTo(mine, B));
		JsonObject odd = new JsonObject();
		odd.add("acct", new JsonObject());
		assertFalse(ProfitStore.belongsTo(odd, A));
	}

	@Test
	public void importedTradesCountAsTradesAndRebuildInTimeOrder() throws Exception
	{
		// A live sell, then (appended later, into the same month) the imported buy from before it.
		TradeEvent sold = sell(10, 150, FEB + 600);
		TradeEvent bought = trade(TradeEvent.IMPORTED, 536, TradeEvent.BUY, 10, 100, FEB);
		log(A, sold);
		log(A, bought);
		ProfitStore s = store();
		on(() -> s.load(A));
		on(s::rebuild);
		awaitRebuild(s);
		// Counted where it happened: the buy is the sell's cost basis.
		assertTrue(s.book().sameAs(live(bought, sold)));
		assertEquals(500, s.book().getAllTime());
		assertEquals(0, s.book().getUnknownProceeds());
	}

	@Test
	public void importOfOlderTradesRecountsInTimeOrder() throws Exception
	{
		// The sell was counted live (no basis yet); then an import appends the older buy, as the plugin does.
		TradeEvent sold = sell(10, 150, FEB + 600);
		TradeEvent bought = trade(TradeEvent.IMPORTED, 536, TradeEvent.BUY, 10, 100, FEB);
		log(A, sold);
		ProfitStore s = store();
		on(() -> s.load(A));
		on(() -> s.apply(A, Collections.singletonList(sold), true));
		assertEquals(1_500, s.book().getUnknownProceeds());
		on(() ->
		{
			try
			{
				log(A, bought);
			}
			catch (Exception ex)
			{
				throw new IllegalStateException(ex);
			}
			s.rebuildFor(A);
		});
		awaitRebuild(s);
		// Same as a sorted rebuild: the imported buy is the sell's cost basis, nothing is held.
		assertTrue(s.book().sameAs(live(bought, sold)));
		assertEquals(500, s.book().getAllTime());
		assertEquals(0, s.book().getUnknownProceeds());
		// Applying it on top instead would have left phantom held units and unknown proceeds.
		assertFalse(live(sold, bought).sameAs(live(bought, sold)));
	}

	@Test
	public void anImportNeverRecountsAwayTradesTheLogDoesntHave() throws Exception
	{
		// The sell was counted while the local log was off; an import then brings an older buy.
		TradeEvent sold = sell(10, 150, FEB + 600);
		TradeEvent bought = trade(TradeEvent.IMPORTED, 536, TradeEvent.BUY, 10, 100, FEB);
		ProfitStore s = store();
		on(() -> s.load(A));
		on(() -> s.apply(A, Collections.singletonList(sold), false));
		on(s::saveNow);
		ProfitStore again = store();
		on(() -> again.load(A));
		on(() ->
		{
			try
			{
				log(A, bought);
			}
			catch (Exception ex)
			{
				throw new IllegalStateException(ex);
			}
			assertFalse("a recount from the log would drop the unlogged sell", again.rebuildFor(A));
			again.apply(A, Collections.singletonList(bought), true);
		});
		assertFalse(executor.submit(again::isRebuilding).get(10, TimeUnit.SECONDS));
		assertTrue(again.book().sameAs(live(sold, bought)));
		assertEquals(1_500, again.book().getUnknownProceeds());
	}

	@Test
	public void rebuildForWhileARebuildRunsRebuildsAgain() throws Exception
	{
		TradeEvent sold = sell(10, 150, FEB + 600);
		TradeEvent bought = trade(TradeEvent.IMPORTED, 536, TradeEvent.BUY, 10, 100, FEB);
		log(A, sold);
		// A second month, so the first rebuild takes two tasks and the import lands between them.
		TradeEvent apr = sell(1, 300, APR);
		log(A, apr);
		ProfitStore s = store();
		on(() -> s.load(A));
		Runnable importBuy = () ->
		{
			try
			{
				log(A, bought);
			}
			catch (Exception ex)
			{
				throw new IllegalStateException(ex);
			}
			s.rebuildFor(A);
		};
		// Queued right behind the rebuild's first file (February), so it lands after that file was read.
		on(() ->
		{
			s.rebuild();
			executor.execute(importBuy);
		});
		awaitRebuild(s);
		assertTrue(s.book().sameAs(live(bought, sold, apr)));
	}
}

package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.SeekableByteChannel;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class ReverseLineReaderTest
{
	private static final int[] CHUNKS = {1, 2, 3, 5, 64 * 1024};

	/** An in-memory channel, so no files are needed. */
	private static final class BytesChannel implements SeekableByteChannel
	{
		private final byte[] bytes;
		private long position;
		private boolean open = true;

		BytesChannel(byte[] bytes)
		{
			this.bytes = bytes;
		}

		@Override
		public int read(ByteBuffer dst)
		{
			if (position >= bytes.length)
			{
				return -1;
			}
			int n = (int) Math.min(dst.remaining(), bytes.length - position);
			dst.put(bytes, (int) position, n);
			position += n;
			return n;
		}

		@Override
		public int write(ByteBuffer src)
		{
			throw new UnsupportedOperationException();
		}

		@Override
		public long position()
		{
			return position;
		}

		@Override
		public SeekableByteChannel position(long p)
		{
			position = p;
			return this;
		}

		@Override
		public long size()
		{
			return bytes.length;
		}

		@Override
		public SeekableByteChannel truncate(long size)
		{
			throw new UnsupportedOperationException();
		}

		@Override
		public boolean isOpen()
		{
			return open;
		}

		@Override
		public void close()
		{
			open = false;
		}
	}

	private static List<String> readAll(String text, int chunk) throws IOException
	{
		List<String> lines = new ArrayList<>();
		try (ReverseLineReader r = new ReverseLineReader(new BytesChannel(text.getBytes(StandardCharsets.UTF_8)), chunk))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				lines.add(line);
			}
			// Stays at the start.
			assertEquals(null, r.readLine());
		}
		return lines;
	}

	private static void check(String text, String... newestFirst) throws IOException
	{
		for (int chunk : CHUNKS)
		{
			assertEquals("chunk " + chunk, Arrays.asList(newestFirst), readAll(text, chunk));
		}
	}

	@Test
	public void linesComeBackNewestFirst() throws IOException
	{
		check("one\ntwo\nthree\n", "three", "two", "one");
	}

	@Test
	public void noTrailingNewline() throws IOException
	{
		check("one\ntwo", "two", "one");
	}

	@Test
	public void emptyFile() throws IOException
	{
		check("");
		check("\n\n\r\n");
	}

	@Test
	public void blankLinesAreSkipped() throws IOException
	{
		check("\none\n\n\ntwo\n\n", "two", "one");
	}

	@Test
	public void crlfIsStripped() throws IOException
	{
		check("one\r\ntwo\r\n", "two", "one");
	}

	@Test
	public void multiByteCharactersSplitAcrossChunks() throws IOException
	{
		// "×" and "é" are two bytes each; small chunk sizes split them.
		check("{\"n\":\"3 × café\"}\n{\"n\":\"é×é\"}\n", "{\"n\":\"é×é\"}", "{\"n\":\"3 × café\"}");
		check("×\né", "é", "×");
	}

	@Test
	public void longLinesSpanManyChunks() throws IOException
	{
		String a = String.join("", Collections.nCopies(500, "a")), b = String.join("", Collections.nCopies(300, "bé"));
		check(a + "\n" + b + "\n", b, a);
	}
}

package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.time.Instant;
import java.time.YearMonth;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;

/** Reading RuneLite's own GE trade history: parsing, the seasonal cutoff, ids, dedupe and the result line. */
public class RuneLiteImportTest
{
	private final Gson gson = new Gson();
	/** 2026-08-01T12:00:00Z in epoch ms. */
	private static final long AUG1 = Instant.parse("2026-08-01T12:00:00Z").toEpochMilli();
	private static final long MIN = 60_000L;

	private static RuneLiteImport.Record rec(boolean buy, int item, int qty, long price, long timeMs)
	{
		return new RuneLiteImport.Record(buy, item, qty, price, timeMs);
	}

	private static TradeEvent fill(String offerKey, boolean buy, int item, int qty, long total, long ts, int n)
	{
		return TradeEvent.builder().id(offerKey + ":fill:" + n).kind(TradeEvent.FILL).side(TradeEvent.sideOf(buy))
			.itemId(item).qty(qty).price(TradeEvent.avgPrice(total, qty)).total(total).offerKey(offerKey).ts(ts)
			.world(345).build();
	}

	/** A GE History row read on Dec 1 (after every record in these tests). */
	private static TradeEvent history(String id, boolean buy, int item, int qty, long total)
	{
		return history(id, buy, item, qty, total, Instant.parse("2026-12-01T00:00:00Z").getEpochSecond());
	}

	private static TradeEvent history(String id, boolean buy, int item, int qty, long total, long readTs)
	{
		return TradeEvent.builder().id(id).kind(TradeEvent.HISTORY)
			.side(TradeEvent.sideOf(buy)).itemId(item).qty(qty).price(TradeEvent.avgPrice(total, qty)).total(total)
			.ts(readTs).late(true).world(345).build();
	}

	@Test
	public void parsesRuneLiteRecordsLeniently()
	{
		String json = "[{\"b\":true,\"i\":4151,\"q\":2,\"p\":1500000,\"t\":" + AUG1 + "},"
			+ "{\"b\":false,\"i\":11802,\"q\":1,\"p\":30000000,\"t\":" + (AUG1 + 5) + "},"
			// skipped: no time, zero units, price 0, fractional, string, not an object, missing side
			+ "{\"b\":true,\"i\":1,\"q\":1,\"p\":1},{\"b\":true,\"i\":1,\"q\":0,\"p\":1,\"t\":1},"
			+ "{\"b\":true,\"i\":1,\"q\":1,\"p\":0,\"t\":1},{\"b\":true,\"i\":1.5,\"q\":1,\"p\":1,\"t\":1},"
			+ "{\"b\":true,\"i\":\"x\",\"q\":1,\"p\":1,\"t\":1},7,null,{\"i\":1,\"q\":1,\"p\":1,\"t\":1}]";
		List<RuneLiteImport.Record> r = RuneLiteImport.parse(gson, json);
		assertEquals(Arrays.asList(rec(true, 4151, 2, 1_500_000, AUG1), rec(false, 11802, 1, 30_000_000, AUG1 + 5)), r);
		assertTrue(RuneLiteImport.parse(gson, null).isEmpty());
		assertTrue(RuneLiteImport.parse(gson, "").isEmpty());
		assertTrue(RuneLiteImport.parse(gson, "{\"b\":true}").isEmpty());
		assertTrue(RuneLiteImport.parse(gson, "not json [").isEmpty());
	}

	@Test
	public void idAndEvent()
	{
		RuneLiteImport.Record r = rec(true, 4151, 3, 1_500_001, AUG1 + 999);
		assertEquals("rl:" + (AUG1 + 999) + ":4151:3:1500001:true", RuneLiteImport.id(r));
		assertEquals("rl:" + AUG1 + ":4151:3:1500001:false", RuneLiteImport.id(rec(false, 4151, 3, 1_500_001, AUG1)));
		TradeEvent e = RuneLiteImport.toEvent(r, 345);
		assertEquals(RuneLiteImport.id(r), e.getId());
		assertEquals(TradeEvent.IMPORTED, e.getKind());
		assertEquals(TradeEvent.BUY, e.getSide());
		assertEquals(4151, e.getItemId());
		assertEquals(3, e.getQty());
		assertEquals(1_500_001, e.getPrice());
		// Exactly price * qty: the server checks it.
		assertEquals(Long.valueOf(4_500_003L), e.getTotal());
		// Seconds, rounded down.
		assertEquals(AUG1 / 1000, e.getTs());
		assertTrue(e.isLate());
		assertEquals(345, e.getWorld());
		assertNull(e.getSlot());
		assertNull(e.getOfferKey());
		assertNull(e.getFilled());
		assertNull(e.getSince());
		assertTrue(TradeEvent.isTrade(e.getKind()));
	}

	@Test
	public void cutoffIsTheFirstOfMarch2026()
	{
		assertEquals(Instant.parse("2026-03-01T00:00:00Z"), RuneLiteImport.CUTOFF);
		long cut = RuneLiteImport.CUTOFF.toEpochMilli();
		assertTrue(RuneLiteImport.beforeCutoff(rec(true, 1, 1, 1, cut - 1)));
		assertFalse(RuneLiteImport.beforeCutoff(rec(true, 1, 1, 1, cut)));

		// Seasonal Deadman: Annihilation ran 30 Jan - 20 Feb 2026; those records are ignored.
		long seasonal = Instant.parse("2026-02-10T10:00:00Z").toEpochMilli();
		RuneLiteImport.Plan p = RuneLiteImport.plan(Arrays.asList(rec(true, 1, 1, 5, seasonal), rec(true, 2, 1, 5, cut)),
			Collections.emptyList(), 0, 345);
		assertEquals(1, p.getAdd().size());
		assertEquals(2, p.getAdd().get(0).getItemId());
		assertEquals(1, p.getBeforeCutoff());
		assertEquals(0, p.getAlready());
		assertEquals(cut, p.getNewestMs());
	}

	@Test
	public void previouslyImportedRecordsMatchByTheirOwnId()
	{
		RuneLiteImport.Record a = rec(true, 4151, 1, 1_000, AUG1), b = rec(false, 4151, 1, 1_100, AUG1 + MIN);
		RuneLiteImport.Plan first = RuneLiteImport.plan(Arrays.asList(a, b), Collections.emptyList(), 0, 345);
		assertEquals(2, first.getAdd().size());
		// Oldest first.
		assertEquals(RuneLiteImport.id(a), first.getAdd().get(0).getId());

		// Importing again with what the first import added: nothing new.
		RuneLiteImport.Plan again = RuneLiteImport.plan(Arrays.asList(b, a), first.getAdd(), 0, 345);
		assertTrue(again.getAdd().isEmpty());
		assertEquals(2, again.getAlready());

		// A record that appears twice in the list is imported once.
		RuneLiteImport.Plan dup = RuneLiteImport.plan(Arrays.asList(a, a), Collections.emptyList(), 0, 345);
		assertEquals(1, dup.getAdd().size());
		assertEquals(1, dup.getAlready());
	}

	@Test
	public void watermarkSkipsWhatAnEarlierImportLookedAt()
	{
		RuneLiteImport.Record old = rec(true, 1, 1, 5, AUG1), fresh = rec(true, 1, 1, 5, AUG1 + MIN);
		RuneLiteImport.Plan p = RuneLiteImport.plan(Arrays.asList(old, fresh), Collections.emptyList(), AUG1, 345);
		assertEquals(Collections.singletonList(RuneLiteImport.id(fresh)),
			p.getAdd().stream().map(TradeEvent::getId).collect(Collectors.toList()));
		assertEquals(1, p.getAlready());
		assertEquals(AUG1 + MIN, p.getNewestMs());
		// Nothing newer: the watermark stays.
		assertEquals(AUG1 + MIN, RuneLiteImport.plan(Collections.singletonList(old), Collections.emptyList(), AUG1 + MIN, 345)
			.getNewestMs());
	}

	@Test
	public void liveFillsOfOneOfferMatchTheirRecord()
	{
		long ts = AUG1 / 1000;
		// One offer of 10 filled in two parts for 10,005 gp in all: RuneLite records q 10, p 1,000 (10,005 / 10).
		List<TradeEvent> known = Arrays.asList(
			fill("k1", true, 4151, 4, 4_000, ts - 300, 4),
			fill("k1", true, 4151, 6, 6_005, ts - 30, 10));
		RuneLiteImport.Record r = rec(true, 4151, 10, 1_000, AUG1);
		RuneLiteImport.Plan p = RuneLiteImport.plan(Collections.singletonList(r), known, 0, 345);
		assertTrue(p.getAdd().isEmpty());
		assertEquals(1, p.getAlready());

		// Same offer, but the other side, item, units or a total off by more than q gp: not it.
		for (RuneLiteImport.Record other : Arrays.asList(rec(false, 4151, 10, 1_000, AUG1), rec(true, 4152, 10, 1_000, AUG1),
			rec(true, 4151, 9, 1_000, AUG1), rec(true, 4151, 10, 998, AUG1)))
		{
			assertEquals(other.toString(), 1, RuneLiteImport.plan(Collections.singletonList(other), known, 0, 345).getAdd().size());
		}
	}

	@Test
	public void liveOfferMustHaveCompletedWithinTenMinutes()
	{
		long ts = AUG1 / 1000;
		List<TradeEvent> known = Collections.singletonList(fill("k1", false, 560, 100, 25_000, ts - 600, 100));
		assertEquals(0, RuneLiteImport.plan(Collections.singletonList(rec(false, 560, 100, 250, AUG1)), known, 0, 345)
			.getAdd().size());
		assertEquals(1, RuneLiteImport.plan(Collections.singletonList(rec(false, 560, 100, 250, AUG1 + 1000)), known, 0, 345)
			.getAdd().size());
		assertEquals(1, RuneLiteImport.plan(Collections.singletonList(rec(false, 560, 100, 250, AUG1 - 1_201_000)), known, 0, 345)
			.getAdd().size());
	}

	@Test
	public void cancelledOfferCompletesAtItsCancellation()
	{
		long ts = AUG1 / 1000;
		// Filled 3 an hour before it was cancelled; RuneLite records it at the cancellation.
		List<TradeEvent> known = Arrays.asList(
			fill("k2", true, 2, 3, 300, ts - 3600, 3),
			TradeEvent.builder().id("k2:cancelled").kind(TradeEvent.CANCELLED).side(TradeEvent.BUY).itemId(2).qty(7)
				.price(100).offerKey("k2").ts(ts + 20).world(345).build());
		RuneLiteImport.Plan p = RuneLiteImport.plan(Collections.singletonList(rec(true, 2, 3, 100, AUG1)), known, 0, 345);
		assertTrue(p.getAdd().isEmpty());
	}

	@Test
	public void eachOfferOrHistoryRowMatchesOneRecordOnly()
	{
		long ts = AUG1 / 1000;
		// Two identical trades, one recorded live: the other is imported.
		List<TradeEvent> live = Collections.singletonList(fill("k3", true, 7, 5, 500, ts, 5));
		RuneLiteImport.Plan p = RuneLiteImport.plan(Arrays.asList(rec(true, 7, 5, 100, AUG1), rec(true, 7, 5, 100, AUG1 + MIN)),
			live, 0, 345);
		assertEquals(1, p.getAdd().size());
		assertEquals(1, p.getAlready());

		// The closest offer in time is the one taken.
		List<TradeEvent> two = Arrays.asList(fill("a", true, 7, 5, 500, ts - 500, 5), fill("b", true, 7, 5, 500, ts + 400, 5));
		p = RuneLiteImport.plan(Arrays.asList(rec(true, 7, 5, 100, AUG1 + 450_000), rec(true, 7, 5, 100, AUG1 - 450_000)),
			two, 0, 345);
		assertTrue(p.getAdd().isEmpty());

		// GE History rows have no time: matched by side, item, units and total, each once.
		List<TradeEvent> rows = Arrays.asList(history("hist:a", false, 9, 2, 2_001), history("hist:b", false, 9, 2, 2_001));
		p = RuneLiteImport.plan(Arrays.asList(rec(false, 9, 2, 1_000, AUG1), rec(false, 9, 2, 1_000, AUG1 + 99 * MIN),
			rec(false, 9, 2, 1_000, AUG1 + 300 * MIN)), rows, 0, 345);
		assertEquals(1, p.getAdd().size());
		assertEquals(2, p.getAlready());
		// The same history row read twice (log + memory) still counts once.
		p = RuneLiteImport.plan(Arrays.asList(rec(false, 9, 2, 1_000, AUG1), rec(false, 9, 2, 1_000, AUG1 + MIN)),
			Arrays.asList(rows.get(0), rows.get(0)), 0, 345);
		assertEquals(1, p.getAdd().size());
	}

	@Test
	public void historyRowOnlyMatchesARecordFromBeforeItWasRead()
	{
		long aug1 = AUG1 / 1000;
		// 1 whip bought on Aug 1 and read from GE History that day; another identical buy on Sep 10.
		TradeEvent row = history("hist:w", true, 4151, 1, 1_500_000, aug1 + 3600);
		long sep10 = Instant.parse("2026-09-10T12:00:00Z").toEpochMilli();
		RuneLiteImport.Plan p = RuneLiteImport.plan(Arrays.asList(rec(true, 4151, 1, 1_500_000, AUG1),
			rec(true, 4151, 1, 1_500_000, sep10)), Collections.singletonList(row), 0, 345);
		assertEquals(1, p.getAlready());
		assertEquals(1, p.getAdd().size());
		assertEquals(sep10 / 1000, p.getAdd().get(0).getTs());

		// Only the Sep 10 record: the Aug 1 row can't be it.
		p = RuneLiteImport.plan(Collections.singletonList(rec(true, 4151, 1, 1_500_000, sep10)),
			Collections.singletonList(row), 0, 345);
		assertEquals(1, p.getAdd().size());
		assertEquals(0, p.getAlready());

		// Of two rows read after the record, the earliest read is taken, leaving the later one for a later record.
		TradeEvent late = history("hist:late", true, 4151, 1, 1_500_000, sep10 / 1000 + 3600);
		p = RuneLiteImport.plan(Arrays.asList(rec(true, 4151, 1, 1_500_000, AUG1),
			rec(true, 4151, 1, 1_500_000, sep10)), Arrays.asList(late, row), 0, 345);
		assertTrue(p.getAdd().isEmpty());
		assertEquals(2, p.getAlready());
	}

	@Test
	public void geHistoryReadAfterAnImportSkipsTheImportedTrades()
	{
		long aug1 = AUG1 / 1000;
		TradeEvent imported = RuneLiteImport.toEvent(rec(false, 4151, 100, 1_200, AUG1), 345);
		List<String> recent = RuneLiteImport.remember(new ArrayList<>(), Collections.singletonList(imported));
		assertEquals(Collections.singletonList("sell|4151|100|1200|" + aug1), recent);

		// The GE History row for it (total within q gp), read later: skipped, once.
		TradeEvent row = history("hist:1", false, 4151, 100, 120_050, aug1 + 86_400);
		assertFalse(RuneLiteImport.consumeRecent(recent, history("hist:x", true, 4151, 100, 120_050, aug1 + 86_400)));
		assertFalse(RuneLiteImport.consumeRecent(recent, history("hist:x", false, 4151, 100, 120_101, aug1 + 86_400)));
		// A row read before the trade can't be it.
		assertFalse(RuneLiteImport.consumeRecent(recent, history("hist:x", false, 4151, 100, 120_050, aug1 - 3_600)));
		assertTrue(RuneLiteImport.consumeRecent(recent, row));
		assertTrue(recent.isEmpty());
		assertFalse(RuneLiteImport.consumeRecent(recent, row));

		// Bounded, newest kept; malformed entries dropped.
		List<TradeEvent> many = new ArrayList<>();
		for (int i = 0; i < RuneLiteImport.MAX_RECENT + 10; i++)
		{
			many.add(RuneLiteImport.toEvent(rec(true, 1, 1, 1, AUG1 + i * MIN), 345));
		}
		List<String> kept = RuneLiteImport.remember(Arrays.asList("junk", "buy|1|x|1|1"), many);
		assertEquals(RuneLiteImport.MAX_RECENT, kept.size());
		assertEquals(RuneLiteImport.recentEntry(many.get(many.size() - 1)), kept.get(kept.size() - 1));
		assertEquals(RuneLiteImport.recentEntry(many.get(10)), kept.get(0));
	}

	@Test
	public void needsTheLocalLog()
	{
		assertEquals(RuneLiteImport.NEEDS_LOGIN, RuneLiteImport.blocked(false, true));
		assertEquals(RuneLiteImport.NEEDS_LOGIN, RuneLiteImport.blocked(false, false));
		// Without the log, live trades from earlier sessions can't be seen, so they'd be imported again.
		assertEquals(RuneLiteImport.NEEDS_LOCAL_LOG, RuneLiteImport.blocked(true, false));
		assertNull(RuneLiteImport.blocked(true, true));
	}

	@Test
	public void totalWithinQGp()
	{
		RuneLiteImport.Record r = rec(true, 1, 4, 100, AUG1);
		assertTrue(RuneLiteImport.totalMatches(400, r));
		assertTrue(RuneLiteImport.totalMatches(403, r));
		assertTrue(RuneLiteImport.totalMatches(404, r));
		assertFalse(RuneLiteImport.totalMatches(405, r));
		assertTrue(RuneLiteImport.totalMatches(396, r));
		assertFalse(RuneLiteImport.totalMatches(395, r));
	}

	@Test
	public void resultLine()
	{
		ZoneId utc = ZoneOffset.UTC;
		List<TradeEvent> add = new ArrayList<>();
		add.add(RuneLiteImport.toEvent(rec(true, 1, 1, 1, Instant.parse("2026-07-29T10:00:00Z").toEpochMilli()), 345));
		add.add(RuneLiteImport.toEvent(rec(true, 1, 1, 1, Instant.parse("2026-10-07T10:00:00Z").toEpochMilli()), 345));
		assertEquals("Imported 2 trades (Jul 29 - Oct 7) - 210 already recorded",
			RuneLiteImport.message(new RuneLiteImport.Plan(add, 210, 0, 0), utc));
		assertEquals("Imported 1 trade (Jul 29)",
			RuneLiteImport.message(new RuneLiteImport.Plan(add.subList(0, 1), 0, 0, 0), utc));
		assertEquals("No new trades - 5 already recorded", RuneLiteImport.message(new RuneLiteImport.Plan(
			Collections.emptyList(), 5, 0, 0), utc));
		assertEquals("No trades to import - 3 from before Mar 1 2026 ignored", RuneLiteImport.message(new RuneLiteImport.Plan(
			Collections.emptyList(), 0, 3, 0), utc));
		assertEquals("RuneLite's Grand Exchange plugin has no trade history for this account yet.",
			RuneLiteImport.message(new RuneLiteImport.Plan(Collections.emptyList(), 0, 0, 0), utc));
		List<TradeEvent> years = Arrays.asList(add.get(1),
			RuneLiteImport.toEvent(rec(true, 1, 1, 1, Instant.parse("2027-01-02T10:00:00Z").toEpochMilli()), 345));
		assertEquals("Oct 7 2026 - Jan 2 2027", RuneLiteImport.range(years, utc));
	}

	@Test
	public void firstLogMonthToRead()
	{
		RuneLiteImport.Record jul = rec(true, 1, 1, 1, Instant.parse("2026-07-01T00:05:00Z").toEpochMilli());
		RuneLiteImport.Record oct = rec(true, 1, 1, 1, Instant.parse("2026-10-07T00:00:00Z").toEpochMilli());
		assertEquals(YearMonth.of(2026, 6), RuneLiteImport.firstMonth(Arrays.asList(oct, jul)));
		assertNull(RuneLiteImport.firstMonth(Collections.emptyList()));
	}
}

package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.Map;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import org.junit.Assume;
import org.junit.Test;

/**
 * Opt-in contract check against a real collection server (skipped unless the environment variable
 * DGT_CONTRACT_SERVER holds its base URL, e.g. a local server from server/ on an ephemeral port). Exercises
 * registration, authorised uploads, the 401 re-registration path, the item limit field, include=trust,fill and
 * DELETE v1/me with the plugin's own classes.
 */
public class ServerContractTest
{
	private final Gson gson = new Gson();
	private final OkHttpClient http = new OkHttpClient();

	@Test
	public void registerSubmitDelete() throws InterruptedException
	{
		String url = System.getenv("DGT_CONTRACT_SERVER");
		Assume.assumeTrue("set DGT_CONTRACT_SERVER to run", url != null && !url.isEmpty());
		HttpUrl base = HttpUrl.get(url);

		Map<String, String> config = new ConcurrentHashMap<>();
		InstallIdentity identity = FakeServer.identity(config);
		AtomicBoolean connected = new AtomicBoolean(true);
		BlockingQueue<java.util.Set<Integer>> sent = new LinkedBlockingQueue<>();
		TradeUploader up = new TradeUploader(http, gson, base, sent::add, identity, connected::get);
		String acct = AccountId.of(123456789L);
		long now = System.currentTimeMillis() / 1000;

		// 1. First upload: registers, then submits with the token (a placed offer, a fill, item info with a limit).
		TradeEvent placed = TradeEvent.builder().id("ck1:placed").kind(TradeEvent.PLACED).side(TradeEvent.BUY)
			.itemId(4151).qty(10).price(1_500_000).slot(0).offerKey("ck1").ts(now - 60).late(false).world(345).build();
		TradeEvent fill = TradeEvent.builder().id("ck1:fill:2").kind(TradeEvent.FILL).side(TradeEvent.BUY).itemId(4151)
			.qty(2).price(1_490_000).total(2_980_000L).slot(0).offerKey("ck1").ts(now - 30).late(false).filled(2)
			.world(345).build();
		up.add(placed, acct);
		up.add(fill, acct);
		up.addItem(4151, "Abyssal whip", null, 70);
		up.flush();
		assertEquals(Collections.singleton(4151), sent.poll(10, TimeUnit.SECONDS));
		FakeServer.awaitIdle(up);
		assertFalse(up.hasPending());
		String firstId = identity.installId();
		String firstToken = identity.token();
		assertNotNull("registered", firstToken);

		// 1b. Imported RuneLite trades: 120 of them go in two requests (at most 100 per request), all accepted.
		for (int i = 0; i < 120; i++)
		{
			up.add(RuneLiteImport.toEvent(new RuneLiteImport.Record(i % 2 == 0, 4151, 1 + i % 3, 1_400_000 + i,
				(now - 86400L * (1 + i % 60)) * 1000 + i), 345), acct);
		}
		up.flush();
		assertNotNull(sent.poll(10, TimeUnit.SECONDS));
		FakeServer.awaitIdle(up);
		assertEquals("the rest wait for the next request", 20, up.queued());
		up.flush();
		assertNotNull(sent.poll(10, TimeUnit.SECONDS));
		FakeServer.awaitIdle(up);
		assertEquals(0, up.queued());
		BlockingQueue<Object> imp = new LinkedBlockingQueue<>();
		new MarketClient(http, gson, base, 345).itemAsync(4151, imp::add, imp::add);
		Object d = imp.poll(10, TimeUnit.SECONDS);
		assertTrue(String.valueOf(d), d instanceof MarketData.ItemDetail);
		// A live fill exists, so the last price is the fill's, not an imported one; vol24 counts the live fill only.
		assertEquals(Long.valueOf(1_490_000), ((MarketData.ItemDetail) d).getSummary().getLastBuy());
		assertEquals(2, ((MarketData.ItemDetail) d).getSummary().getVol24());

		// 2. A wrong token: 401, re-register gets 409 (the id has a token), so the uploader rotates and resends.
		identity.setToken(firstId, FakeServer.tok('x'));
		up.add(fill.toBuilder().id("ck1:fill:3").qty(1).total(1_490_000L).filled(3).build(), acct);
		up.flush();
		assertNotNull(sent.poll(10, TimeUnit.SECONDS));
		FakeServer.awaitIdle(up);
		assertNotEquals("rotated after 409", firstId, identity.installId());
		assertNotNull(identity.token());

		// 3. Reads with include=trust,fill carry the new fields.
		MarketClient market = new MarketClient(http, gson, base, 345);
		BlockingQueue<Object> got = new LinkedBlockingQueue<>();
		market.itemAsync(4151, got::add, got::add);
		Object detail = got.poll(10, TimeUnit.SECONDS);
		assertTrue(String.valueOf(detail), detail instanceof MarketData.ItemDetail);
		MarketData.Summary s = ((MarketData.ItemDetail) detail).getSummary();
		assertNotNull("confVol24 (include=trust)", s.getConfVol24());
		assertEquals(Long.valueOf(1_490_000), s.getLastFillBuy());
		market.items(Collections.singletonList(4151), false, got::add, got::add);
		Object items = got.poll(10, TimeUnit.SECONDS);
		assertTrue(String.valueOf(items), items instanceof MarketData.ItemsResponse);
		assertEquals(1, ((MarketData.ItemsResponse) items).getItems().size());
		assertNotNull(((MarketData.ItemsResponse) items).getItems().get(0).getConfVol24());

		// 4. Delete my shared data: DELETE v1/me with the token, then disconnected with a new id and no token.
		String beforeDelete = identity.installId();
		BlockingQueue<DataDeletion.Result> results = new LinkedBlockingQueue<>();
		DataDeletion deletion = new DataDeletion(http, gson, base, identity, up, () -> connected.set(false));
		assertTrue(deletion.start(results::add));
		DataDeletion.Result r = results.poll(20, TimeUnit.SECONDS);
		assertNotNull(r);
		assertTrue(r.toString(), r.outcome == DataDeletion.Outcome.DELETED || r.outcome == DataDeletion.Outcome.PENDING);
		assertFalse(connected.get());
		assertNull(identity.token());
		assertNotEquals(beforeDelete, identity.installId());

		// 5. The deleted install's id can't be registered again (tombstone).
		Map<String, String> ghostConfig = new ConcurrentHashMap<>();
		ghostConfig.put(InstallIdentity.KEY_INSTALL_ID, beforeDelete);
		InstallIdentity old = FakeServer.identity(ghostConfig);
		BlockingQueue<InstallAuth.Result> reg = new LinkedBlockingQueue<>();
		new InstallAuth(http, gson, base, old).register(false, reg::add);
		InstallAuth.Result again = reg.poll(10, TimeUnit.SECONDS);
		assertNotNull(again);
		assertEquals("tombstoned id", InstallAuth.Status.DELETED, again.getStatus());

		// 6. Deleting again from the new (never used) id: registers first, then deletes nothing.
		connected.set(true);
		assertTrue(deletion.start(results::add));
		DataDeletion.Result second = results.poll(20, TimeUnit.SECONDS);
		assertNotNull(second);
		assertEquals(second.toString(), DataDeletion.Outcome.DELETED, second.outcome);
	}
}

