/**
 * Flush must never throw or leave the in-flight flag stuck, whatever state the queues are in. No network: requests
 * are answered by an interceptor.
 */
public class TradeUploaderFlushTest
{
	private static final HttpUrl BASE = HttpUrl.get("http://localhost:1");
	private static final String PNG_BASE64_PREFIX = "iVBORw0KGgo";

	private final Gson gson = new Gson();
	/** Requests seen by the fake server, in order. */
	private final BlockingQueue<Request> requests = new LinkedBlockingQueue<>();

	/** The plugin's uploader, with a token already issued (as after registering): uploads go straight out. */
	private TradeUploader uploader(OkHttpClient http, Consumer<Set<Integer>> onSent)
	{
		InstallIdentity id = FakeServer.identity(new HashMap<>());
		id.setToken(id.installId(), FakeServer.tok('f'));
		return new TradeUploader(http, gson, BASE, onSent, id, () -> true);
	}

	private OkHttpClient fakeServer()
	{
		return new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				requests.add(chain.request());
				return new Response.Builder()
					.request(chain.request())
					.protocol(Protocol.HTTP_1_1)
					.code(200)
					.message("fake")
					.body(ResponseBody.create(null, ""))
					.build();
			})
			.build();
	}

	private static TradeEvent fill(int world)
	{
		return TradeEvent.builder().id("k:fill:1").kind(TradeEvent.FILL).side(TradeEvent.BUY).itemId(4151).qty(1)
			.price(1).total(1L).ts(1).world(world).build();
	}

	private static BufferedImage visibleImage()
	{
		BufferedImage img = new BufferedImage(4, 4, BufferedImage.TYPE_INT_ARGB);
		img.setRGB(1, 1, 0xff00ff00);
		return img;
	}

	/** An image that counts pixel reads, so a test can tell when the PNG encoding (which scans pixels) ran. */
	private static final class CountingImage extends BufferedImage
	{
		final AtomicInteger reads = new AtomicInteger();

		CountingImage()
		{
			super(4, 4, BufferedImage.TYPE_INT_ARGB);
			super.setRGB(1, 1, 0xff00ff00);
		}

		@Override
		public int getRGB(int x, int y)
		{
			reads.incrementAndGet();
			return super.getRGB(x, y);
		}
	}

	/** Waits for the response callback to clear the in-flight flag. */
	private static void awaitIdle(TradeUploader up) throws InterruptedException
	{
		for (int i = 0; i < 500 && up.isInFlight(); i++)
		{
			TimeUnit.MILLISECONDS.sleep(10);
		}
		assertFalse("in-flight flag stuck", up.isInFlight());
	}

	@Test
	public void nextKeyHandlesEmptySnapshot()
	{
		Map<TradeUploader.BatchKey, List<JsonObject>> offers = new ConcurrentHashMap<>();
		// The old flush assumed the offers map was still non-empty here and threw NoSuchElementException.
		assertNull(TradeUploader.nextKey(null, offers));
		offers.put(new TradeUploader.BatchKey(345, "a"), Collections.emptyList());
		assertEquals(new TradeUploader.BatchKey(345, "a"), TradeUploader.nextKey(null, offers));
		assertEquals(new TradeUploader.BatchKey(318, "b"),
			TradeUploader.nextKey(new TradeUploader.Queued(fill(318), "b"), offers));
	}

	private JsonObject nextBody() throws InterruptedException, IOException
	{
		Request req = requests.poll(5, TimeUnit.SECONDS);
		assertNotNull("expected a request", req);
		Buffer buf = new Buffer();
		req.body().writeTo(buf);
		return gson.fromJson(buf.readUtf8(), JsonObject.class);
	}

	@Test
	public void batchesNeverMixAccounts() throws InterruptedException, IOException
	{
		TradeUploader up = uploader(fakeServer(), ids ->
		{
		});
		TradeEvent a1 = fill(345).toBuilder().id("a1").build();
		TradeEvent b1 = fill(345).toBuilder().id("b1").build();
		TradeEvent a2 = fill(345).toBuilder().id("a2").build();
		TradeEvent n1 = fill(345).toBuilder().id("n1").build();
		up.add(a1, "acct-a");
		up.add(b1, "acct-b");
		up.add(a2, "acct-a");
		up.add(n1, null);

		up.flush();
		JsonObject first = nextBody();
		awaitIdle(up);
		assertEquals("acct-a", first.get("accountId").getAsString());
		assertEquals(2, first.getAsJsonArray("events").size());
		assertEquals("a1", first.getAsJsonArray("events").get(0).getAsJsonObject().get("id").getAsString());
		assertEquals("a2", first.getAsJsonArray("events").get(1).getAsJsonObject().get("id").getAsString());

		up.flush();
		JsonObject second = nextBody();
		awaitIdle(up);
		assertEquals("acct-b", second.get("accountId").getAsString());
		assertEquals(1, second.getAsJsonArray("events").size());
		assertEquals("b1", second.getAsJsonArray("events").get(0).getAsJsonObject().get("id").getAsString());

		// Unknown account: its own batch, and no accountId field at all.
		up.flush();
		JsonObject third = nextBody();
		awaitIdle(up);
		assertFalse(third.has("accountId"));
		assertEquals("n1", third.getAsJsonArray("events").get(0).getAsJsonObject().get("id").getAsString());

		up.flush();
		assertNull(requests.poll(200, TimeUnit.MILLISECONDS));
	}

	@Test
	public void openOffersGoWithTheirAccount() throws InterruptedException, IOException
	{
		TradeUploader up = uploader(fakeServer(), ids ->
		{
		});
		JsonObject offer = new JsonObject();
		offer.addProperty("slot", 1);
		up.setOpenOffers(345, "acct-b", Collections.singletonList(offer));
		up.add(fill(345), "acct-a");

		up.flush();
		JsonObject first = nextBody();
		awaitIdle(up);
		assertEquals("acct-a", first.get("accountId").getAsString());
		assertFalse(first.has("offers"));

		up.flush();
		JsonObject second = nextBody();
		awaitIdle(up);
		assertEquals("acct-b", second.get("accountId").getAsString());
		assertEquals(0, second.getAsJsonArray("events").size());
		assertEquals(1, second.getAsJsonArray("offers").size());
	}

	@Test
	public void flushOnEmptyAfterClearDoesNotWedge() throws InterruptedException
	{
		TradeUploader up = uploader(fakeServer(), ids ->
		{
		});
		// Open offers queued, then dropped (sharing switched off) right before the flush ran.
		up.setOpenOffers(345, null, Collections.emptyList());
		up.clear();
		up.flush();
		assertFalse(up.isInFlight());
		assertNull(requests.poll());

		// The uploader still works afterwards.
		up.add(fill(345), null);
		up.flush();
		assertNotNull(requests.poll(5, TimeUnit.SECONDS));
		awaitIdle(up);
	}

	@Test
	public void flushThatThrowsResetsInFlight() throws InterruptedException
	{
		AtomicInteger calls = new AtomicInteger();
		OkHttpClient real = fakeServer();
		OkHttpClient failingOnce = new OkHttpClient()
		{
			@Override
			public Call newCall(Request request)
			{
				if (calls.getAndIncrement() == 0)
				{
					throw new IllegalStateException("boom");
				}
				return real.newCall(request);
			}
		};
		TradeUploader up = uploader(failingOnce, ids ->
		{
		});
		up.add(fill(345), null);

		up.flush(); // must not throw
		assertFalse(up.isInFlight());

		up.flush();
		assertNotNull(requests.poll(5, TimeUnit.SECONDS));
		awaitIdle(up);
	}

	@Test
	public void iconIsEncodedOnlyOnceRendered()
	{
		TradeUploader.ItemInfo info = new TradeUploader.ItemInfo(4151, "Abyssal whip");
		info.image = visibleImage();

		// Added but not rendered yet: nothing to encode.
		TradeUploader.encodeIcon(info);
		assertNull(info.icon);

		info.imageReady = true;
		TradeUploader.encodeIcon(info);
		assertNotNull(info.icon);
		assertTrue(info.icon.startsWith(PNG_BASE64_PREFIX));
	}

	@Test
	public void addItemDoesNotEncodeButFlushSendsTheIcon() throws InterruptedException, IOException
	{
		TradeUploader up = uploader(fakeServer(), ids ->
		{
		});
		CountingImage img = new CountingImage();
		up.addItem(4151, "Abyssal whip", img);
		up.setIcon(4151, img);
		assertFalse(up.needsItem(4151));
		// addItem/setIcon run on the client thread: they must not scan or encode the image.
		assertEquals(0, img.reads.get());

		// Items ride along with a batch of events.
		up.add(fill(345), null);
		up.flush();
		Request req = requests.poll(5, TimeUnit.SECONDS);
		assertNotNull(req);
		// The encoding happened in flush.
		assertTrue(img.reads.get() > 0);
		Buffer buf = new Buffer();
		req.body().writeTo(buf);
		JsonObject body = gson.fromJson(buf.readUtf8(), JsonObject.class);
		JsonObject item = body.getAsJsonArray("items").get(0).getAsJsonObject();
		assertEquals("Abyssal whip", item.get("name").getAsString());
		assertTrue(item.get("icon").getAsString().startsWith(PNG_BASE64_PREFIX));
		awaitIdle(up);
	}

	private OkHttpClient serverAnswering(int code)
	{
		return new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				requests.add(chain.request());
				return new Response.Builder().request(chain.request()).protocol(Protocol.HTTP_1_1).code(code)
					.message("fake").body(ResponseBody.create(null, "")).build();
			})
			.build();
	}

	@Test
	public void onSentGetsTheBatchItemIdsOnlyOnSuccess() throws InterruptedException
	{
		BlockingQueue<Set<Integer>> sent = new LinkedBlockingQueue<>();
		TradeUploader up = uploader(fakeServer(), sent::add);
		up.add(fill(345), "a");
		up.add(fill(345).toBuilder().id("x").itemId(536).build(), "a");
		up.flush();
		assertNotNull(requests.poll(5, TimeUnit.SECONDS));
		assertEquals(new HashSet<>(Arrays.asList(4151, 536)), sent.poll(5, TimeUnit.SECONDS));
		awaitIdle(up);

		// Offers only: nothing traded, nothing to report.
		up.setOpenOffers(345, "a", Collections.emptyList());
		up.flush();
		assertNotNull(requests.poll(5, TimeUnit.SECONDS));
		awaitIdle(up);
		assertNull(sent.poll(200, TimeUnit.MILLISECONDS));

		// Server errors: not sent, not reported.
		for (int code : new int[]{500, 400})
		{
			TradeUploader failing = uploader(serverAnswering(code), sent::add);
			failing.add(fill(345), "a");
			failing.flush();
			assertNotNull(requests.poll(5, TimeUnit.SECONDS));
			awaitIdle(failing);
			assertNull(sent.poll(200, TimeUnit.MILLISECONDS));
		}
	}

	@Test
	public void throwingOnSentDoesNotWedgeTheUploader() throws InterruptedException
	{
		TradeUploader up = uploader(fakeServer(), ids ->
		{
			throw new IllegalStateException("boom");
		});
		up.add(fill(345), null);
		up.flush();
		assertNotNull(requests.poll(5, TimeUnit.SECONDS));
		awaitIdle(up);
		up.add(fill(345).toBuilder().id("2").build(), null);
		up.flush();
		assertNotNull(requests.poll(5, TimeUnit.SECONDS));
		awaitIdle(up);
	}
}

package com.deadmantoolkit;

import static com.deadmantoolkit.FakeServer.REGISTER;
import static com.deadmantoolkit.FakeServer.SUBMIT;
import static com.deadmantoolkit.FakeServer.awaitIdle;
import static com.deadmantoolkit.FakeServer.json;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Test;

/** Imported trades upload at most 100 per request, and what the server defers stays queued instead of being lost. */
public class TradeUploaderImportTest
{
	private final Gson gson = new Gson();
	private final FakeServer server = new FakeServer();
	private final Map<String, String> config = new ConcurrentHashMap<>();
	private final InstallIdentity identity = FakeServer.identity(config);
	private final AtomicLong now = new AtomicLong(1_791_300_000L);

	private TradeUploader uploader()
	{
		TradeUploader up = new TradeUploader(server.client(), gson, FakeServer.BASE, ids ->
		{
		}, identity, () -> true);
		up.setClock(now::get);
		return up;
	}

	private static TradeEvent imported(int i)
	{
		return RuneLiteImport.toEvent(new RuneLiteImport.Record(true, 4151, 1, 100 + i, 1_790_000_000_000L + i), 345);
	}

	private static TradeEvent fill(String id)
	{
		return TradeEvent.builder().id(id).kind(TradeEvent.FILL).side(TradeEvent.BUY).itemId(4151).qty(1)
			.price(1).total(1L).ts(1).world(345).build();
	}

	private static List<String> ids(FakeServer.Seen s)
	{
		List<String> out = new ArrayList<>();
		for (JsonElement e : s.json().getAsJsonArray("events"))
		{
			out.add(e.getAsJsonObject().get("id").getAsString());
		}
		return out;
	}

	private FakeServer.Seen nextSubmit() throws InterruptedException
	{
		FakeServer.Seen s = server.next();
		while (REGISTER.equals(s.path()))
		{
			s = server.next();
		}
		assertEquals(SUBMIT, s.path());
		return s;
	}

	private static String deferred(List<String> ids, long retryAfter)
	{
		JsonArray arr = new JsonArray();
		ids.forEach(arr::add);
		return "{\"ok\":true,\"accepted\":0,\"rejected\":0,\"paired\":0,\"deferred\":" + ids.size() + ",\"deferredIds\":"
			+ arr + (retryAfter > 0 ? ",\"retryAfter\":" + retryAfter : "") + "}";
	}

	@Test
	public void atMostOneHundredImportedPerRequest() throws InterruptedException
	{
		TradeUploader up = uploader();
		for (int i = 0; i < 150; i++)
		{
			up.add(imported(i), "acct");
		}
		up.add(fill("live"), "acct");
		up.flush();
		FakeServer.Seen first = nextSubmit();
		List<String> sent = ids(first);
		// 100 imported plus the live fill behind them; the other 50 wait for the next request.
		assertEquals(101, sent.size());
		assertTrue(sent.contains("live"));
		assertEquals(100, sent.stream().filter(id -> id.startsWith("rl:")).count());
		awaitIdle(up);
		assertEquals(50, up.queued());

		up.flush();
		assertEquals(50, ids(nextSubmit()).size());
		awaitIdle(up);
		assertEquals(0, up.queued());
		assertFalse(up.hasPending());
	}

	@Test
	public void deferredIdsStayQueuedAndRetryAfterHoldsImportsOnly() throws InterruptedException
	{
		TradeUploader up = uploader();
		List<TradeEvent> events = new ArrayList<>();
		for (int i = 0; i < 5; i++)
		{
			events.add(imported(i));
			up.add(imported(i), "acct");
		}
		up.add(fill("live1"), "acct");
		// The server stored 3 and deferred 2 (its daily allowance ran out); retry in an hour.
		List<String> late = Arrays.asList(events.get(3).getId(), events.get(4).getId());
		server.on(SUBMIT, json(200, deferred(late, 3600)));
		up.flush();
		assertEquals(6, ids(nextSubmit()).size());
		awaitIdle(up);
		assertEquals(2, up.queued());
		assertEquals(now.get() + 3600, up.importsHeldUntil());

		// Held: imported events aren't sent, and with only them queued there is nothing to send.
		assertFalse(up.hasPending());
		up.flush();
		assertNull(server.poll(200));

		// Live events still go, without the held imports.
		up.add(fill("live2"), "acct");
		up.flush();
		assertEquals(Collections.singletonList("live2"), ids(nextSubmit()));
		awaitIdle(up);

		// After the hold, the deferred ones go again.
		now.addAndGet(3600);
		assertTrue(up.hasPending());
		up.flush();
		assertEquals(late, ids(nextSubmit()));
		awaitIdle(up);
		assertEquals(0, up.queued());
	}

	@Test
	public void deferredWithoutRetryAfterGoesInTheNextRequest() throws InterruptedException
	{
		TradeUploader up = uploader();
		up.add(imported(1), "acct");
		up.add(imported(2), "acct");
		server.on(SUBMIT, json(200, deferred(Collections.singletonList(imported(2).getId()), 0)));
		up.flush();
		assertEquals(2, ids(nextSubmit()).size());
		awaitIdle(up);
		assertEquals(1, up.queued());
		assertEquals(0, up.importsHeldUntil());
		assertTrue(up.hasPending());
		up.flush();
		assertEquals(Collections.singletonList(imported(2).getId()), ids(nextSubmit()));
		awaitIdle(up);
		assertEquals(0, up.queued());
	}

	@Test
	public void deferredParsing()
	{
		assertTrue(TradeUploader.Deferred.parse(gson, null).ids.isEmpty());
		assertTrue(TradeUploader.Deferred.parse(gson, "").ids.isEmpty());
		assertTrue(TradeUploader.Deferred.parse(gson, "{\"ok\":true,\"accepted\":3}").ids.isEmpty());
		assertTrue(TradeUploader.Deferred.parse(gson, "not json").ids.isEmpty());
		TradeUploader.Deferred d = TradeUploader.Deferred.parse(gson, "{\"deferredIds\":[\"a\",7,null,\"b\"],\"retryAfter\":-5}");
		assertEquals(2, d.ids.size());
		assertEquals(0, d.retryAfter);
	}
}

package com.deadmantoolkit;

import static org.junit.Assert.assertEquals;
import com.deadmantoolkit.OfferTracker.SlotState;
import com.deadmantoolkit.OfferTracker.Status;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

/**
 * Pins the submit request body, which is the server's contract.
 */
public class TradeUploaderTest
{
	private final Gson gson = new Gson();

	private static final String OFFER_JSON = "{\"slot\":2,\"offerKey\":\"k1\",\"side\":\"sell\",\"itemId\":4151,\"price\":300000,"
		+ "\"totalQty\":10,\"filledQty\":3,\"placedAt\":100}";

	private static SlotState slot()
	{
		return new SlotState("k1", 4151, false, 300_000, 10, 3, 900_000, Status.ACTIVE, 100, 150);
	}

	@Test
	public void offerJson()
	{
		assertEquals(OFFER_JSON, gson.toJson(TradeUploader.offerJson(2, slot())));
	}

	@Test
	public void submitBody()
	{
		TradeEvent ev = TradeEvent.builder()
			.id("k1:placed")
			.kind(TradeEvent.PLACED)
			.side(TradeEvent.SELL)
			.itemId(4151)
			.qty(10)
			.price(300_000)
			.slot(2)
			.offerKey("k1")
			.ts(100)
			.late(false)
			.world(345)
			.name("Abyssal whip")
			.build();
		TradeUploader.ItemInfo whip = new TradeUploader.ItemInfo(4151, "Abyssal whip");
		whip.icon = "AAAA";
		TradeUploader.ItemInfo shark = new TradeUploader.ItemInfo(385, "Shark");

		JsonObject body = TradeUploader.buildBody(gson, "install-1", new TradeUploader.BatchKey(345, null), 1234, Collections.singletonList(ev),
			Collections.singletonList(TradeUploader.offerJson(2, slot())), Arrays.asList(whip, shark));

		assertEquals("{\"installId\":\"install-1\",\"world\":345,\"sentAt\":1234,\"events\":[{\"id\":\"k1:placed\","
			+ "\"kind\":\"placed\",\"side\":\"sell\",\"itemId\":4151,\"qty\":10,\"price\":300000,\"slot\":2,\"offerKey\":\"k1\","
			+ "\"ts\":100,\"late\":false,\"world\":345,\"name\":\"Abyssal whip\"}],\"offers\":[" + OFFER_JSON + "],"
			+ "\"items\":[{\"id\":4151,\"name\":\"Abyssal whip\",\"icon\":\"AAAA\"},{\"id\":385,\"name\":\"Shark\"}]}",
			gson.toJson(body));
	}

	@Test
	public void submitBodyWithoutOpenOffers()
	{
		JsonObject body = TradeUploader.buildBody(gson, "install-1", new TradeUploader.BatchKey(345, null), 1234, Collections.emptyList(), null,
			Collections.emptyList());
		assertEquals("{\"installId\":\"install-1\",\"world\":345,\"sentAt\":1234,\"events\":[],\"items\":[]}", gson.toJson(body));
	}

	@Test
	public void submitBodyAppendsAccountIdLast()
	{
		JsonObject body = TradeUploader.buildBody(gson, "install-1", new TradeUploader.BatchKey(345, "abc123"), 1234,
			Collections.emptyList(), null, Collections.emptyList());
		assertEquals("{\"installId\":\"install-1\",\"world\":345,\"sentAt\":1234,\"events\":[],\"items\":[],"
			+ "\"accountId\":\"abc123\"}", gson.toJson(body));
	}

	@Test
	public void itemLimitOnlyWhenKnownAndLast()
	{
		TradeUploader.ItemInfo whip = new TradeUploader.ItemInfo(4151, "Abyssal whip", 70);
		whip.icon = "AAAA";
		TradeUploader.ItemInfo shark = new TradeUploader.ItemInfo(385, "Shark", 0);
		TradeUploader.ItemInfo bones = new TradeUploader.ItemInfo(536, "Dragon bones", 7500);
		JsonObject body = TradeUploader.buildBody(gson, "install-1", new TradeUploader.BatchKey(345, null), 1234,
			Collections.emptyList(), null, Arrays.asList(whip, shark, bones));
		assertEquals("{\"installId\":\"install-1\",\"world\":345,\"sentAt\":1234,\"events\":[],\"items\":["
			+ "{\"id\":4151,\"name\":\"Abyssal whip\",\"icon\":\"AAAA\",\"limit\":70},"
			+ "{\"id\":385,\"name\":\"Shark\"},"
			+ "{\"id\":536,\"name\":\"Dragon bones\",\"limit\":7500}]}", gson.toJson(body));
	}
}

