 */
public class WireFormatTest
{
	private final Gson gson = new Gson();

	private static TradeEvent fullEvent()
	{
		return TradeEvent.builder()
			.id("k1:fill:3")
			.kind(TradeEvent.FILL)
			.side("buy")
			.itemId(4151)
			.qty(3)
