	@Test
	public void kindValues()
	{
		assertEquals("placed", TradeEvent.PLACED);
		assertEquals("fill", TradeEvent.FILL);
		assertEquals("cancelled", TradeEvent.CANCELLED);
		assertEquals("history", TradeEvent.HISTORY);
