	@Test
	public void sectionVisibility()
	{
		assertFalse(ProfitSection.visible(null));
		assertFalse(ProfitSection.visible(ProfitSnapshot.EMPTY));
		// No numbers yet, but a log a rebuild could count.
		assertTrue(ProfitSection.visible(snapshot(0, 0, 0, false, true)));
		assertTrue(ProfitSection.visible(snapshot(0, 0, 0, false, false, item(1, 1, 1, 0, 0, 0, 0))));
	}

	private static List<Component> all(Container c)
	{
		List<Component> out = new ArrayList<>();
		for (Component ch : c.getComponents())
		{
			out.add(ch);
			if (ch instanceof Container)
			{
				out.addAll(all((Container) ch));
			}
		}
		return out;
	}

	private static JButton button(ProfitSection s)
	{
		for (Component c : all((Container) s.getComponent()))
		{
			if (c instanceof JButton)
			{
				return (JButton) c;
			}
		}
		throw new AssertionError("no button");
	}

	@Test
	public void sectionRendersOnlyOnChangeAndRebuildButtonStates()
	{
		AtomicInteger rebuilds = new AtomicInteger();
		ProfitSection s = new ProfitSection(rebuilds::incrementAndGet, (id, name) ->
		{
		});
		assertFalse(s.getComponent().isVisible());
		ProfitSnapshot snap = snapshot(1_000, 0, 0, false, true, item(1, 0, 0, 1_000, 0, 0, 0));
		s.setSnapshot(snap);
		assertTrue(s.getComponent().isVisible());
		List<Component> before = all((Container) s.getComponent());
		s.setSnapshot(snapshot(1_000, 0, 0, false, true, item(1, 0, 0, 1_000, 0, 0, 0)));
		s.tick();
		List<Component> after = all((Container) s.getComponent());
		assertEquals(before.size(), after.size());
		for (int i = 0; i < before.size(); i++)
		{
			assertSame(before.get(i), after.get(i));
		}

		JButton b = button(s);
		assertTrue(b.isEnabled());
		b.doClick();
		assertEquals(1, rebuilds.get());
		assertFalse(b.isEnabled());
		assertEquals("Rebuilding…", b.getText());
		s.setSnapshot(snapshot(1_000, 0, 0, true, true, item(1, 0, 0, 1_000, 0, 0, 0)));
		assertFalse(b.isEnabled());
		s.setSnapshot(snap);
		assertTrue(b.isEnabled());
		assertEquals("Rebuild", b.getText());

		s.setLogEnabled(false);
		assertFalse(b.isEnabled());
		assertEquals(ProfitText.REBUILD_NEEDS_LOG, b.getToolTipText());
	}
}

package com.deadmantoolkit.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.awt.Component;
import java.awt.Container;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import org.junit.Test;

public class RowListTest
{
	/** How many times the factory built each item. */
	private final Map<String, Integer> built = new HashMap<>();
	private final Map<String, String> versions = new HashMap<>();

	private RowList<String> list()
	{
		return new RowList<>(s -> s, s -> versions.getOrDefault(s, ""), s ->
		{
			built.merge(s, 1, Integer::sum);
			return new JLabel(s);
		});
	}

	private static List<String> items(int n)
	{
		List<String> out = new ArrayList<>();
		for (int i = 0; i < n; i++)
		{
			out.add("r" + i);
		}
		return out;
	}

	/** The row components on screen, in order (each row sits in a wrapper with its spacing). */
	private static List<Component> rows(RowList<?> l)
	{
		List<Component> out = new ArrayList<>();
		for (Component c : l.getComponent().getComponents())
		{
			if (c instanceof Container && ((Container) c).getComponentCount() > 0 && !(c instanceof JButton)
				&& ((Container) c).getComponent(0) instanceof JLabel)
			{
				out.add(((Container) c).getComponent(0));
			}
		}
		return out;
	}

	private static List<String> texts(RowList<?> l)
	{
		return rows(l).stream().map(c -> ((JLabel) c).getText()).collect(Collectors.toList());
	}

	private static JButton moreButton(RowList<?> l)
	{
		for (Component c : l.getComponent().getComponents())
		{
			if (c instanceof JButton)
			{
				return (JButton) c;
			}
		}
		return null;
	}

	@Test
	public void factoryRunsOncePerNewKey()
	{
		RowList<String> l = list();
		l.setItems(Arrays.asList("a", "b"));
		l.setItems(Arrays.asList("c", "a", "b"));
		assertEquals(Arrays.asList("c", "a", "b"), texts(l));
		assertEquals(Integer.valueOf(1), built.get("a"));
		assertEquals(Integer.valueOf(1), built.get("b"));
		assertEquals(Integer.valueOf(1), built.get("c"));
	}

	@Test
	public void identicalInputChangesNothing()
	{
		RowList<String> l = list();
		l.setItems(Arrays.asList("a", "b"));
		Component[] before = l.getComponent().getComponents();
		l.setItems(new ArrayList<>(Arrays.asList("a", "b")));
		Component[] after = l.getComponent().getComponents();
		assertEquals(before.length, after.length);
		for (int i = 0; i < before.length; i++)
		{
			assertSame(before[i], after[i]);
		}
	}

	@Test
	public void changedVersionRebuildsOnlyThatRow()
	{
		RowList<String> l = list();
		l.setItems(Arrays.asList("a", "b"));
		Component a = rows(l).get(0), b = rows(l).get(1);
		versions.put("b", "6m");
		l.setItems(Arrays.asList("a", "b"));
		assertSame(a, rows(l).get(0));
		assertNotSame(b, rows(l).get(1));
		assertEquals(Integer.valueOf(2), built.get("b"));
		// A rebuilt row isn't new: no highlight.
		assertFalse(RowList.HIGHLIGHT.equals(rows(l).get(1).getBackground()));
	}

	@Test
	public void showMoreGrowsByAPage()
	{
		RowList<String> l = list();
		l.setItems(items(120));
		assertEquals(RowList.PAGE, rows(l).size());
		assertEquals("Show more (70 more)", moreButton(l).getText());
		moreButton(l).doClick();
		assertEquals(100, rows(l).size());
		assertEquals("Show more (20 more)", moreButton(l).getText());
		moreButton(l).doClick();
		assertEquals(120, rows(l).size());
		assertEquals(null, moreButton(l));
		// The first rows were built once, never again.
		assertEquals(Integer.valueOf(1), built.get("r0"));

		l.reset();
		l.setItems(items(120));
		assertEquals(RowList.PAGE, rows(l).size());
	}

	@Test
	public void rowsNotVisibleAreNotBuilt()
	{
		RowList<String> l = list();
		l.setItems(items(1000));
		assertEquals(RowList.PAGE, built.size());
	}

	@Test
	public void newRowsAreHighlightedButNotOnTheFirstRender()
	{
		RowList<String> l = list();
		l.setItems(Arrays.asList("a", "b"));
		for (Component c : rows(l))
		{
			assertFalse(RowList.HIGHLIGHT.equals(c.getBackground()));
		}
		l.setItems(Arrays.asList("c", "a", "b"));
		assertEquals(RowList.HIGHLIGHT, rows(l).get(0).getBackground());
		assertFalse(RowList.HIGHLIGHT.equals(rows(l).get(1).getBackground()));

		// After a reset (tab or item change) nothing counts as new.
		l.reset();
		l.setItems(Arrays.asList("d", "c", "a", "b"));
		assertFalse(RowList.HIGHLIGHT.equals(rows(l).get(0).getBackground()));
		l.stop();
	}

	@Test
	public void anEmptyRenderIsNoBaselineForHighlighting()
	{
		RowList<String> l = list();
		// What a reset feed or a logged-out offers list does: empty first, then the first real load.
		l.setItems(Collections.emptyList());
		l.reset();
		l.setItems(Collections.emptyList());
		l.setItems(Arrays.asList("a", "b"));
		for (Component c : rows(l))
		{
			assertFalse(RowList.HIGHLIGHT.equals(c.getBackground()));
		}
		l.stop();
	}

	@Test
	public void emptyShowsTheMessage()
	{
		RowList<String> l = list();
		l.setEmptyText("Nothing here");
		l.setItems(Collections.emptyList());
		assertEquals(1, l.getComponent().getComponentCount());
		assertEquals("Nothing here", ((javax.swing.text.JTextComponent) l.getComponent().getComponent(0)).getText());
		l.setItems(Collections.singletonList("a"));
		assertEquals(Collections.singletonList("a"), texts(l));
		assertEquals(1, l.getComponent().getComponentCount());
	}

	@Test
	public void newKeys()
	{
		assertEquals(new HashSet<>(Arrays.asList("c", "d")),
			RowList.newKeys(Arrays.asList("a", "b"), Arrays.asList("c", "a", "d")));
		assertTrue(RowList.newKeys(Arrays.asList("a"), Arrays.asList("a")).isEmpty());
	}

	@Test
	public void occurrenceKeysStayUnique()
	{
		List<RowList.Keyed<String>> keyed = RowList.withOccurrenceKeys(Arrays.asList("x", "y", "x"), s -> s);
		assertEquals(Arrays.asList("x|1", "y|1", "x|2"), keyed.stream().map(k -> k.key).collect(Collectors.toList()));
		assertEquals("x", keyed.get(2).value);
	}

	@Test
	public void rowsKeepTheirComponentsAcrossReorder()
	{
		RowList<String> l = list();
		l.setItems(Arrays.asList("a", "b", "c"));
		JComponent b = (JComponent) rows(l).get(1);
		l.setItems(Arrays.asList("b", "c"));
		assertSame(b, rows(l).get(0));
	}
}

package com.deadmantoolkit.ui;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import org.junit.Test;

public class TimeTicksTest
{
	private static final ZoneId UTC = ZoneOffset.UTC;
	private static final ZoneId NEW_YORK = ZoneId.of("America/New_York");

	private static long ts(String iso)
	{
		return Instant.parse(iso).getEpochSecond();
	}

	private static void ascendingInRange(TimeTicks t, long t0, long t1)
	{
		for (int i = 0; i < t.ts.length; i++)
		{
			assertTrue(t.ts[i] >= t0 && t.ts[i] <= t1);
			if (i > 0)
			{
				assertTrue(t.ts[i] > t.ts[i - 1]);
			}
		}
	}

	@Test
	public void dayRangeUsesHoursAtLeastThreeApart()
	{
		long t1 = ts("2026-10-07T12:30:00Z"), t0 = t1 - 86_400;
		TimeTicks t = TimeTicks.of(t0, t1, ChartRange.H24, UTC, 8);
		assertArrayEquals(new String[]{"15:00", "18:00", "21:00", "00:00", "03:00", "06:00", "09:00", "12:00"}, t.labels);
		ascendingInRange(t, t0, t1);
		for (int i = 1; i < t.ts.length; i++)
		{
			assertTrue(t.ts[i] - t.ts[i - 1] >= 3 * 3600);
		}
		// Less room: every 6 hours.
		assertArrayEquals(new String[]{"18:00", "00:00", "06:00", "12:00"}, TimeTicks.of(t0, t1, ChartRange.H24, UTC, 4).labels);
	}

	@Test
	public void dayRangeInLocalTime()
	{
		long t1 = ts("2026-10-07T12:30:00Z"), t0 = t1 - 86_400;
		TimeTicks t = TimeTicks.of(t0, t1, ChartRange.H24, NEW_YORK, 4);
		// 12:30 UTC is 08:30 in New York (EDT).
		assertArrayEquals(new String[]{"12:00", "18:00", "00:00", "06:00"}, t.labels);
		ascendingInRange(t, t0, t1);
	}

	@Test
	public void weekUsesWeekdays()
	{
		long t1 = ts("2026-10-07T12:00:00Z"), t0 = t1 - 7 * 86_400;
		TimeTicks t = TimeTicks.of(t0, t1, ChartRange.D7, UTC, 10);
		assertArrayEquals(new String[]{"Thu", "Fri", "Sat", "Sun", "Mon", "Tue", "Wed"}, t.labels);
		assertEquals(ts("2026-10-01T00:00:00Z"), t.ts[0]);
		assertTrue(TimeTicks.of(t0, t1, ChartRange.D7, UTC, 4).ts.length <= 4);
	}

	@Test
	public void monthUsesMondays()
	{
		long t1 = ts("2026-10-07T12:00:00Z"), t0 = t1 - 30 * 86_400;
		TimeTicks t = TimeTicks.of(t0, t1, ChartRange.D30, UTC, 6);
		assertArrayEquals(new String[]{"14 Sep", "21 Sep", "28 Sep", "5 Oct"}, t.labels);
	}

	@Test
	public void quarterEveryFewWeeks()
	{
		long t1 = ts("2026-10-07T12:00:00Z"), t0 = t1 - 90 * 86_400;
		TimeTicks t = TimeTicks.of(t0, t1, ChartRange.D90, UTC, 5);
		assertTrue(t.ts.length >= 2 && t.ts.length <= 5);
		for (int i = 1; i < t.ts.length; i++)
		{
			long gap = t.ts[i] - t.ts[i - 1];
			assertTrue(gap >= 14 * 86_400 && gap % (7 * 86_400) == 0);
		}
		ascendingInRange(t, t0, t1);
	}

	@Test
	public void yearUsesMonths()
	{
		long t1 = ts("2026-10-07T12:00:00Z"), t0 = t1 - 365 * 86_400;
		TimeTicks t = TimeTicks.of(t0, t1, ChartRange.Y1, UTC, 12);
		assertArrayEquals(new String[]{"Nov", "Dec", "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct"},
			t.labels);
		assertEquals(ts("2025-11-01T00:00:00Z"), t.ts[0]);
		assertArrayEquals(new String[]{"Jan", "Apr", "Jul", "Oct"}, TimeTicks.of(t0, t1, ChartRange.Y1, UTC, 4).labels);
	}

	@Test
	public void maxLabelsIsRespected()
	{
		long t1 = ts("2026-10-07T12:00:00Z");
		for (ChartRange r : ChartRange.values())
		{
			for (int max = 1; max <= 12; max++)
			{
				TimeTicks t = TimeTicks.of(t1 - r.seconds(), t1, r, NEW_YORK, max);
				assertTrue(r + " " + max + ": " + t.ts.length, t.ts.length <= max);
				assertEquals(t.ts.length, t.labels.length);
			}
			assertEquals(0, TimeTicks.of(t1 - r.seconds(), t1, r, UTC, 0).ts.length);
		}
	}

	@Test
	public void acrossDaylightSavingChange()
	{
		// New York leaves DST on 1 Nov 2026 at 02:00 local.
		long t1 = ts("2026-11-01T18:00:00Z"), t0 = t1 - 86_400;
		TimeTicks t = TimeTicks.of(t0, t1, ChartRange.H24, NEW_YORK, 8);
		ascendingInRange(t, t0, t1);
		for (String label : t.labels)
		{
			assertTrue(label, Integer.parseInt(label.substring(0, 2)) % 3 == 0 && label.endsWith(":00"));
		}
	}
}

package com.deadmantoolkit.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.deadmantoolkit.Onboarding;
import java.awt.Component;
import java.awt.Container;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.AbstractButton;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import javax.swing.text.JTextComponent;
import org.junit.Test;

public class WelcomeCardTest
{
	private final AtomicInteger connects = new AtomicInteger();
	private final AtomicInteger dismissed = new AtomicInteger();

	private static Container card(WelcomeCard c)
	{
		return (Container) ((Container) c.getComponent()).getComponent(0);
	}

	private static String allText(Component c)
	{
		StringBuilder sb = new StringBuilder();
		if (c instanceof JLabel)
		{
			sb.append(((JLabel) c).getText()).append('\n');
		}
		else if (c instanceof JTextComponent)
		{
			sb.append(((JTextComponent) c).getText()).append('\n');
		}
		else if (c instanceof AbstractButton)
		{
			sb.append('[').append(((AbstractButton) c).getText()).append("]\n");
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				sb.append(allText(child));
			}
		}
		return sb.toString();
	}

	private static AbstractButton button(Component c, String text)
	{
		if (c instanceof AbstractButton && text.equals(((AbstractButton) c).getText()))
		{
			return (AbstractButton) c;
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				AbstractButton b = button(child, text);
				if (b != null)
				{
					return b;
				}
			}
		}
		return null;
	}

	@Test
	public void states() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			boolean[] answer = {false};
			int[] asked = {0};
			WelcomeCard c = new WelcomeCard(connects::incrementAndGet, () -> { }, dismissed::incrementAndGet, null, parent ->
			{
				asked[0]++;
				return answer[0];
			});
			assertFalse(c.getComponent().isVisible());

			c.update(Onboarding.Step.CONNECT_AND_IMPORT, true, null);
			assertTrue(c.getComponent().isVisible());
			String text = allText(c.getComponent());
			assertTrue(text, text.contains("[Connect]"));
			assertTrue(text, text.contains(WelcomeCard.SHARED_TEXT));
			// RuneLite's warning is a confirmation on Connect now, not text on the card.
			assertFalse(text, text.contains("submits your IP address to a 3rd-party server"));
			assertFalse(WelcomeCard.SHARED_TEXT, WelcomeCard.SHARED_TEXT.contains("your IP address"));
			assertTrue(WelcomeCard.SHARED_TEXT, WelcomeCard.SHARED_TEXT.contains("IP addresses are never stored"));
			assertTrue(text, text.contains("2. Click the History button."));
			assertTrue(text, text.contains("Log in on world 345 first."));

			// Same state: nothing is rebuilt.
			Component first = card(c).getComponent(0);
			c.update(Onboarding.Step.CONNECT_AND_IMPORT, true, null);
			assertSame(first, card(c).getComponent(0));

			// Declining the warning doesn't connect; accepting does.
			button(c.getComponent(), "Connect").doClick();
			assertEquals(1, asked[0]);
			assertEquals(0, connects.get());
			answer[0] = true;
			button(c.getComponent(), "Connect").doClick();
			assertEquals(2, asked[0]);
			assertEquals(1, connects.get());

			c.update(Onboarding.Step.IMPORT, false, null);
			text = allText(c.getComponent());
			assertFalse(text, text.contains("[Connect]"));
			assertFalse(text, text.contains("Log in on world 345 first."));
			assertTrue(text, text.contains("1. Open the Grand Exchange."));

			c.update(Onboarding.Step.IMPORTED_NOTICE, false, 12);
			text = allText(c.getComponent());
			assertTrue(text, text.contains("Imported 12 trades from GE History"));
			assertFalse(text, text.contains("Get started"));
			button(c.getComponent(), "x").doClick();
			assertEquals(1, dismissed.get());

			c.update(Onboarding.Step.HIDDEN, false, null);
			assertFalse(c.getComponent().isVisible());
		});
	}
}

package com.deadmantoolkit.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import com.deadmantoolkit.world.WorldEventMessage.Combat;
import com.deadmantoolkit.world.WorldEventMessage.Kind;
import org.junit.Test;

public class WorldEventMessageTest
{
	private static WorldEventMessage parse(String s)
	{
		return WorldEventMessage.parse(s).orElseThrow(() -> new AssertionError("not parsed: " + s));
	}

	@Test
	public void chestBroadcast()
	{
		WorldEventMessage m = parse("A Deadman's Chest has spawned at north of the Warriors' Guild!");
		assertEquals(Kind.CHEST, m.getKind());
		assertEquals("north of the Warriors' Guild", m.getLocation());
		assertNull(m.getCombat());
	}

	@Test
	public void tagsCurlyApostrophesAndCaseDontMatter()
	{
		WorldEventMessage m = parse("<col=ef1020>A deadman’s chest  has spawned at <col=ffffff>Zanaris</col>!</col>");
		assertEquals(Kind.CHEST, m.getKind());
		assertEquals("Zanaris", m.getLocation());
		assertEquals("Kingdom Of Asgarnia", parse("A Deadman's Chest has spawned at Kingdom Of Asgarnia.").getLocation());
	}

	@Test
	public void breachWithCombat()
	{
		WorldEventMessage m = parse("A breach has spawned at the Bone Yard! Powerful monsters now roam the area (Multi).");
		assertEquals(Kind.BREACH, m.getKind());
		assertEquals("the Bone Yard", m.getLocation());
		assertEquals(Combat.MULTI, m.getCombat());
		assertEquals(Combat.SINGLE,
			parse("A breach has spawned at Lumbridge! Powerful monsters now roam the area (Single).").getCombat());
		assertEquals(Combat.MULTI, parse("A breach has spawned at Lumbridge! It is multi-way combat.").getCombat());
	}

	@Test
	public void breachWithoutCombatOrExclamationMark()
	{
		WorldEventMessage m = parse("A breach has spawned at North of Asgarnia. Powerful monsters now roam the area.");
		assertEquals("North of Asgarnia", m.getLocation());
		assertNull(m.getCombat());
		m = parse("A breach has spawned at Varrock (Multi).");
		assertEquals("Varrock", m.getLocation());
		assertEquals(Combat.MULTI, m.getCombat());
	}

	@Test
	public void breachThroughoutAPlace()
	{
		// Seen live on world 345 (2026-10-11).
		WorldEventMessage m = parse("@mes_hl_pur@A breach has spawned throughout Zanaris! Powerful monsters now roam the area"
			+ " (Single).</col>");
		assertEquals(Kind.BREACH, m.getKind());
		assertEquals("Zanaris", m.getLocation());
		assertEquals(Combat.SINGLE, m.getCombat());
	}

	@Test
	public void otherMessagesAreIgnored()
	{
		assertFalse(WorldEventMessage.parse("The next breach will appear in 2 hours, 5 minutes.").isPresent());
		assertFalse(WorldEventMessage.parse("Welcome to Old School RuneScape.").isPresent());
		assertFalse(WorldEventMessage.parse("A Deadman's Chest has spawned at !").isPresent());
		assertFalse(WorldEventMessage.parse(null).isPresent());
		StringBuilder long_ = new StringBuilder("A Deadman's Chest has spawned at ");
		for (int i = 0; i < 100; i++)
		{
			long_.append('x');
		}
		assertFalse("absurdly long place", WorldEventMessage.parse(long_ + "!").isPresent());
	}

	@Test
	public void gameTextRoundTrips()
	{
		for (Combat c : new Combat[]{null, Combat.SINGLE, Combat.MULTI})
		{
			WorldEventMessage m = parse(WorldEventMessage.gameText(Kind.BREACH, "south of Falador", c));
			assertEquals("south of Falador", m.getLocation());
			assertEquals(c, m.getCombat());
		}
		assertEquals("Zanaris", parse(WorldEventMessage.gameText(Kind.CHEST, "Zanaris", null)).getLocation());
	}
}

package com.deadmantoolkit.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.deadmantoolkit.world.WorldEventMessage.Combat;
import com.deadmantoolkit.world.WorldEventMessage.Kind;
import com.deadmantoolkit.world.WorldLocations.Accuracy;
import com.google.gson.Gson;
import java.awt.image.BufferedImage;
import java.time.Instant;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

/** Map / minimap icons, marker labels and where the minimap points. */
public class WorldEventVisualsTest
{
	private static final Instant T = Instant.parse("2026-10-03T14:15:40Z");
	private final WorldLocations loc = WorldLocations.load(new Gson());

	private WorldEvents.Event event(Kind kind, String place, Combat combat)
	{
		return new WorldEvents.Event(kind, place, combat, T, T.plusSeconds(3600), loc.resolve(place), WorldEvents.Source.SEEN, 0);
	}

	private static int alpha(BufferedImage img, int x, int y)
	{
		return img.getRGB(x, y) >>> 24;
	}

	@Test
	public void mapIconsAreBigEnoughAndPinsPointDown()
	{
		BufferedImage pin = WorldEventIcons.pin(Kind.BREACH, Accuracy.EXACT);
		assertTrue("visible on the map", pin.getWidth() >= 26 && pin.getHeight() >= 36);
		// The pointer's tip is at the bottom centre (the spot); the bottom corners are empty.
		assertTrue(alpha(pin, pin.getWidth() / 2, pin.getHeight() - 3) > 0);
		assertEquals(0, alpha(pin, 0, pin.getHeight() - 1));
		assertTrue(WorldEventIcons.minimap(Kind.CHEST, Accuracy.EXACT).getWidth() >= 13);
		assertNotSame(WorldEventIcons.pin(Kind.CHEST, Accuracy.EXACT), WorldEventIcons.pin(Kind.CHEST, Accuracy.REGION));
	}

	@Test
	public void edgeArrowsTurnTowardsTheEvent()
	{
		assertEquals(0, WorldEventIcons.direction(0));
		assertEquals(4, WorldEventIcons.direction(Math.PI / 2));
		assertEquals(8, WorldEventIcons.direction(Math.PI));
		assertEquals(12, WorldEventIcons.direction(-Math.PI / 2));
		assertEquals(0, WorldEventIcons.direction(2 * Math.PI - 0.01));
		// Pointing right: the arrow's tip near the right edge, nothing at the same spot on the left.
		BufferedImage right = WorldEventIcons.edge(Kind.CHEST, Accuracy.EXACT, 0);
		int mid = right.getHeight() / 2;
		assertTrue(alpha(right, right.getWidth() - 3, mid) > 0);
		assertEquals(0, alpha(right, 2, mid));
		BufferedImage left = WorldEventIcons.edge(Kind.CHEST, Accuracy.EXACT, Math.PI);
		assertTrue(alpha(left, 2, mid) > 0);
		assertSame(right, WorldEventIcons.edge(Kind.CHEST, Accuracy.EXACT, 0.05));
	}

	@Test
	public void labelsSayWhatAndWhere()
	{
		assertEquals("Breach (Multi): North of Edgeville", WorldEventMarkers.label(event(Kind.BREACH, "North of Edgeville", Combat.MULTI), null));
		assertEquals("Breach (Single): North of Asgarnia (somewhere in Asgarnia)",
			WorldEventMarkers.label(event(Kind.BREACH, "North of Asgarnia", Combat.SINGLE), null));
		assertEquals("Deadman's Chest: North of Edge Monastry (read as North of the Edgeville Monastery)",
			WorldEventMarkers.label(event(Kind.CHEST, "North of Edge Monastry", null), null));
		assertEquals("Breach (Single): Zanaris - enter at Lumbridge Swamp shed",
			WorldEventMarkers.label(event(Kind.BREACH, "Zanaris", Combat.SINGLE), "Lumbridge Swamp shed"));
	}

	@Test
	public void minimapPointsAtTheEntranceOfAnotherMap()
	{
		WorldPoint surface = new WorldPoint(3200, 3200, 0);
		WorldEvents.Event zanaris = event(Kind.BREACH, "Zanaris", null);
		assertEquals(zanaris.getWhere().getEntrance(), WorldEventMinimapOverlay.target(zanaris, surface));
		// Inside Zanaris itself: its spot.
		assertEquals(zanaris.getWhere().getPoint(), WorldEventMinimapOverlay.target(zanaris, new WorldPoint(2410, 4440, 0)));
		// A surface event seen from a dungeon: nothing to point at.
		WorldEvents.Event edge = event(Kind.BREACH, "North of Edgeville", null);
		assertNull(WorldEventMinimapOverlay.target(edge, new WorldPoint(3100, 9900, 0)));
		assertEquals(edge.getWhere().getPoint(), WorldEventMinimapOverlay.target(edge, surface));
		assertNull(WorldEventMinimapOverlay.target(event(Kind.CHEST, "the Whispering Glade", null), surface));
	}
}

package com.deadmantoolkit.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.deadmantoolkit.world.WorldEventMessage.Combat;
import com.deadmantoolkit.world.WorldEventMessage.Kind;
import com.deadmantoolkit.world.WorldEvents.Event;
import com.deadmantoolkit.world.WorldEvents.Source;
import com.google.gson.Gson;
import java.time.Duration;
import java.time.Instant;
import java.util.List;
import org.junit.Test;

public class WorldEventsTest
{
	private static final Instant T = Instant.parse("2026-10-03T14:15:40Z");
	private final WorldLocations loc = WorldLocations.load(new Gson());
	private final WorldEvents events = new WorldEvents();

	private boolean add(Kind kind, String place, Combat combat, Instant at, Source source, int reporters)
	{
		return events.add(new WorldEventMessage(kind, place, combat), at, loc.resolve(place), source, reporters);
	}

	@Test
	public void oneChestAtATime()
	{
		assertTrue(add(Kind.CHEST, "north of the Warriors' Guild", null, T, Source.SEEN, 0));
		assertTrue(add(Kind.CHEST, "Zanaris", null, T.plus(Duration.ofMinutes(61)), Source.SEEN, 0));
		List<Event> a = events.active();
		assertEquals(1, a.size());
		assertEquals("Zanaris", a.get(0).getLocation());
		// A late server report of the older chest doesn't bring it back.
		assertFalse(add(Kind.CHEST, "north of the Warriors' Guild", null, T, Source.REPORTED, 3));
		assertEquals("Zanaris", events.active().get(0).getLocation());
	}

	@Test
	public void chestEndsAfterTenMinutes()
	{
		add(Kind.CHEST, "Lumbridge", null, T, Source.SEEN, 0);
		assertFalse(events.expire(T.plus(Duration.ofMinutes(9))));
		assertTrue(events.expire(T.plus(Duration.ofMinutes(10))));
		assertTrue(events.active().isEmpty());
	}

	@Test
	public void repeatsAndDriftAreOneEvent()
	{
		add(Kind.CHEST, "Lumbridge", null, T, Source.REPORTED, 2);
		// Seen here a minute later (the game is not exactly on :15), worded slightly differently.
		assertTrue(add(Kind.CHEST, "lumbridge", null, T.plus(Duration.ofMinutes(1)), Source.SEEN, 0));
		Event e = events.active().get(0);
		assertEquals(T, e.getAt());
		assertEquals(Source.SEEN, e.getSource());
		assertEquals(2, e.getReporters());
		assertFalse("nothing new", add(Kind.CHEST, "Lumbridge", null, T, Source.SEEN, 0));
	}

	@Test
	public void breachWaves()
	{
		add(Kind.BREACH, "the Bone Yard", Combat.MULTI, T, Source.SEEN, 0);
		add(Kind.BREACH, "North of Asgarnia", Combat.SINGLE, T, Source.SEEN, 0);
		add(Kind.CHEST, "Lumbridge", null, T, Source.SEEN, 0);
		// The server's copy of one, without its combat note, adds nothing.
		assertFalse(add(Kind.BREACH, "The Bone Yard", null, T.plusSeconds(20), Source.SEEN, 0));
		List<Event> a = events.active();
		assertEquals(3, a.size());
		assertEquals(Kind.CHEST, a.get(0).getKind());
		assertEquals(Combat.MULTI, a.get(1).getCombat());
		// The chest goes after 10 minutes, the breaches after 45.
		assertTrue(events.expire(T.plus(WorldEvents.CHEST_LIFE)));
		assertEquals(2, events.active().size());
		assertTrue(events.expire(T.plus(WorldEvents.BREACH_LIFE)));
		assertTrue(events.active().isEmpty());
	}

	@Test
	public void sameBreachPlaceInALaterWaveIsANewBreach()
	{
		add(Kind.BREACH, "Varrock", null, T, Source.SEEN, 0);
		add(Kind.BREACH, "Varrock", null, T.plus(Duration.ofHours(4)), Source.SEEN, 0);
		assertEquals(2, events.active().size());
		events.expire(T.plus(Duration.ofHours(4)));
		assertEquals(1, events.active().size());
	}

	@Test
	public void aNewerPlaceListPlacesListedEvents()
	{
		add(Kind.CHEST, "the old shed", null, T, Source.SEEN, 0);
		assertEquals(WorldLocations.Accuracy.UNKNOWN, events.active().get(0).getWhere().getAccuracy());
		WorldPlaces.Table newer = WorldPlaces.parse(new Gson(),
			"{\"revision\": 9, \"places\": [{\"name\": \"The old shed\", \"x\": 3202, \"y\": 3169}]}");
		events.reresolve(new WorldLocations(newer));
		assertEquals(WorldLocations.Accuracy.EXACT, events.active().get(0).getWhere().getAccuracy());
	}
}

package com.deadmantoolkit.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.deadmantoolkit.world.WorldLocations.Accuracy;
import com.deadmantoolkit.world.WorldLocations.Resolved;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class WorldLocationsTest
{
	private final WorldLocations loc = WorldLocations.load(new Gson());

	private static final WorldPoint WARRIORS = new WorldPoint(2864, 3544, 0);

	@Test
	public void knownPlaceIsExactWhateverTheWording()
	{
		for (String s : new String[]{"Warriors' Guild", "the Warriors' Guild", "WARRIORS GUILD", "Warriors’ Guild",
			"at the warriors guild", "Surrounding the Warriors' Guild"})
		{
			Resolved r = loc.resolve(s);
			assertEquals(s, Accuracy.EXACT, r.getAccuracy());
			assertEquals(s, WARRIORS, r.getPoint());
			assertEquals("Warriors' Guild", r.getPlace());
		}
	}

	@Test
	public void directionMovesTheMarker()
	{
		// (Wording the place file doesn't list itself; "north of the Warriors' Guild" is a chest spot of its own.)
		Resolved r = loc.resolve("south of the Warriors' Guild");
		assertEquals(Accuracy.APPROXIMATE, r.getAccuracy());
		assertEquals(new WorldPoint(2864, 3544 - WorldLocations.NEAR, 0), r.getPoint());
		assertEquals(WorldLocations.NEAR, r.getRadius());
		assertEquals(Accuracy.EXACT, loc.resolve("north of the Warriors' Guild").getAccuracy());

		r = loc.resolve("South-West of Lumbridge");
		assertTrue(r.getPoint().getX() < 3222 && r.getPoint().getY() < 3218);
		r = loc.resolve("east of the GE");
		assertEquals(3165 + WorldLocations.NEAR, r.getPoint().getX());
		// A direction inside longer wording.
		r = loc.resolve("the old ruins west of the Bone Yard");
		assertEquals(Accuracy.APPROXIMATE, r.getAccuracy());
		assertEquals(3236 - WorldLocations.NEAR, r.getPoint().getX());
	}

	@Test
	public void regionsAndKingdoms()
	{
		Resolved center = loc.resolve("Kingdom Of Asgarnia");
		assertEquals(Accuracy.REGION, center.getAccuracy());
		assertEquals("Asgarnia", center.getPlace());
		assertTrue(center.getRadius() > 50);

		Resolved north = loc.resolve("North of Asgarnia");
		assertEquals(Accuracy.REGION, north.getAccuracy());
		assertTrue(north.getPoint().getY() > center.getPoint().getY());
		assertEquals(center.getPoint().getX(), north.getPoint().getX());

		// A part of a kingdom the file doesn't list (the southern one is a regional breach of its own).
		Resolved east = loc.resolve("The eastern Asgarnian kingdom");
		assertEquals("Asgarnia", east.getPlace());
		assertTrue(east.getPoint().getX() > center.getPoint().getX());
		assertEquals("The southern Asgarnian Kingdom", loc.resolve("the southern asgarnian kingdom").getPlace());

		assertEquals("Misthalin", loc.resolve("Throughout Misthalin").getPlace());
		assertEquals("Wilderness", loc.resolve("Within the Wilderness").getPlace());
		assertEquals("Kandarin", loc.resolve("northern Kandarin").getPlace());
		assertTrue(loc.resolve("northern Kandarin").getPoint().getY() > loc.resolve("Kandarin").getPoint().getY());
	}

	@Test
	public void leadWordsAreDropped()
	{
		// Wording the file doesn't list as a spot of its own.
		assertEquals("White Wolf Mountain", loc.resolve("Surrounding White Wolf Mountain").getPlace());
		assertEquals("Barrows", loc.resolve("Within the Barrows").getPlace());
		assertEquals(Accuracy.EXACT, loc.resolve("Within the Barrows").getAccuracy());
		assertEquals("Lumbridge", loc.resolve("near Lumbridge").getPlace());
		// Listed wording is its own spot.
		assertEquals("On top of White Wolf Mountain", loc.resolve("On top of White Wolf Mountain").getPlace());
	}

	@Test
	public void theGamesOwnNamesForPlaces()
	{
		// Seen live: "A Deadman's Chest has spawned at within the Fremennik Slayer Cave!" (it used to land on the
		// Fremennik region, the only name the matcher found in it) and "... at at the Tasakaal entrance!".
		Resolved r = loc.resolve("within the Fremennik Slayer Cave");
		assertEquals("Fremennik Slayer Dungeon", r.getPlace());
		assertEquals(Accuracy.EXACT, r.getAccuracy());
		assertEquals(new WorldPoint(2797, 3615, 0), r.getPoint());
		r = loc.resolve("at the Tasakaal entrance");
		assertEquals("Karuulm Slayer Dungeon", r.getPlace());
		assertEquals(Accuracy.EXACT, r.getAccuracy());
		// "... at within the Chicken Shrine!": in Zanaris, near its original entrance.
		r = loc.resolve("within the Chicken Shrine");
		assertEquals("Chicken Shrine", r.getPlace());
		assertEquals(Accuracy.EXACT, r.getAccuracy());
	}

	@Test
	public void otherMapsHaveASurfaceEntrance()
	{
		Resolved r = loc.resolve("Zanaris");
		assertEquals(Accuracy.EXACT, r.getAccuracy());
		assertNotNull(r.getEntrance());
		assertEquals("Lumbridge Swamp shed", r.getEntranceName());
		assertTrue("Zanaris is off the surface map", r.getPoint().getY() > 4000);
		assertNotNull(loc.resolve("the Mole Hole").getEntrance());
		assertNull(loc.resolve("Lumbridge").getEntrance());
	}

	@Test
	public void unknownPlaces()
	{
		for (String s : new String[]{"Nowhere-in-particular", "", "the", "north of nowhere", "ge"})
		{
			Resolved r = loc.resolve(s);
			if ("ge".equals(s))
			{
				// A short alias on its own is fine...
				assertEquals("Grand Exchange", r.getPlace());
				continue;
			}
			assertEquals(s, Accuracy.UNKNOWN, r.getAccuracy());
			assertFalse(r.known());
		}
		// ...but never matched inside other words.
		assertEquals(Accuracy.UNKNOWN, loc.resolve("the edge of the gem rocks").getAccuracy());
	}

	@Test
	public void aDownloadedPlaceListIsBounded()
	{
		String json = "{\"revision\": 5, \"places\": ["
			+ "{\"name\": \"<col=ff0000>Shed</col>\", \"x\": 3202, \"y\": 3169},"
			+ "{\"name\": \"Off the map\", \"x\": 99999, \"y\": 3169},"
			+ "{\"name\": \"Bad plane\", \"x\": 3000, \"y\": 3000, \"plane\": 9},"
			+ "{\"name\": \"" + new String(new char[200]).replace('\0', 'x') + "\", \"x\": 3000, \"y\": 3000},"
			+ "{\"name\": \"Huge\", \"x\": 3000, \"y\": 3000, \"radius\": 100000}"
			+ "]}";
		WorldPlaces.Table t = WorldPlaces.parse(new Gson(), json);
		assertEquals(2, t.getPlaces().size());
		assertEquals("Shed", t.getPlaces().get(0).getName());
		assertEquals(WorldPlaces.MAX_RADIUS, t.getPlaces().get(1).getRadius());
		assertNull(WorldPlaces.parse(new Gson(), "not json"));
	}

	@Test
	public void everyNameAndAliasResolvesToItsOwnPlace()
	{
		for (WorldPlaces.Place p : loc.places())
		{
			assertEquals(p.getName(), p.getName(), loc.resolve(p.getName()).getPlace());
			for (String a : p.getAliases())
			{
				assertEquals(a, p.getName(), loc.resolve(a).getPlace());
			}
		}
	}

	@Test
	public void broadcastWordingOfKnownSpotsIsExact()
	{
		// A chest spot named after the bank is the chest's tile, not the bank's.
		Resolved r = loc.resolve("Outside the Al-Kharid bank");
		assertEquals(Accuracy.EXACT, r.getAccuracy());
		assertEquals(new WorldPoint(3273, 3160, 0), r.getPoint());
		assertEquals(new WorldPoint(3229, 3650, 0), loc.resolve("North of the Chaos Temple").getPoint());
		// A regional breach: its own spawn area, not a guess from "southern".
		r = loc.resolve("The southern Asgarnian Kingdom");
		assertEquals(Accuracy.REGION, r.getAccuracy());
		assertEquals(new WorldPoint(2984, 3249, 0), r.getPoint());
		// Underground spots keep their surface entrance.
		assertNotNull(loc.resolve("North in the Dwarven Mine").getEntrance());
	}

	@Test
	public void theCompassSpellingAndAbbreviationsDontMatter()
	{
		// Without "the": still the chest spot by the monastery (not 24 tiles north of Edgeville).
		Resolved r = loc.resolve("North of Edgeville Monastry");
		assertEquals("North of the Edgeville Monastery", r.getPlace());
		assertEquals(new WorldPoint(3045, 3512, 0), r.getPoint());
		assertFalse(r.isFuzzy());
		// One-word compass spellings.
		assertEquals(loc.resolve("North-west of the Al Kharid mine").getPlace(),
			loc.resolve("Northwest of the Al-Kharid Mine").getPlace());
		assertFalse(loc.resolve("Northwest of the Al-Kharid Mine").isFuzzy());
	}

	@Test
	public void nearSpellingsOfAWholeName()
	{
		// "Edge" for Edgeville, and "Monastry": read as the chest spot, flagged, reported as approximate.
		Resolved r = loc.resolve("North of Edge Monastry");
		assertEquals("North of the Edgeville Monastery", r.getPlace());
		assertEquals(new WorldPoint(3045, 3512, 0), r.getPoint());
		assertEquals(Accuracy.EXACT, r.getAccuracy());
		assertTrue(r.isFuzzy());
		assertEquals(Accuracy.APPROXIMATE, r.reported());
		// A direction from a misspelled place: that place, moved.
		r = loc.resolve("south of edge monastery");
		assertEquals("Edgeville Monastery", r.getPlace());
		assertEquals(Accuracy.APPROXIMATE, r.getAccuracy());
		assertTrue(r.isFuzzy());
		assertEquals(3490 - WorldLocations.NEAR, r.getPoint().getY());
		assertEquals("Lumbridge", loc.resolve("Lumbrdige").getPlace());
		// Compass words are never guessed: south is not north.
		assertEquals(3544 - WorldLocations.NEAR, loc.resolve("south of the Warriors Guild").getPoint().getY());
		// A lone short word isn't enough to guess from.
		assertFalse(loc.resolve("edge").known());
	}

	@Test
	public void wordScores()
	{
		assertEquals(3, WorldLocations.wordScore("guild", "guild"));
		assertEquals(2, WorldLocations.wordScore("edge", "edgeville"));
		assertEquals(1, WorldLocations.wordScore("monastry", "monastery"));
		assertEquals(1, WorldLocations.wordScore("lumbrdige", "lumbridge"));
		assertEquals(0, WorldLocations.wordScore("north", "south"));
		assertEquals(0, WorldLocations.wordScore("east", "west"));
		assertEquals(0, WorldLocations.wordScore("mine", "mind"));
		assertEquals(0, WorldLocations.wordScore("ge", "gem"));
		assertEquals(0, WorldLocations.wordScore("level", "level2"));
	}

	@Test
	public void twoEqualGuessesAreNoGuess()
	{
		WorldPlaces.Table t = new WorldPlaces.Table(1, Arrays.asList(
			place("Grove Hill", 3000, 3000), place("Grave Hill", 3100, 3100),
			place("Alpha Fort", 3200, 3200), place("Alpha Fortress", 3300, 3300)),
			Collections.emptyList(), Collections.emptyList());
		WorldLocations l = new WorldLocations(t);
		// One letter off both: no guess.
		assertFalse(l.resolve("Grive Hill").known());
		assertEquals("Grove Hill", l.resolve("Grovee Hill").getPlace());
		// A shortening beats a name with letters added.
		assertEquals("Alpha Fortress", l.resolve("Alpha Fortres").getPlace());
	}

	private static WorldPlaces.Place place(String name, int x, int y)
	{
		return new WorldPlaces.Place(name, Collections.emptyList(), new WorldPoint(x, y, 0), false, 8, null, null);
	}

	@Test
	public void tableHasNoClashingNames()
	{
		Set<String> seen = new HashSet<>();
		for (WorldPlaces.Place p : loc.places())
		{
			// Compared the way the resolver matches (no "the", compass words split).
			assertTrue("duplicate name " + p.getName(), seen.add(WorldLocations.matchKey(p.getName())));
			for (String a : p.getAliases())
			{
				assertTrue("alias clashes: " + a, seen.add(WorldLocations.matchKey(a)));
			}
			WorldPoint w = p.getPoint();
			// The game world, surface (Sailing islands reach y 2200) and underground (y up to about 10400).
			assertTrue(p.getName(), w.getX() > 1000 && w.getX() < 4200 && w.getY() > 2000 && w.getY() < 12800);
		}
	}
}
